window.__D("text/maamarei-admur-haemtzai/c002",{"p":[[1900740335,"הגבוה והשני עומד בגיא עמוק והם שני אוהבים בתכלית ורוצים להתייחד במקום א', אזי יש שני אופנים באופן היחוד או שהתחתון יעלה למעלה ולמעלה יתייחדו או שהעליון ירד למטה. והנה אם העליון יבא למטה א\"צ לזה הכנת התחתון כלל וא\"צ להזדככות לבושי' של העליון אחר שהוא בא למטה, אבל אם התחתון יעלה צריך להזדכך הלבושים שלו וגם עוד זאת המניעה שאין ברור לו אופני ההילוך. והנה כמו\"כ יובן בעבודת ה' שאם יהי' תלוי המשכות אלקות ע\"י אתעלד\"ת ע\"ז כתיב מי יעלה בהר ה' נקי כפים ובר לבב אשר לא נשא לשוא נפשו, ג' תנאים, הא' הוא נקי כפים ואין הפי' שיהי' נקי מגזל דייקא אלא כל בחי' פו\"מ שהוא סו\"מ וע\"ט נק' בשם נקי כפים. ובר לבב הוא בחי' נקיון הלב שיכול להיות שיתפעל מאלקות לפי שעה ואח\"כ יתפעל מההיפוך, זה אין נק' בשם בר לבב דהיינו שההתפעלות מאלקות כזו אין נק' בשם בר לבב כי הלא שקר בנפשו אחר שתיכף נתפעל מההיפוך, אלא בחי' בר לבב הוא ההתפעלות תמידי' שבלתי יופסק. ואשר לא נשא לשוא נפשו הוא שלא נשא לשוא הרצון שלו, כי נפש נק' בשם רצון כמ\"ש אין נפשי אל העם כו', דהיינו שלא יהי' לו רצון אחר זולת לה' לבדו כמ\"ש מי לי בשמים ועמך לא חפצתי בארץ. ומי שיש בו דייקא ג' בחי' אלו הוא יעלה כו' כמ\"ש מי יעלה שכשתלוי בענין העלאה אזי צ\"ל נקי כפים כו' ואח\"כ הוא ישא ברכה מאת הוי' בחי' המשכת אלקות למטה, ובאמת אין זה שכיח כלל כמ\"ש מי יעלה כו'. ומשה הי' רעיא מהימנא והי' אוהב אמיתי לישראל ורצה שיהי' גילוי אלקות מצד עצמו.\n<b>ובכלל</b> הוא ענין תורה ותפלה, כי התפלה הוא בחי' העלאה מלמטה למעלה כמ\"ש מתי אבא ואראה כו' כי התפלה הוא בחי' העתקה והזזה ממעמדו ומצבו (בל\"א צו רירט פון זיין ארט כו'), אבל התורה הוא המשכת אלקות מלמעלה למטה בלי שום התעוררות כלל, כי לימוד התורה א\"צ כוונה"],[1900740336,"פנימי' רק שילמוד לשם ה' ולא להתייהר ולגרמי' כו'. וזהו ענין דרב יהודה לא הי' מצלי אלא מתלתין יומין לתלתין יומין, כי התפלה הוא בחי' הזדככות והגוף שלו הי' מזוכך וכמו ר\"י הנשיא שהי' מעביר ידיו על עיניו לבד ולא הי' צריך להאריך כ\"כ בתפלה בכדי לזכך הגוף כי הם היו מזוככים היטב, אבל אנו צריכים להתפלל בכל יום כדי לזכך הגוף ולבושיו כו'. וז\"ש ושם דרך כו' וארז\"ל השם אורחותיו שהוא ענין התפלה שהוא לדקדק על עצמו בכל פרט עד שכל חוט השערה נדמה לו כהר ומואס בחייו כו'. אבל תורה הוא המשכה מלמעלה בלי העלאה כלל, וכמו שנראה שיש בנ\"א שאין מדקדקין על עצמם כלל רק כמ\"ש כל דרכי איש זך בעיניו, כי אין אדם רואה חוב לעצמו והוא כשר וישר בעיניו בכל פרטיו, ומ\"מ רוצה שיומשך בו גילוי אלקות ע\"י תורה כמ\"ש קרבת אלקים לי טוב כו'. וזהו בקשת משה שיהי' המשכת אלקות מלמעלה למטה ע\"י תורה בלתי העלאה כי משה הי' רעיא מהימנא וביקש טובתם כנ\"ל.\n<b>וזהו</b> ואתחנן אל ה' בעת ההיא לאמר, שיהי' התגלות אלקות ע\"י לימוד התורה בדיבור בפה, וזהו לאמר כי יש ב' מצות בתורה הגיון ודיבור ודייקא ע\"י לימוד התורה בדיבור הוא המשכת אלקות למטה. ומ\"ש בעת ההיא, הנה עת הוא בחי' מל' שנק' בשם דיבור כמ\"ש בדבר ה' שמים נעשו כו' והוא בחי' מל' דאצי' המחי' את כולם מאין ליש, וכתיב בי מלכים ימלוכו שהנהגת המלוכה הוא דייקא ע\"י הדיבור בת\"ת וכמארז\"ל שלש שעות ראשונות יושב הקב\"ה ועוסק בתורה שניות יושב ודן את כל העולם כולו שלישית יושב וזן כו', שלהיות דן את כל העולם כולו וזן כו' מקרני ראמים עד בצי כנים הכל הוא ע\"י התורה וכמ\"ש מלך במשפט יעמיד ארץ ובהמשפט צריך להיות חכמה איך ומה כו' והוא דייקא ע\"י התורה דאורייתא מחכמה נפקת בלימוד הפה כו'"],[1900740337,"וד\"ל. ורצה משה שיהי' המשכת אלקות ע\"י תורה וממילא הי' ביעור הרע דגוף מחמת גילוי אלקות. וז\"ש ההר הטוב הזה והלבנון נו\"ן פשוטה שרצה שיהי' גילוי אא\"ס בחי' שעשוע המלך בעצמותו למטה כמו למעלה בלי אתעדל\"ת כלל. ולכן ביקש אעברה ואראה כו' כנ\"ל, ולא פעל זאת אצל הקב\"ה, רק אמר לו עלה ראש הפסגה ויראה אותה מרחוק בכלל כל א\"י, וע\"י ראי' זו פעל שיהי' בחי' זו שהוא המשכת גילוי אלקות מלמעלה למטה ע\"י תורה אצל יחידי סגולה ואצל המון עם יהי' נמשך ג\"כ בהעלם ומקיף, כי אין ד\"ת מקבלין טומאה ואפי' ב\"ק מותר בד\"ת כמאמר בני פתח פיך ויאירו דבריך כו', וכמו שהי' בזמן תנאים ואמוראים שלא הי' שכיח כלל שמי שהוא בעל תורה לא יהי' בו יראת שמים כי ע\"י תורה הי' נמשך אלקות בגילוי וממילא לא יוכל לעשות ההיפוך. ועכשיו ג\"כ בכל דור יש בחי' משה כמאמר אתפשטותא דמשה בכל דרא ודרא, ואצל יחידי סגולה יש בחי' זו בגילוי ואצל שארי העם נמשך אלקות בהעלם ומקיף. וזהו מ\"ש ויתעבר ה' בי למענכם שהמניעה היא מצדכם ולא מצדי כנ\"ל וד\"ל. אבל אלו הי' רואה אותה מקרוב הי' המשכת אלקות בגילוי ע\"י תורה בכולם כו'. ואחר שראה שלא פעל בקשתו אמר ועתה ישראל שמע אל החוקים והמשפטים, אחר שלא פעלתי להיות גילוי אלקות מצד עצמו לכן שמע אל החוקים כו' שיהי' ההעלאה מלמטה כו'.\n<b>ועתה</b> י\"ל מה שאמר להם אח\"כ פ' ק\"ש שמע ישראל כו', הענין הוא כי אחר שלא פעל בקשתו אמר להם שמע ישראל, והוא כעין עצה שאופן זה שע\"י תורה יהי' ע\"י שרש נשמתם שנק' ישראל, וענין ישראל הוא שר אל כמ\"ש כי שרית עם אלקים ועם אנשים ותוכל כו'. הענין כי יש ב' בחי' בנשמה חלק הנשמה אשר בגוף וחלק הנשמה אשר למעלה שאינה מתלבשת בגוף והוא הנק' צלם כמ\"ש נעשה אדם בצלמינ\"ו כדמותינ\"ו, שצלמינו הוא שרש"],[1900740338,"הנשמה שלמעלה ודמותינו הוא הנשמה שבגוף וכמ\"ש בצלם אלקי' עשה את האדם, וכתיב אך בצלם יתהלך איש שהוא ההארה מהנשמה אשר בתוך הגוף כו'. וענין צלם ודמות יובן עפ\"י ב' משלים, הא' הוא מהחותם שיש בו אותיות שקועים ונק' בשם צורה ראשונה ועצמי' והאותיות החותם הנחקקי' בשעוה ונראה בשעוה אותן אותיות עצמן שהוא צורה שני' הוא הנק' דמות. והמשל הב' הוא מה שמציירין צורת האדם על הלוח כל פרצוף פנים שלו לא יחסר כל ונק' צורת האדם עצמו בשם צורה עצמי' והצורה שנית המצויירת על הלוח נק' בשם דמות וצורה מצורה כו'. וכמו\"כ יובן בנשמת האדם, כי הנה כתיב נשמה שנתת בי טהורה היא אתה בראת אתה יצרת כו' שכמו שהיא בבריאה בחי' יש מאין נק' בשם צלם והנשמה שבגוף נק' בשם דמות. והנה ע\"י חטאים ועוונות נעשה פגם בנשמה כמ\"ש ואם פגמתי באות יו\"ד באות ה' כו'. כי הנה כתיב נר הוי' נשמת אדם כו' שבנשמה יש שם הוי', ולכן ע\"י חטא נפגמ' הנשמה והפגם אינו מגיע רק בנשמה הנק' דמות, אבל בצלם הנשמה שם אינו מגיע חטא ועון כלל. ובזה יובן מ\"ש נשמה שנתת בי טהורה היא דלכאורה אינו מובן שהרי הנשמה שבגוף אינה טהורה אלא דקאי על שרש הנשמה כו'. ויש עונות שחייבים כרת שהוא כריתת הנשמה לגמרי משרשה כמ\"ש ונכרתה הנפש מעמי\"ה כו', וע\"י תשובה מעומקא דלבא ובמרירות גדולה ועקירת הרצון מגיע עד שרש הנשמה למעלה ועי\"ז נמחל חטא ועון, כי הוא מהפך האותיות זרים שנעשו לטוב, כי ידוע שע\"י תשובה נמחלו החטאים, ולהיכן ילכו החטאים, אלא שהחטאים גופא נתהפכו לטוב, והוא כענין בעל החותם שברצונו מהפך האותיות באופן אחר.\n<b>והנה</b> ענין צלם ודמות יובן ג\"כ בהשתלשלות העולמות כמארז\"ל מה הנשמה ממלא את כל הגוף כך הקב\"ה ממלא את כל העולם כו', שבחי' כח הפועל בנפעל שהוא בחי' שם אלקים נק' בשם דמות ואלקות שבבחי' אצי' נק' בשם צלם. וענין כי שרית עם אלקים הוא השתררות על שם אלקים, וזה קאי כמו שהנשמה היא בבחי' אצי' עדיין שמשתרר על שם אלקים וכמו ענין הניסים שהוא להפך הטבע כמו מי שאמר לשמן וידליק יאמר"],[1900740339,"לחומץ וידליק שמשנה הצירופים כו' שהוא ע\"י הארה מבחי' אצי'. כמו\"כ יובן בענין הנשמה שע\"י שרש הנשמה יהי' נהפך הצירופים כמו למשל הבעל חותם הנ\"ל, והוא ענין מלמעלה למטה בלי אתעדל\"ת רק מצד שרש הנשמה כמו ע\"י תורה, וכמו שנראה שפעם יש גילוי אלקות מלמעלה למטה שלא לפי ערך האתעדל\"ת כמו בנביאים שהי' גילוי אלקות בגרונו הגשמי וכמו גילוי אלקות בהיכל ק\"ק, ופעם להיפך כמ\"ש גם כי תרבו תפלה אינני שומע כו', והוא מרצון בעל החותם כו' וד\"ל. וזה הוא רצונו של משה שאמר להם שמע ישראל שע\"י שורש הנשמה יהי' התגלות אלקות מלמעלה למטה גם שלא לפי מעשיהם כי הצירופים יהפכו מרע לטוב. והנה בחי' זאת לא עשה משה רק בכח הנשמה, כי אלו הי' בפועל הרי הי' נמחל חטא ועון, אלא שהמשיך בכח לבד, ולכן כעת צריך דייקא תשובה מלמטה למעלה ולעתיד יתגלה כו' וד\"ל."],[1900740340,"<h3>לא יקרא עוד שמך אברם</h3>\n<b></b><b>נאמר על ברית מילה של חתן אדמו\"ר מהר\"מ, יום ג' פ' עקב תקע\"ז לפ\"ק</b>\n<b></b>נאמר על ברית מילה של חתן אדמו\"ר מהר\"מ, יום ג' פ' עקב\n<b>לא</b> יקרא עוד שמך אברם כי אם אברהם כי אב המון גוים נתתיך כו'. הנה איתא במדרש ששאל א' אם אינו חפץ ה' בערלה למה בראו. והשיב לו משל לתורמוס שיש בו עביות ופסולת ושולקין אותו ז' פעמים עד שנעשה מתוק כו'. וכתיב אשר ברא ה' אלקים לעשות לתקן כו'. ולהבין ענין מילה מפני מה לא יהי' נולד מהול מאחר שאינו חפץ ה' בערלה, צריך להקדים כי יש ב' מיני הבדלות בכלל, כמ\"ש המבדיל בין קדש לחול בין ישראל לעמים. ויובן הענין בהשתלשלות העולמות ובעבודת ה'.\n<b>והענין</b> הוא כי הנה כתיב כי עמך מקור חיים באורך נראה אור, כי באמת אינו מובן כלל, איך אפשר להתהוות עולמות בע\"ג מבחי' א\"ס הבלתי גבול, והגם שכתיב שאו מרום עיניכם וראו מי ברא אלה, וכמ\"ש חדשים לבקרים כו', שבכל בוקר קודם נפילתו בטרדת הפרנסה כשנותן לבו שאין העולם עושה א\"ע"],[1900740341,"ובודאי חי מאלקות, אינו משיג לא מהותו שהוא עצמות אלקות ולא איכותו שהוא בחי' התפשטות אלקות איך ומה, והגם שכתיב מבשרי אחזה אלוק' דהיינו כמו שרואה האדם עד\"מ בראי' גשמי' שהגוף חי מהנפש הגם שאינו יודע לא מהות הנפש ולא איכות דהיינו אופן החיות איך שהגוף חי מהנפש, ומ\"מ יודע בודאי שהגוף חי מהנפש, שהרי הגוף בלתי נפש הוא כאבן דומם, כמו\"כ הגם שמתבונן שאין העולם עושה א\"ע ובודאי חי מאלקות מ\"מ אין נראה עצם אלקות ולא איכותו, והוא מחמת כי הוא ית' ישת חשך סתרו שיש פרסא המפסיק כמ\"ש והבדילה הפרוכת לכם בין קדש ובין קדש הקדשים.\n<b>והנה</b> יש ב' מיני הבדלות, דהיינו כמו עד\"מ בגשמיות שיש הבדלה גמורה שק של עור אשר מסתיר האור לגמרי. ויש מסך שמשימין בעד החלון כדי שלא יאיר האור להדיא ויתמעט האור מעט ומתוך הלבוש יואר האור. ועפ\"י משל זה יובן בהשתלשלות העולמות שידוע שיש מסך ופרסא המפסקת בין אצי' לבריאה, כי כדי שיתהוה עולם הבריאה יש מאין צריך שיתעלם האור דאצי' ולא יאיר רק דרך מסך כו', וכן מבריאה ליצירה ומיצירה לעשי', ונמצא שהלבוש ג\"כ נק' בשם לבוש קדוש, כי הלבוש אינו מבדיל גמור רק אדרבה על ידו דייקא יוכר האור כו'. ויש לבוש גמור והוא המסך אשר בין ע' שרים שנתהוים ליש ופירוד גמור, וכמו שר של מצרים שאמר לי יאורי כו' ובלעם כו', רק לפעמים נתעוררי' ובטילים לאלקות כמו בלעם שאמר לא אוכל לעבור את פי ה' כו', ועפ\"י רוב הם נפרדים ליש גמור, והמסך שביניהם הוא מסך והבדל גמור ונק' שק של עור, וז\"ש אלביש שמים קדרות ושק אשים כסותם כו'. ובכלל הוא ענין שבת וחול. והענין הוא כי הנה כתיב ששת ימים תעשה מעשיך וביום השביעי שבת כו', שא\"א להיות שבת בלא חול ו' ימי המעשה, כי ענין השביתה לא שייך דייקא אחר עשיית המלאכה. וצ\"ל הציווי של ששת ימים תעשה מעשיך דמשמע שהוא כמו מצוה עד שצריך לצוות עליה תעשה מעשיך ולייגע עצמו בלב ונפש בענין המו\"מ, וכמו בק\"ש שבפ' ראשונה כתיב שמע ישראל ואהבת כו' ובפ' שני' חזר הדבר והי' א\"ש כו' בכל לבבכם ובכל נפשכם כו', ואח\"כ כתיב ואספת דגנך כו' והלא יותר טוב הי' שיהי' כל היום כמו בש\"ע שמבואר בס' קבלה שהוא בחי' ביטול"],[1900740342,"במציאות, וכתיב דייקא ששת ימים תעשה מעשיך שאין רצון ה' דייקא שיהי' כל היום כמו בש\"ע אלא אעפ\"י שמקושר בעסקי עוה\"ז ואח\"כ ישוב אל ה' כו' כמשית\"ל זהו רצון העליון כו'.\n<b>והנה</b> ענין עשיית מלאכה בו' ימי החול שהוא כמו ההסתר מאלקות לייגע עצמו בלב ונפש ונראה הדבר בבחי' פירוד גמור, אך מ\"מ כשנזכר על ה' גם באמצע יגיעתו איך שה' הוא הנותן כח ועוז והוא המצליח כמ\"ש השלך על ה' יהבך והוא יכלכלך כו', או כמו בהתעוררות בתפלה, אזי נתעלים כל הכוחות אשר שם בעניני עוה\"ז בעסקי המו\"מ ועולים לה', ונק' בשם חולין שנעשו על טהרת הקודש, והוא הנק' להבדיל בין קדש לחול שההבדלה זו אינה הבדלה גמורה רק הוא הבדלה שע\"י יוכר האור. והענין כי הנשמה היא בחי' אלקו' ונתלבשה הנשמה בעניני המו\"מ ושם דייקא ימצא בחי' אלקות, והוא ענין פרקי הצלם, דהיינו שהנשמה מתלבשת עצמה בעניני עוה\"ז, ובזמן הבית כתיב וישבו איש תחת גפנו כו' שהי' להם הפרנסה בריוח בלי יגיעה וכעת הוא דייקא ע\"י הטרדא והעסק, וזהו רצון ה' שיתלבש בלבוש ומתוך הלבוש יהי' התגלות אלקות. וכמו\"כ יובן למעלה שכל ו' ימי החול הוא בחי' מלאכה ועבודה שית יומין עביד עבידתא להחיות העולמות בע\"ג ע\"י לבושי' והסתרים כדי שיוכלו להתהוות העולמות בבחי' בע\"ג, והלבוש אינו רק שע\"י יאיר האור כנ\"ל, והוא ענין להבדיל בין קדש לחול שאינו חול גמור, וההבדלה שבין ישראל לעמים הוא הבדלה גמורה כי הפרידם מאחדותו לגמרי. והנה לע\"ל כתיב אז אהפוך אל עמים שפה ברורה לקרא כלם בשם ה', דהיינו שלישראל יהי' התגלות עצמות ומהות אלקות ולא כמו עכשיו שבאורך נראה אור שהלבוש מסתיר על עצם האור והאור שנראה הוא הארה דהארה לבד, וגם מה שלאוה\"ע עכשיו לבוש שק, לעתיד לא יהי' לבוש גמור המבדיל לגמרי כמ\"ש לקרא כלם כו' וכמ\"ש וידע כל פעול כי אתה פעלתו כו' וד\"ל."],[1900740343,"<h3>לא יקרא עוד שמך אברם</h3>\n<b>יום הנ\"ל</b>\n<b>לא</b> יקרא עוד שמך אברם כ\"א אברהם כו', להבין הטעם שנק' אחר המילה אברהם בתוס' ה' כמ\"ש אב המון גוים נתתיך, שאחר המילה דייקא הוא אב המון גוים כו'. הנה ידוע שיש בכל דור ודור בחי' צדיק אשר ע\"י נפעלים כל ההעלאות וההמשכות, דהיינו שהוא המביא ומעלה כל ההתעוררות של מעשה התחתונים וכל התומ\"צ והוא המוליך ההשפעה מלמעלה למטה, ונק' בשם יסוד וכמ\"ש וצדיק יסוד עולם כו'. והנה מבואר בס' קבלה שיש פנימי' יסוד וחיצוני' יסוד, וכולם נפעלים ע\"י צדיק א' שבדור, והוא ענין פנימי' השפעה וחיצוני' השפעה הנשפעים ע\"י צדיק שחד בדרא, וחיצוני' השפעה הוא מה שהוא נותן לחם בשר וזן ומפרנס לכל, ושרש החסד למעלה הוא חסד אלקי והוא נמשך למטה לזה בחיצוני' בהשפעת עושר וכבוד וגם המשפט שעל מלכי האדמה באדמה להרים המל' ולהשפיל כ\"ז נעשה ע\"י הצדיק. ויש שנמשך לו ההשפעה בבחי' פנימי' בעניני אלקות להתפעל במוח ולב, שאין זה ערך כלל לכל השפעה חיצוני' בבני חיי ומזוני כו', וכ\"ז נעשה ע\"י הצדיק שהוא כמו הסרסור עד\"מ שהוא המוליך מלמעלה למטה ומביא מלמטה כו' כנ\"ל. והנה אברהם הי' הצדיק הממוצע כמ\"ש ברוך אברם לאל עליון קונה שמים וארץ שאמר לו מלכי צדק מלך שלם כו', מלכי צדק הוא בחי' מל' דאצי' כח הפועל בנפעל וההמשכת אלקות בבחי' מל' תלוי ע\"י אברם, וזהו שאמר לו מלכ\"י צד\"ק ברוך אברם כו' שע\"י הוא המשכת אלקות לבחי' מל'."],[1900740344,"<b>והנה</b> קודם שנימל אברהם הי' ההשפעה הולך לאוה\"ע כמו לישראל בשוה, כמו ענין דורו של אנוש היו ניזונין בחסדו של הקב\"ה הגם שהי' עובדי ע\"ז היו מושפעים כל טוב. וכמו\"כ הי' בימי אברהם, ולא הי' הבדל בין פנימי' השפעה לחיצוני' ההשפעה, שהי' נשפע שפע אלקי' לכולם בשוה, דהיינו שהי' נמשך פנימי' אלקות גם לאוה\"ע. ולכן מצינו בימי אברהם שהיו חסידי אוה\"ע וכמו נשמת משותלח כו' שהיו נשמות גבוהות מאד באוה\"ע ולא גיירו את עצמן כלל, כי הי' נשפע בשוה לכולם, והניצוצות שירדו להם נשתקעו שם ולא בדרך נפילה כמשית\"ל. והטעם הוא מפני שלא נימול והוא הי' בחי' מרכבה לה' גם קודם שנימול, לכן הי' השפעת אלקות לאוה\"ע כמו לישראל. אך אחר שנימול נק' שמו אברהם בתוס' ה\"א כי אב המון גוים כו'. והענין הוא שע\"י הסרת הערלה אזי נבדל הפנימי' מחיצוני' שלא יומשך הפנימי' לאוה\"ע כ\"א לישראל דווקא ואז נבדלו הישראל מאוה\"ע שלא יומשך לאוה\"ע רק חיצוני'. ומה שנראה כעת גרים המתגיירים שרוח ה' נוססה בם בתשוקה נפלאה להתגייר הוא מחמת הניצוצות שנפלו בדרך נפילה ולא מחמת האב ואם שהם המשיכו ניצוץ אלקי, כי הרי נבדלו זמ\"ז בתכלית מעת שנימל אברהם שאז נעשה הבדלה גמורה בין ישראל לאוה\"ע. וגם אותם הניצוצות שכבר ירדו ג\"כ לקח אז אלא שנפלו נשמות בדרך נפילה כו' כידוע. אבל בישראל הגם שכתיב הן בעון חוללתי ובחטא יחמתני אמי שאב ואם ממשיכין נפש הטבעי' ע\"י חום התאוה גשמי' שלהם מ\"מ נמשך בו נשמה ג\"כ כמארז\"ל שלשה שותפין יש באדם אב ואם ממשיכין נפש הטבעי' והקב\"ה נותן בו נשמה. וזהו ענין מילה ופריעה, שמילה הוא הסרת הערלה שלא יקבלו אוה\"ע מפנימי' והפריעה הוא ענין השפעה פנימי' שלישראל וזהו ענין וצאצאיו חתם באות ברית קודש כו'"],[1900740345,"וד\"ל. וז\"ש בני חת לאברהם נשיא אלקים אתה בתוכינו, שאתה הוא הפנימי' ולאוה\"ע אינו נמשך כ\"א חיצוני', והוא ענין פנימי' יסוד וחיצוני' יסוד הנשפע ע\"י צדיק ואז הי' אברהם המשפיע. וזהו שנק' אחר המילה אברהם בתוס' ה' ע\"ש כי אב המון גוים נתתיך, שבתחלה לא הי' אב של המון גוים שעיקר ההשפעה היתה ע\"י בחי' מל' והוא הי' הסרסור לבד ולא הי' כ\"א כמו מליץ באמרו השופט כל הארץ לא יעשה משפט ולא בדידי' תליא מילתא, אבל אחר המילה אב המון גוים נתתיך שהוא בעצמו המשפיע ובדידי' תליא מילתא. וזהו אב המון גוים כו' שאתה הוא האב המשפיע כו', ובחי' מל' נתעלה למדרגה גבוה יותר כידוע וד\"ל."],[1900740346,"<h3>בעצם היום הזה נימול אברהם</h3>\n<b>יום הנ\"ל</b>\n<b>בעצם</b> היום הזה נימול אברהם כו' וצ\"ל ענין נימול דמשמע מעצמו. והנה להבין זאת צריך להקדים שיש ב' מיני מילות כמ\"ש המולו ערלת לבבכם וכתיב ומל ה' אלקיך כו'. ולהבין מ\"ש והיטבך והרבך מאבותיך, דמשמע יותר מאבותיך, ולכאורה אינו מובן והלא האבות הם השרשים ומיעקב נתפשט עד ע' נפש כו' ובמצרים נעשו ת\"ר אלף שרשים וכעת הם ענפים ואיך כתיב והרבך מאבותיך כו'. הנה כתיב מי יעלה לנו השמימה ר\"ת מילה וס\"ת הוי\"ה, ובתורה כתיב לא בשמים היא שכבר ירדה משמים כו' וכתיב עקב אשר שמע אברהם בקולי וישמור משמרתי כו' וארז\"ל קיים א\"א ע\"ה כל המצות אפי' ע\"ת קיים אותם ברוחני' אבל מצות מילה לא קיים, כי כל המצות נרמזים בשם הוי\"ה י\"ה הוא שס\"ה ל\"ת ו\"ה הוא רמ\"ח מ\"ע וכמ\"ש ושמרו דרך הוי' לעשות צדקה כו' אבל מילה לא קיים שמצות מילה היא העולה על כולם כו'.\n<b>ולהבין</b> כ\"ז יש להקדים הקדמה א' מענין לימוד התורה שגם מי שיושב ולומד הרבה ושונה וחוזר עד שנעשה שגורה בפיו ויכול להורות הוראה לאמיתה מ\"מ אם התורה הוא בלא תשובה אין לו חיבור עם התורה שלומד כמו הפחות ערך שאינו לומד כלל, כי בתושב\"כ בס\"ר אותיות התורה יש לכל א' אות מיוחד אבל בתושבע\"פ שלומד אין לו חיבור כלל, רק צ\"ל"],[1900740347,"תשובה, והוא ענין מילה ערלת לב והוא כמ\"ש כי כל הגוים ערלים וכל בית ישראל ערלי לב, והוא ענין לבו כלב האבן, בשרירות לבי אלך כו' בחי' פריקת עול הרגשת עצמו ליש ודבר בכל פרטיו. וענין הסרת ערלת לב הוא כמו ענין שכתוב ביעקב כי במקלי עברתי את הירדן ועתה הייתי לשני מחנות קטונתי מכל החסדים כו' שמה שעבר במקל לבד ואח\"כ הי' לעושר גדול הי' שוה אצלו גם שהי' עוסק בעניניו עד שהי' לשני מחנות אבל הי' נקבע אצלו שאין זה שלו כי ה' הוא הנותן והוא יכול להרים ולהשפיל ברגע א'. וכמו\"כ צריך שיקבע בכל נפש מישראל שלא יתרחב לבו כשהולך לו בעניני זה העולם ומצליח ולהיות הולך בשרירות לבו כו' ורק כשיבטשו אותו בבני חיי ומזוני אז יזכור על ה' שה' הוא העושה לו זאת וזולת זה אינו נזכר כלל על ה', אלא צריך שיהי' זה תמיד בכחו* שה' הוא הנותן ההשפעה והוא יוכל להמנע. ובחי' זו נק' מילה של ערלת הלב, והוא המילה שמלמטה למעלה. ומ\"ש ומל ה' אלקיך את לבבך כו' הוא התגלות אלקות מלמעלה למטה כמו הדוגמא שיהי' לעתיד וכמ\"ש יראת ה' על פניכם לבלתי תחטאו שהוא מחמת התגלות עצמו' אלקות מלמעלה אזי א\"א לבא לידי חטא כלל. וזהו ענין מילה ופריעה, שמילה הוא הסרת הערלה שמלמטה כו', והפריעה הוא כמ\"ש וצאצאיו חתם באות ברית קודש, שהוא האות לבחי' התגלות עצמיות כו'. וזהו בעצם היום הזה, ולא כתיב יום רק היום דקאי על יום הבא יום שכולו טוב יום שכולו ארוך. וזהו בעצם היום הזה נימול מעצמו כו' הוא הדוגמא דלעתיד כידוע וד\"ל."],[1900740348,"<h3>והי' עקב תשמעון</h3>\n<b></b><b>בעז\"ה, שבת פ' עקב תקע\"ז</b>\nשבת פ' עקב\n<b>והי'</b> עקב תשמעון את המשפטים האלה ושמרתם ועשיתם אותם ושמר ה' אלקיך לך את הברית ואת החסד אשר נשבע לאבותיך. תשמעון ושמרתם ועשיתם הם ג' בחי', מדו\"מ שבתורה והוא ענין בי\"ע, ובעד אלו ג' בחי' אזי יהי' מלמעלה ג\"כ ג' בחי', והוא ברית וחסד הם ב' בחי' ואשר נשבע לאבותיך הוא בחי' ג'. והנה בכלל מדו\"מ הוא בחי' מוח לב רגל, מחשבה הוא במוח ודיבור בלב ומעשה ברגל, ובפרט יש במח' גופא ג' בחי' מחשבה שבמחשבה דיבור שבמחשבה מעשה שבמחשבה, והוא ענין שמע ישראל כי בשמע יש ג' פירושים, הא' הוא לשון הבנה כמו דבר כי שומע עבדיך כלומר מבין והוא הבנת המחשבה (הנק' בל\"א דער הערט טיף אין דער מח'), ולא שמיעת אותיות לבד. וגם שמע הוא לשון אסיפה וקיבוץ כמ\"ש וישמע שאול את העם והוא התקבצות כל האותיות ששומע ומבחין בהם בין טוב לרע והוא בחי' דיבור שבמחשבה. וגם שמע הוא לשון שמיעה ששומע מה שחבירו מדבר בחי' שמיעת האותיות הוא בחי' עשי' שבמחשבה. ובעבודת ה' בתפלה יובן ג' בחי' אלו, כי בכלל תפלה נק' בשם מח' ובמח' גופא יש ג' בחי' מדו\"מ ובפ' שמע ישראל כתובים ג' בחי' אלו כמו שהם בכלל במוח לב כו'. שמע הוא במוח ואהבת בלב והיו הדברים האלה כו' בפו\"מ בחי' מעשה. ובשמע גופא יש ג\"כ ג' פירושים כנ\"ל והוא מה שבמח' יש ג' בחי' אלו, דהיינו התבוננות אלקות והעמקת והבנת הענין במחשבתו כנ\"ל הוא בחי' מחשבה שבמחשבה, ומה שנתפעל במחשבתו הוא בחי' דיבור שבמחשבה בחי' מדות שבמחשבה, ובחי' עשי' הוא ההסכם במחשבתו על העשי' בפו\"מ והוא הנק' בכן שהוא אחר ההתפעלות, דהיינו מאחר שנתפעל מאלקות איך שהוא העיקר ומחי' והעולם הוא טפל הוה ונפסד לכן נשאר אצלו הסכם על כל היום להיות סו\"מ וע\"ט."],[1900740349,"<b>והנה</b> מבשרי אחזה אלוה, הגם שבאמת אין לו גוף ולא דמות הגוף כי אין ערוך דיבור ומח' שלנו לדיבורו ומחשבתו, כי אין דיבורו כדיבורינו שהלא מדיבור גשמיו' שלנו לא נעשה שום התהוות משא\"כ בדבר ה' שמים נעשו, מ\"מ דברה תורה כלשון בנ\"א כמו הדיבור שלנו שהוא ההתגלות לזולתו והמח' היא סתומה, כמ\"כ כתיב למעלה בדבר ה' שמים נעשו בחי' כח הפועל בנפעל, וכמו כל עשרה מאמרות ויאמר אלקים יהי אור ויהי אור. ומה שיש מציאת אור כעת הוא ע\"י אמירה שאמר אז ובכל יום מחדש כו'. והנה יש מאמר סתום ומאמר פתוח, מאמר פתוח הוא מה שבא הדיבור בהתגלות כמו יהי אור, ומאמר סתום אינו שהוא סתום לגמרי שלא בא בגילוי כלל אלא הוא המח' של כל דיבור, כמו מאמר יהי אור הי' תחלה במח' עליונה, כמו למשל באדם שמה שהוא מחשב זאת הוא מדבר רק שהתהוות גשמיות הבריאה הוא ע\"י דיבור דייקא כי במח' ישנו כל אות ואות וכל הצירופי אותיות שבאים בדיבור, אלא שבמח' המה רוחניי' עדיין וכמאמר רז\"ל כל מה שיש ביבשה יש בים. יבשה וים הוא בחי' עלמא דאתגליא ועלמא דאתכסיא, וכל מה שיש ביבשה שהוא בחי' עלמא דאתגליא בחי' כח הפועל בנפעל יש בים שהוא עולם המח' עולם הרוחני. וז\"ש ברוך ה' אלקי ישראל מן העולם ועד העולם, מעלמא דאתכסיא לעלמא דאתגליא. והנה בחי' מח' זו אינו נק' בשם מח' אחת רק נק' בשם רבות מחשבות כו', דהיינו שכל הריבוי צירופי אותיות שבאים בהתגלות בדיבור הם אותם אותיות עצמן שהיו במח' כל הפרטי', ולכן נק' בשם רבות מחשבות. אבל יש עוד מח' הנק' בשם מח' אחת והוא מ\"ש צופה ומביט עד סוף כל הדורות בסקירה אחת כו', כמו למשל שמה שהוא צריך לדבר באיזה ענין ב' שעות, במח' הוא אצלו בסקירה אחת. וכמו למשל כשמחשב במחשבתו בסקירה א' שצריך לבנין בסקירה א' וכשבא לפועל דהיינו לבנות הבנין אזי יש בזה פרטים רבים באופני החלונות והגג והרצפה ולכל פרט יש מח' בפני עצמו השייכת לפרט ההוא, אבל במח' כללית נסקרו כולם בסקירה א'."],[1900740350,"<b>וכמו\"כ</b> יובן למעלה שיש מח' כללית הנק' מח' אחת שצופה ומביט עד סוף כל הדורות שהוא שית אלפי שני דהוי עלמא בחי' זמן ומקום עבר הוה עתיד כו' שם נסקרו בסקירה והבטה אחת, והוא ענין בראשית ברא אלקים את השמים ואת הארץ וכו', שבבחי' מאמר בראשית היו כל הפרטי' נסקרים בסקירה אחת. ובחי' מח' כללית זו הוא המעמיד ומקיים של המח' ודיבור שבאים לפועל המעשה כמו בבנין שמה שהוא מייגע עצמו לבנות הבנין ואינו נלאה כלל הוא מחמת שנשאר אצלו ההסכם במח' כללית שצריך לבנין כו'. והנה ארז\"ל בראשית נמי מאמר הוא, שבחי' בראשית שהוא מח' כללית הצופה ומביט עד סוף כל הדורות בסקירה אחת, לגבי עצמותו הוא מאמר א' לבד, כי בחי' בראשית זה הרי הוא בחי' כלל לפרט, דהיינו שכפי ערך הפרטי' של הדורות ככה הוא הכלל של מח' אחת. כמו למשל חומה המקפת את העיר שלפי ערך העיר ככה הוא החומה, כמו\"כ יש מח' אחת זו בכל עולם ועולם שיש בראשית של עולם העשי' שכולל במח' אחת כל הפרטי' שבעולם העשי', ויש מח' אחת של עולם הבריאה כו'. אבל בחי' עצמותו ית' אין שייך עליו לומר בחי' כלל ופרט כו'.\n<b>והנה</b> ארז\"ל נש\"י עלו במח' וכתיב אחור וקדם צרתני קדם למע\"ב. והנה א\"א לומר שקאי על מח' ששייך לדיבור שהרי כל העולמות נעשו בדבר ה' ולכל דיבור יש מח' ומהו היתרון מעלה של נשמות, אלא דקאי על מח' אחת שנש\"י היו במח' אחת. ועדיין אינו מובן שהרי מח' זו כוללת ג\"כ כל פרטי הברואים כמאמר צופה ומביט עד סוף כל הדורות כו'. אלא הענין הוא שבמח' זו יש ב' חלקי' ונק' בשם פנימי' וחיצוני', דהיינו מה שהוא צופה ומביט עד סוף כל הדורות כו' הוא חלק התחתון של מח', אבל נש\"י עלו בבחי' פנימי' של המח' זו. וראי' לדבר שהרי איתא במדרש במי נמלך בנשמתן של צדיקים, פי' במי נמלך אם לברא העולם אם לאו בנשמתן של צדיקים, ולכאורה אינו מובן שצדיקים לא שייך רק אחר שנה\"ע ונשמות בגופים ומקיימים תומ\"צ נק' בשם צדיקים אבל כשלא נה\"ע עדיין איך שייך צדיקים. הענין הוא שעלה לפניו איך שיהיו נשמות הצדיקים כו'. והנה מאחר שהם הסבה להתהוות העולמות הרי הם קדם גם לבחי' מח' שצופה ומביט כו' כי מח' אחת זו הוא כלל לפרט"],[1900740351,"העולמות וכמ\"ש ברוך שאמר והי' העולם, שאמר פירושו שרצה במח' אחת, כי רצון ומח' הם ענין א' כמו אחר חשב לעשות שפירושו רצה כו' וד\"ל.\n<b>והנה</b> לפ\"ז צ\"ל טעם ירידת הנשמה לגוף כמ\"ש באדה\"ר ויפח באפיו כו', אדה\"ר הי' כולל כל הנשמות ונשמתו הי' מבחי' עלה במחשבה, ולמה זה ירדה לגוף, וכמו\"כ עכשיו כו', שהלא הגוף הוא מעפר כמ\"ש אדם יסודו מעפר וכמ\"ש ויברא ה' את האדם עפר מן האדמה כו' שהוא מקרקע הגן מהרכבת ד' יסודות, והנשמה שרשה גבוה שהם עלה במח' בחי' הפנימי' והמובחר של מח' כנ\"ל, וא\"כ ה\"ז ירידה גדולה לגבי הנשמה מאיגרא רמא לבירא עמיקתא. אך הענין כי ירידה היא צורך עלי' שע\"י ירידתה לגוף תתעלה יותר מכמו שהיתה הנשמה דבוקה למעלה בשרשה בחי' פנימי' של מח' כללית. ויובן ע\"פ המאמר לית מחשבה תפיסא בך דמשמע דייקא בחי' מח' לא תפיסא בך אפי' מח' כללית ואפי' הפנימי' של מח' זו שנש\"י עלו במח' זאת אבל נקודת הרצון תפיסא בך (והוא בחי' ה', כי מדו\"מ הוא ג' בחי' ומח' כללי' הוא בחי' ד' וגם שיש בה ב' בחי' כנ\"ל נחשבים לא', ונקודת הרצון הוא בחי' ה' בחי' יחידה), כי בחי' מח' כללית הרי הוא עכ\"פ בחי' גילוי הרצון אבל נקודת הרצון אינו רצון בגילוי כלל רק הוא המעורר כל מיני רצון ונק' רעוא דרעוין כו', כמו שידוע שיש ג' בחי', מוח לב מעשה וכולם תלויי' ע\"י רצון, הן התפעלות המוח והן התפעלות הלב כו', ושרש שרשם הוא בחי' נקודת הרצון שהוא המעורר כל מיני רצון הן במוח כו', והוא בחי' תורה ותשובה כמשי\"ת."],[1900740352,"<b>ולהבין</b> זאת צריך להקדים מארז\"ל ע\"פ ואספת דגנך, דמקשה הגמרא והלא כתיב ועמדו זרים ורעו צאנכם, ומשני לא קשיא כאן בזמן שישראל עושין רצונו של מקום אז מלאכתן נעשית ע\"י אחרים, וכאן בזמן שאין עושין רצונו ש\"מ דאז מלאכתן נעשית ע\"י עצמן. ולכאורה אינו מובן כלל שהרי בפ' והי' א\"ש כתיב בכל לבבכם ובכל נפשכם בחי' מס\"נ בתכלית ונק' עדיין אין עושין רצש\"מ ומלאכתן נעשית ע\"י עצמן. אך ידוע התירוץ בשם הה\"מ ז\"ל דכאן לא כתי' בכל מאודך הגם שכתיב בכל לבבך ובכל נפשך עדיין אין זה עושין רצש\"מ. וביאור הדברים דידוע דיש ב' מיני יחודי', יחוד פב\"פ ויחוד אחור באחור. בזמן הבית הי' יחוד פב\"פ כמ\"ש יראה כל זכורך כו' שהי' מלמטה למעלה מישראל לאא\"ס בחי' פנימי' נקודת הרצון, וכמו\"כ מלמעלה למטה הי' התגלות פנימי' כמ\"ש יאר ה' פניו אליך כו' כמו הדוגמא דמת\"ת דכתיב פב\"פ דיבר ה' כו'. אבל בגלות הוא יחוד אחור באחור, כי הנה אמרו בזוהר קוב\"ה בגלותא אסתלק לעילא לעילא וכמ\"ש אלכה ואשובה אל מקומי כו' ופעם כתיב השוכן אתם בתוך טומאתם כו' דסתרי אהדדי. אך הענין הוא כי פנימי' נסתלק וע\"ז כתיב אלכה ואשובה כו' אבל בחי' חיצוני' לא נסתלק וז\"ש השוכן אתם בתוך טומאתם כו'. והחיצוני' אשר מלמעלה למטה אינו כמו לאוה\"ע שהוא בחי' אחוריים כמאן דשדי לשנאוי בתר כתפוי כידוע אבל בחי' חיצוני' של ישראל הוא חיצוני' של הפנימי'. וכמו\"כ מלמטה למעלה מישראל לאא\"ס הוא ג\"כ בחי' חיצוני' כמ\"ש כי פנו אלי עורף ולא פנים וכמ\"ש בפיו ושפתיו כבדוני ולבו רחק ממני כו', אבל אינו חיצוני' לגמרי כמו אוה\"ע דקרו לי' אלקא דאלקיא כו' רק"],[1900740353,"הוא חיצוני' של הפנימי', והפנימי' הוא בהסתלקות בחי' העלם כו'. ויובן זאת עד\"מ איש המדבר עם חבירו דברי פנימי' אהבה ובא איש זר שא\"א להראות בפניו גודל אהבתו אליו אזי הוא מדבר עמו בפניו דברים חיצונים ובעת שהוא מדבר עמו דברי חיצוני' האהבה פנימי' היא בשלימות רק שא\"א לו להגלות אותה כנ\"ל. וכמו\"כ יובן בענין האהבה שמלמעלה למטה מאא\"ס לישראל שהאהבה פנימי' היא בשלימות רק שאינה בגילוי מצד כלי המקבלים שמלוכלכים בחטא ועון ע\"י הרהור וכדומה. וכמו\"כ מלמטה למעלה מישראל לאא\"ס גם כן האהבה פנימי' היא בשלימות רק שאינה בגילוי. והראי' לדבר שהרי מ\"מ מקיימים תומ\"צ ומניחים טלית ותפילין כו' כמו בעת התגלות אהבה פנימי'. ועוד שהרי כשמעוררי' אותה אזי נתעורר בחי' פנימי' כמ\"ש כי אם מאס מאסתנו קצפת עלינו עד מאד השיבנו ה' אליך כו' שהקצף גבר עד מאד ולא עד בכלל, אזי אין להקצף מקום ונתעורר בחי' פנימי' נקודת הרצון. וזהו מ\"ש זכור רחמיך וחסדיך כי מעולם המה פי' מעולם של א\"ס כו'. וזהו השיבנו ה' אליך מלמעלה ואז ונשובה שהוא היחוד פב\"פ כו'.\n<b>והנה</b> התעוררות נקודת הרצון הוא ע\"י ב' בחי' תורה ותשובה, ע\"י תשובה הוא ע\"י בחי' ממעמקים קראתיך הוי' כו', מעומקא דלבא במרירות עצום עי\"ז נתעורר למעלה ג\"כ בחי' פנימי' כו', או שתחלת התעוררו' הוא מלמעלה כמ\"ש השיבנו ה' אליך כו' כנ\"ל. וע\"י תורה ג\"כ נעשה יחוד פב\"פ כי כל היושב ושונה הקב\"ה יושב ושונה כנגדו כמ\"ש הליכות עולם לו כו', כמשל החבל שראשו אחד קשור למעלה מעלה וראשו השני למטה, כמו\"כ ע\"י לימוד התורה למטה נמשך בחי' עצמותו כמ\"ש ואהי' אצלו אמון שעשועי' כו' משחקת לפניו ששרש התורה למעלה הוא בחי' שעשועי' עצמיי' בחי' נקודת הרצון, כי רצון ותענוג הוא ענין א', כי נקודת הרצון ממנו נובעים כל מיני רצון וכל מיני תענוג ובדורו של רשב\"י היו מועטים שע\"י עסק התורה שלהם נעשה יחוד פב\"פ כמארז\"ל הרבה עשו כרשב\"י ולא עלתה בידם אבל מקצתן עלתה בידן, שע\"י עסק התורה שלהם הגם שבדור הי' יחוד אב\"א אבל על ידי התורה עשו יחוד פב\"פ. ונמצא שע\"י שניהם נתעורר בחי' נקודת הרצון בין ע\"י תורה בין ע\"י תשובה, רק שיש הפרש ביניהם כמשי\"ת, שע\"י תשובה נתעורר"],[1900740354,"בחי' אהבה בגילוי וע\"י תורה אינה התעוררו' בחי' אהבה בגילוי רק שלא יהי' רעה בפו\"מ כמ\"ש לא מאסתים ולא געלתים לכלותם כו'.\n<b>ובזה</b> יובן ענין ושמר לך את הברית ואת החסד אשר נשבע לאבותיך, וצ\"ל ענין כריתת ברית שכורתים שני אוהבים זע\"ז בתכלית, ולמה צריך להכריתות ברית אחר שהם אוהבים זל\"ז בלא\"ה. אך ענין הכריתות ברית הוא גם שיהיו פירודי' ביניהם ע\"י הולכי רכיל וכדומה מ\"מ לא תזוז האהבה מאתם, וגם כשהאהבה שביניהם יתבטל התועלת של הכריתת ברית הוא שלא יוכל לעשות לו רעה בפו\"מ. וזהו ההפרש שבין חסד ובין אשר נשבע לאבותיך, חסד הוא גילוי האהבה, ואשר נשבע לאבותיך הוא כמ\"ש רק באבותיך חשק בחי' האהבה בפו\"מ לבד כנ\"ל (וזהו ענין הפלוגתא מר אמר תמו זכות אבות ומר אמר לא תמו זכות אבות כו'). וזהו מ\"ש והי' עקב תשמעון את המשפטים כו' דקאי על התורה, ותשמעון הוא המח' בתורה, ותשמרון הוא הדיבור דייקא בתורה כמ\"ש ערוכה בכל ושמורה, ועשיתם הוא בחי' הפו\"מ כי בתורה הדיבור הוא בחי' הפו\"מ, והעיקר הוא הפו\"מ כמ\"ש ויהי נועם ה' עלינו ומעשה ידינו כוננה עלינו כו' כי נעוץ תחלתן בסופן כו' כידוע, ועי\"ז ושמר לך את הברית שכולל חסד ושבועה כו' והוא ע\"י תשובה ותורה כנ\"ל וד\"ל.\n<b>ובזה</b> יובן מארז\"ל כאן כשאין ]עושין[ רצוש\"מ וכאן כשעושין רצש\"מ, כי בחי' מקום הוא מה שבדבר ה' שמים נעשו כו' בחי' מעלה ומטה וד' סטרין כו' וגדלות הדיבור בחי' ד' רבתי דאחד הוא בחי' מאמר סתום כמו שהדיבור עדיין כלול במח', וגדלות המח' הוא בחי' מח' כללית, וישראל עושין רצונו של מקום (כי שרשם הוא בבחי' נקודת הרצון ונמצא שהם עושין רצונו של מקום) בחי' מח' כללית. וזהו מ\"ש ואספת דגנך הגם שכתיב בכל לבבך ובכל נפשך אבל לא כתיב בכל מאדך שהוא בחי' תשובה עושין רצש\"מ ואז מלאכתן נעשית ע\"י עצמן. ומ\"ש ועמדו זרים כו' הוא כשעושין רצונו ש\"מ בחי' בכל מאדך כו'. ותירוץ השני דרז\"ל הוא כשעושין תורתן קבע ומלאכתן ארעי, שע\"י תורתם אומנתם נתעורר בחי' נקודת הרצון עושין רצש\"מ ואז מלאכתן נעשית ע\"י אחרים כו', אבל כשאין תורתם קבע אז ואספת דגנך כמ\"ש במ\"א וד\"ל."],[1900740355,"<h3>ועתה ישראל</h3>\n<b>בעז\"ה פ' הנ\"ל תקע\"ז</b>\n<b>ועתה</b> ישראל מה ה' אלקיך שואל מעמך כ\"א ליראה ואח\"כ כתיב לאהבה ולעבדו ללכת בכל דרכיו כו'. הנה כתיב לך ה' הגדולה, לגדולתו אין חקר וכתיב מה רבו מעשיך ה' כולם בחכמה עשית. הענין הוא כי כל פסד\"ז והללויה מדבר רק בדברים תחתונים הנראים כמו הללוהו שמש וירח כו' תנינים וכל תהומות כו' וכן כל ספר תהלים מדבר בדברים הנמוכים ואינו מדבר בענין הפלאת ערכו סדכ\"ס כו'. הענין הוא כי הנה כתיב אתה הראת לדעת שצריך שיקבע בנפשו כאלו רואה בראי' חושית, וזה א\"א כ\"א דייקא בדברים הנראים, וכמ\"ש שאו מרום עיניכם וראו מי ברא אלה. אלה הוא עולמות הנראים וכמו דצח\"מ או ארמ\"ע שזהו דבר הנראה וצריך להעמיק בזה איך שאין הדבר עושה א\"ע ולא לילך אחר הבלי עוה\"ז בגשמיות להתאוות תאוה רק להסתכל ולראות מאין נבראו מאחר שאין הדבר עושה א\"ע מוכרח להיות שכח אלקי הוא המהוה ומחי' אותם כמ\"ש אין לך עשב מלמטה שאין לו מזל מלמעלה מכה ואומר לו גדל, ממגד תבואות שמש וממגד גרש ירחים כו', וכן מזל מחכים מזל מעשיר. וכמו\"כ בדומם כמאמר גדא דהר שפי' מזל ההר, וכמו שנראה שאין אקלים א' דומה לחבירו, ובאקלים א' גופא יש שינויים מזמן לזמן כמ\"ש חלקה אחת תמטר כו' שזה תלוי מחמת כ]ח א[לקי כו', ולכן כל הצמיחות גדילים ביושר ואינם גדילים באלכסון כי כולם גדילים נגד המזל והפילוסופי' נלאו זאת להבין ואין מביני' כו'. וזה כל האדם להיות נקבע בנפשו"],[1900740356,"כאלו רואה, ולכן נקבע ההתבוננו' בפסד\"ז ובכל ס' תהילים בדברים נמוכים הנראים כי מאחר שרואה גוף העולמות אז יקבע בנפשו גם על כח אלקי כאלו רואה, אבל אם יהי' ההתבוננות במזל גופא שהרי המזל הוא ג\"כ נברא ומחודש, לא יתפעל בנפשו בבחי' ראי' רק בבחי' שמיעה דהיינו חוש השמיעה ולא שמיעה בעלמא רק הוא ענין (דער הער כידוע), וכמ\"ש שמעתי שמעך יראתי, שהרי אינו רואה המזל להיות נקבע בנפשו בבחי' ראי' על אלקו' המחי' אותו כו', ואינו דומה שמיעה לראי' כמו למשל השמיעה מעוצם הדר מלכות באופני כלי יקר מאד הגם שמספרים לו כל אריכות בכל אופניו לא יחסר דבר, לא יתפעל כ\"כ כמו ע\"י ראי' כי התפעלות הראי' גם בדבר קטן הוא יותר גדול מהתפעלות השמיעה בדבר גדול. וכמו\"כ יובן בעבודת ה' שיותר טוב בחי' ראי', וזהו דייקא מהתבוננות בדברים נמוכים. והענין הוא כי אא\"ס הוא למעלה בעלוי אחר עלוי עד אין קץ ולמטה מטה עד אין תכלית, וכשיתבונן בבחי' הפלאת ערכו למעלה בעלוי אחר עלוי כמו שיתחיל מהמזל רוחני ויש גבוה על גבוה עד אצי' ולמעלה מאצי' סדכ\"ס לית מחשבה תפיסא בי', הרי לא יתפעל בנפשו כ\"א בבחי' שמיעה. אבל מהתבוננות של אא\"ס למטה כו' יהי' בחי' ראי'. ובאמת הוא כח אחד שאותו הכח אלקות עצמו שלמעלה מעלה עד אין קץ הוא עצמו הכח של התפשטות למטה עד אין תכלית.\n<b>והענין</b> כי בכל דבר ודבר יש ג' בחי', עולם שנה נפש, כמו בעץ יש ג' בחי' אלו, עולם הוא מהות העץ ושנה הוא הרכבה רוחני' של ד' יסודות ונק' בשם חומר וצורה, ונפש הוא כח אלקי המחי' אותם. וכמו\"כ בשמים יש עולם שנה נפש, עולם הוא מהות השמים כו'. והנה החומר וצורה הם הוה ונפסד אבל בחי' נפש שהוא הכח אלקי כמ\"ש ואתה מחי' את כולם זאת היא בחי' נצחי', הגם שהוא בחי' השתלשלות מעלה לעלול ברבוא רבבות השתלשלות עד שנתהוה דצח\"מ גשמיי', אבל מ\"מ הכח אלקי הוא נצחי' כמו אלקות שבעולם האצי' כנ\"ל. וזהו ענין לך ה' הגדולה, לגדולתו אין חקר, שהגדולה הוא התפשטות אלקות למטה מטה כו' כנ\"ל. ובזה יובן ג\"כ מה שאמר דהע\"ה מה רבו מעשיך ה' כו'. הענין הוא כי אחר שיקבע בנפשו ההתבוננות מדברים הנראי' כמו הרכבת ד' יסודות דצח\"מ כנ\"ל איך שואתה מחי' את כולם"],[1900740357,"כו', אזי ממילא יבא ויגיע לההתבוננות בדברים המופלאים ונעלמים שאין נראים, כי ידוע בבחי' השתלשלות עו\"ע שחלק האחרון שהוא חלק עשיראה לבד של המשפיע, משפיע במקבל. כמו למשל רב המשפיע שכל לתלמיד שא\"א למקבל לקבל עצמו' שכל הרב לכן מוכרח הרב לצמצם עצמו' שכלו ולא יגלה לו רק אפס קצהו וכו'. ולכן אחר התבוננות בריבוי מדרגות בדברים הנראים בדצח\"מ וכדומה ואין זה אלא חלק עשירית מהמזל מזל מחכים אין לך עשב כו', כולם אינם רק בחי' עשירית מהמזל ונמצא שהמזל הוא עשר פעמים כמוהו, והמזל מקבל מלמעלה וכן גבוה על גבוה שכל הגבוה יותר שם הוא מספר היותר גדול, וכן בלשון רז\"ל מרקיע לרקיע ת\"ק שנה כו' רגלי החיות כנגד כולן, שוקי החיות כנגד כולן, קרסולי החיות כו' שכל היותר גבוה שם הוא עוצם רבה המספר. וזהו שאמר דהע\"ה מה רבו מעשיך כו' שאין ערך כלל מה שאנו רואים לגבי למעלה מזה, כי הלא הם רק חלק עשירית, וכן גבוה על גבוה כו' כנ\"ל.\n<b>והנה</b> כתיב שמע ישראל, שמ\"ע שם ע', ישראל א' מע' באומות. ואין זה מובן כלל לפי הנ\"ל כי ידוע שנשמות הם יותר ממלאכים, שהרי הנשמות הם בחי' פנימי' ומלאכים הם בחי' חיצוני' כמ\"ש חונה מלאך ה' סביב ליראיו כו', וכל היותר פנימי' הוא היותר במספר, והמלאכים לגבי נשמות הם רק חלק א' מאלפי אלפים ורבוא רבבות לגבי הנשמות כי נשמות שירדו בגופי' שהיו בימי משה ת\"ר אלף ובכל דור ודור ניתוספו נשמות בגופי' אינם ערך כלל לגבי הנשמות שלמעלה שלא ירדו בגופי' כמ\"ש וקדושים בכל יום יהללוך סלה, וכל החיים יודוך סלה, וכל מקום שנאמר נצח סלה ועד אין לו הפסק כו', וא\"כ לפ\"ז הי' צ\"ל גם למטה נשמות יותר מכולם מאחר שהם למעלה יותר במספר מכל הדברים וחלק עשירית מתגלה כו'. אך הוא כי למטה הישראל הם בחי' פנימי' ואוה\"ע בחי' חיצוני' וצריך שיהי' ישראל מועט מאוה\"ע. והנה הנשמה כמו שהיא בשרשה למעלה נק' בשם אור, כי יש ב' בחי' אור ושפע. שפע הוא כמו מים הנירוק מכלי לכלי שמהות הדבר נשפע. ואור"],[1900740358,"הוא רק בחי' זיו. וכמו\"כ יובן למעלה שמ\"ש בדבר ה' שמים נעשו הוא בחי' כח הפועל בנפעל נק' בשם שפע שההשפעה היא בבחי' מהות כו', ונש\"י בשרשם נק' בחי' אור כמ\"ש נר ה' נשמת אדם, והגם שאור הוא רק בחי' זיו אבל יש יתרון מעלה ]ב[אור מבשפע, שבשפע הגם שהוא מהות אבל אינו כ\"א בחי' חיצוני', אבל אור הוא דומה לעצם, כמשל זיו השמש שמחמת שמאור השמש הוא עצם בהיר לכן הזיו ג\"כ מאיר. וכמו\"כ יובן למעלה שא\"ס נק' בשם מאור ונשמות נק' בשם אור כו'. וצ\"ל למה ירדה הנשמה לגוף מאחר ששרשה הוא בבחי' אא\"ס למעלה עד אין קץ בחי' אור, וא\"כ למה זה ירדה לגוף הגשמי. אך הענין הוא כי ירידה צורך עלי'. וז\"ש ועתה ישראל מה ה' אלקיך שואל מעמך כ\"א ליראה ולאהבה ללכת בכל דרכיו כו'.\n<b>והענין</b> יובן עפ\"י משל שיש ב' מיני עבדים, עבד עני ועבד עשיר. עבד עני הוא המשרת לאדון בעניני הבית לכבד הבית ולתקן המאכל שלא יהי' מר ושלא יתקלקל צרכי הבית ואינו מביא שום ריוח לאדון, רק אדרבה נותנין לו מעות על הוצאות הבית ועבודתו הוא לתקן הבית מכל מיאוס וטינוף או במאכלים ולראות דבר היש בבית שלא יתקלקל ולא שיגיע ריוח, דבר שמאוס לאדון לעשותו בעצמו כו', ונק' עבד עני הבא בשכרו שנותנין לו שכירות קצוב בעד זה. ויש עבד עשיר כמו אליעזר עבד אברהם שנק' עבדו זקן ביתו. וכמו יוסף שכתי' ויברך ה' כו' בגלל יוסף והוא עבד שהבעה\"ב נותן לו כל ממונו ורכושו והוא עוסק בהן במשא ומתן ומעשיר לאדון וכמו עבד הנוקב מרגליות כו'. ויובן הענין בעבודת ה' שיש ב' מיני עבד, כי נש\"י אחר שירדו בגופים נק' בשם עבדים כמ\"ש כי לי בנ\"י עבדים ואפי' נשמת משה אחר שירדה בגוף נק' עבד הוי', אבל כמו שהנשמות הם למעלה קודם ירידתם בגוף אין נופל עליהם שם עבד. ויש ב' מיני עבדים כנ\"ל, עבד עני הוא ענין לאהפכא חשוכא לנהורא והוא בחי' תשובה ומרירות, וכל מרירות אינה בחנם רק הוא מחמת הפגם שפגם במוח או בלב כו' ויש לו מרירות מזה ומקבל על עצמו להיות סומ\"ר והוא בחי' עבד עני שאינו מרויח לאדון רק הוא מתקן הדירה שלא יהי' פגום, וכח זה גופא נותנין לו מלמעלה כמו למשל העבד שנותנין לו מעות על הוצאות תיקון הבית והוא בא בשכרו ששכרו הוא שנותנין לו גילוי אלקות שיתפעל במוח ולב כו'. וע\"ז כתיב ועתה מה ה' אלקיך שואל מעמך כ\"א ליראה כו' ונק' בשם מילתא זוטרתא עבד עני כנ\"ל."],[1900740359,"<b>ומ\"ש</b> ללכת בכל דרכיו כו' הוא בחי' עבד עשיר והוא ענין התורה וקיום המצות, כי התורה נק' בשם הליכות עולם, כמו למשל הדרך שהמלכות עצמו הולך בה. כי ע\"י עסק התורה למטה הגם שנתלבשה בענינים גשמיים מ\"מ נמשך ע\"י בחי' עצמו' אא\"ס, כי שרשה הוא כמ\"ש ואהי' אצלו שעשועי' בחי' שעשועי' עצמיים. וכמו\"כ ע\"י מצות שמקיימים למטה בגשמיות כי המצות בשרשם המה תרי\"ג ארחי' דגלגלתא בחי' פנימי' רצונותיו. וזהו מה שהמלאכים שואלים איה מקום כבודו, ומשיבים מכה\"כ וכמ\"ש והארץ האירה מכבודו, ואין כבוד אלא תורה. כבוד בגי' ל\"ב נתיבות והוא ל\"ב נתיבות החכמה. וענין הנתיב הוא הדרך שעצמו' אא\"ס הולך ע\"י תורה ומצות להיות אא\"ס למטה כמו למעלה, והמלאכים אין בהם בחי' זאת ענין המשכת אלקות למטה, כי אין להם תומ\"צ, רק בחי' ביטול למעלה כמ\"ש וצבא השמים לך משתחוים כו'. ולכן משיבים מכה\"כ. ובחי' זאת נק' עבד עשיר שמעשיר לאדון כי נתאוה הקב\"ה להיות לו דירה בתחתונים דייקא כו', שכמו שהנשמות הם בשרשם נק' בחי' אור וע\"י ירידתם בגופים ע\"י תומ\"צ שנק' בשם אור כמ\"ש נר מצוה ותורה אור נמשך למטה להיות כמו למעלה כו'. ועבד עני הוא מ\"ש הושע ה' אתה עבדך כו'. ועבד עשיר הוא מ\"ש שמח נפש עבדך כו'.\n<b>והנה</b> בענין יראה שהוא בחי' עבד עני יש בזה ב' בחי' דהיינו הא' הוא בחי' מרירות שקודם התפלה שהוא על ח\"נ. והב' הוא המרירות שבתוך התפלה שהוא ע\"י התפעלות מאלקות איך שאתה מחי' את כולם ולא כמו שנראה העולם ליש גשמי והאין אלקי מוסתר ונעלם, אלא שמעמיק בזה הרבה איך שאלקות הוא העיקר ונתפעל בבחי' צעקה על שנראה העולם ליש שהוא היפך האמת, או בזוכרו שאחר התפלה יפול בהבלי עוה\"ז בטרדת עסק הפרנסה, והוא כמו למשל אדם שמשכיל איזה שכל אמת ובא אחר ואמר לו שקר היפך האמת ונתמלא כעס ורוגז על המדבר שקר. וכמו\"כ יובן בתפלה שע\"י שמתפעל מאין אלקי אזי תגבר הרוגז על היש המסתיר. והנה אם אין לו"],[1900740360,"מרירות כלל מהיש המסתיר על כח אלקי, אזי מזה הוראה שהוא מקושר בעומק רע. כי ידוע שיש עומק טוב ועומק רע והוא בחי' מקיף דרע כמ\"ש אתה ידעת את העם כי ברע הוא שהוא מוקף בתוך הרע והרע מקיפו. והענין הוא כי יש ברע ב' בחי' א\"פ ואו\"מ דהיינו אם עושה העבירה ע\"י שנתפעל בהתאוה בחי' א\"פ ואח\"כ חוזר בתשובה ויש לו מרירות מאד מזה ונק' צעקה מדבר חדש וחוזר ונופל, ולכן אנו מתפללי' בכל יום. אבל אם אין לו מרירות מצד שאין לו התפעלות מהאין אלקי, מזה הוראה שהוא מקושר בעומק רע עד שאינו שומע כלל שעושה רע. והוא כמשל אדם שעומד בהר גבוה ורואה גיא עמוק שמכיר גבהותו והתנשאותו, אבל אם שטח ההר הוא רחב מאד אינו מכיר כלל שהוא עומד בהר. או אדם עני שנעשה עשיר שיש בזה התפעלות יען כי דבר חדש הוא אבל מי שהוא עשיר מנעוריו אינו נתפעל כלל כי הרי זהו עצמותו. וכמו למשל עסק הפרנסה שחיי נפשו הוא שאינו ניכר בו התפעלות כלל. וכמו\"כ יובן בבחי' עומק רע שהוא מקושר בתכלית עד שאין מרגיש כלל כענין מארז\"ל אין אדם עובר עבירה אלא א\"כ נכנס בו רוח שטות כו' שנדמה כבהמה כו', ולכן אינו נתפעל מאין אלקי, וממילא אין לו מרירות מהיש המנגד לאין אלקי. אך עצתו הוא שתהי' עבודתו בבחי' שפלות והוא הנק' קבלת עומ\"ש, וכמ\"ש נאום הגבר הקים על כו' היפך של פריקת עול, דהיינו שיאמר לנפשו אחר שאין לי התפעלות מאלקו' ומרירות מן המנגד אזי מ\"מ זאת תהי' עבודתי בבחי' שפלות דהיינו שלא לצאת חוץ מגדר עכ\"פ בבחי' סו\"מ וע\"ט בפו\"מ, והוא כענין מאמרז\"ל אל יאמר אדם אי אפשי בבשר חזיר אלא אפשי אבל אבי שבשמים גזר עלי שהוא ענין קבלת עול לבד ואינו בחי' מואס ברע כו'. ובחי' זו נק' ג\"כ עבד עני. וזהו ועתה ישראל מה ה' אלקיך שואל מעמך כ\"א ליראה דקאי על ב' בחי' יראה שהוא עבד עני, הן המרירות על היש והן בחי' שפלות והוא הגורם למ\"ש סיפא דקרא לטוב לך כו'.\n<b>והענין</b> יובן ע\"פ מ\"ש שמח נפש עבדך כו' דקאי על עבד עשיר, וצ\"ל דבשלמא לעבד עני שעבודתו הוא בבחי' מרירות צריך לשמחה, אבל עבד עשיר שהוא בחי' עסק תומ\"צ המשכו' אא\"ס למטה כו' למה צריך עדיין הבקשה להיות שמחה כו'. אך הענין הוא לרצויי למרי' דהיינו שתהי'"],[1900740361,"בחי' שמחה עליונה מקיום התומ\"צ, כי יכול להיות גם שמקיים תומ\"צ אבל אין מזה שמחה למעלה כמ\"ש ובפרישכם כפיכם אעלים עיני מכם גם כי תרבו תפלה אינני שומע כו', וכמ\"ש ברצות ה' דרכי איש כו' שיכול להיות שאינו רוצה בו, וכמ\"ש בחזקיהו שאמר זכור את אשר התהלכתי לפניך באמת ובתמים, והשיב לו ה' וגנותי על העיר הזאת להושיעה למעני ולמען דוד עבדי, אבל האמת והתמים שלו אינו נתקבל. והוא כמשל המלך ב\"ו גם שעושין לו פנימי' רצונותיו וממלאין תאוותו ורצונו האהוב לו, מ\"מ לפעמים אינו מקבל תענוג מזה. וזהו ענין הבקשה שמח כו' שיהי' שש ושמח במעשה התחתונים. וענין לטוב לך, הוא שהשמחה עליונה שהוא טוב העליון בחי' שמחה ותענוג עצמי יתקבל בתוך נש\"י כענין חדאי נפשאי כו'. וזהו לטוב לך שהטוב העליון יתקבל בך, וכ\"ז הוא ע\"י ליראה דכתב ברישא דקרא כו' כמ\"ש במ\"א וד\"ל."],[1900740362,"<h3>להבין כו' בלק\"א פרק נ\"ב</h3>\n<b></b><b>בעז\"ה יום ב' פ' ראה תקע\"ז לפ\"ק</b>\nיום ב' פ' ראה\n<b>להבין</b> שרש הדברים מ\"ש בלק\"א פרק נ\"ב בענין התלבשות מל' דאצי' בהיכל ק\"ק דבריאה שהוא ענין חב\"ד דבריאה וחב\"ד הוא תלמוד כו' והוא ענין יחוד גאולה לתפלה כו'. להבין כ\"ז צריך להקדים בכל השתלשלות עלה ועלול שאין העלול בערך עילתו ורק בחי' אחרונה שבעלה שהוא חלק עשירית ממנו לבד משפיע בהעלול, וא\"כ צ\"ל מי מכריח שישפיע העלה להעלול מאחר שאין ערוך העלול להעלה א\"כ ה\"ז ירידה וצמצום לגבי העלה, ובאמת הוטבע שהעלה יהי' רוצה להשפיע להעלול כו'. אך הענין הוא כי כל עו\"ע הוטבע באופן שנעוץ תחב\"ס וסב\"ת (כי משפיע ומקבל נק' בשם תחלה וסוף כו'). הענין הוא כי יש כח אחר במקבל מה שאין במשפיע שהמשפיע מקבל חיות מזה, ולכן הוא רוצה להשפיע להעלול והוא כענין תלמיד המחכים את רבו, שבאמת שכל הרב גבוה למעלה מן שכל התלמיד וכשצריך להשפיע השכל להתלמיד אזי הוא מוכרח לצמצם עצמות שכלו ושישפיע לפי ערך תלמיד המקבל וא\"כ מי מכריח אותו להשפיע, והוא מטעם הנ\"ל כי במקבל יש כח עליון מה שאין במשפיע עד שהמשפיע הוא בחי' מקבל לגבי בחי' זו שבמקבל, וכנראה שע\"י שאלות וקושיות של שכל התלמיד הוא מחכים לרבו. כמו\"כ יובן למעלה בב' בחי' השפעות עיגולים ויושר שנעוץ תחב\"ס וסב\"ת שיש כח בתחתון מה שאין בעליון.\n<b>והענין</b> יובן עד\"מ מהלחם שאדם אוכל שעליו יחי' האדם שבאמת אינו מובן כלל שהרי האדם בחי' מדבר הוא גבוה למעלה מבחי' דצ\"ח וכמארז\"ל כל העולם כולו לא נברא אלא בשביל לצוות לזה בשביל האדם שיהי' לו לאכול וללבוש כו', נמצא שהאדם הוא הפנימי' ואיך יקבל חיות מבחי' צומח וחי. אך הטעם הוא מחמת שמוצא פי ה' שבמאכל הוא למעלה ממאמר נעשה אדם כידוע, ששרש המאכל הוא מבחי' עולם התוהו והאדם הוא מבחי' תיקון, דהיינו שבבחי' השתלשלות האדם הוא למעלה אבל יש בו כח אחר מצד שרשו כו' לכן יש בכחו להחיות האדם כו', וכמו שנראה בטעם"],[1900740363,"המאכל כי הנה כתיב וחיך יטעם אוכל כו'. ויש טעמים רוחני' וטעמים גשמיי', כמו שיש טעם ומתיקות בהשגת איזה שכל דבר מה עד שערב לנפשו וכמו בהתפעלות אלקות בתפלה בטוב טעם ותענוג כו', ויש טעם גשמי כמו טעם הפרי. והנה נראה שחיות האדם הוא דייקא ע\"י טעם גשמי שע\"י אכילת פרי אזי ישוב נפשו אליו, אבל כשלא יאכל ויטעם טעם רוחני שהוא טעם השכל לא יתקיים האדם, והוא מחמת שהטעם שבמאכל הוא הגבה למעלה מטעם השכל. והענין הוא כי יש למעלה עולם התענוג הנק' תענוג הפשוט והתענוג שבשכל הוא רק תענוג מורכב שהרי השכל אינו תענוג רק שהתענוג הוא בבחי' התלבשות בתוך השכל, אבל התענוג שבפרי הוא מהות של עצם התענוג רק שנתגשם ע\"י שבה\"כ כידוע, וכמ\"ש ויטע ה' אלקי' גן בעדן מקדם כל עץ נחמד למראה וטוב למאכל כו'. גן בעדן הוא בחי' זיוא עילאה בחי' עצמות התענוג הי' בבחי' כל עץ נחמד למראה כו', וכמו\"כ עתה הטעם שבפרי הוא מבחי' עצמו' התענוג רק שנפל בשבירה ונתגשם כנ\"ל. וכמו\"כ יובן למעלה בב' בחי' השפעות שהוא השפעה בבחי' עיגולים והשפעה שבבחי' יושר שנעוץ תחב\"ס כנ\"ל. וענין עיגולים ויושר יובן עד\"מ, הנה העיגול אין בו מעלה ומטה שהרי כשיתגלגל העיגול אזי יהי' העליון תחתון והתחתון עליון נמצא שמבלי ימצא ראש וסוף שהתחתון יכול להיות עליון והעליון יכול להיות תחתון כו'. ובחי' יושר הוא כמו פרצוף אדם שנראה בו מעלה ומטה והוא בחי' ראש ולב ורגל, שהראש הוא בחי' פנימי' והרגל הוא בחי' חיצוני' אבל יש בהעלם כח ברגל מה שאין בראש עד שהראש מקבל חיות מהרגל, וכמו שנראה שהרגל הוא מעמד ומצב של הראש. ומאחר שיש בכח הרגל להעמיד הראש מוכרח להיות שיש בו כח עליון מה שאין בראש שהראש מקבל חיות מהרגל, ונמצא שגם בבחי' יושר אין בו מעלה ומטה כלל מבלי שימצא ראש וסוף כו'. אך ההפרש שבין בחי' עיגולים ובחי' יושר הוא בענין העלם וגילוי, שבבחי' עיגולים הרי נראה בגילוי שהעליון יכול להיות תחתון והתחתון עליון, אבל בבחי' יושר הרי נראה שהראש הוא העליון והרגל הוא התחתון רק שיש כח בהעלם ברגל יותר מבראש. וזהו הטעם להשפעת עלה לעילתו תמיד בלי הפסק כו' וכמו שידוע שע\"י העלאת מ\"נ בבירורי' של מעשה התחתונים עי\"ז ניתוספו אורות באצי' כו' וד\"ל."],[1900740364,"<b>והנה</b> יש עוד הקדמה לזה עפ\"י מה שמבואר בע\"ח בהיכל הז' בענין ד' עולמות אבי\"ע הנרמזים בד' אותיות שם הוי', שהמשל לזה הוא מד' בחי' דצח\"מ. והנה בחי' דצח\"מ הרי הם בערך זה לזה, והנה לפ\"ז כמו\"כ בענין ד' עולמות אבי\"ע שעולם עשי' שלנו נק' בשם דומם שגם החיות רוחני' של עולם העשי' נק' בשם גשמיו' אחר שהוא כח להחיו' הגשמי', וכמו אין לך עשב מלמטה שאין לו מזל מלמעלה, מזל מחכים מזל מעשיר וכמ\"ש אני אענה את השמים והם יענו את הארץ כו', לכן גם הכח רוחני של עולם העשי' בכללו נק' בשם דומם, וכמו אברהם שאמר ואנכי עפר ואפר שהי' מרכבה לבחי' חסד דאצי' ונדמה עצמו לבחי' עפר בחי' דומם. ועולם היצירה נק' בשם צומח שהוא אינו בחי' כח להחיות גשמיו' הנבראים. ועולם הבריאה נק' בשם חי שהוא ענין נשמות יושבין ונהנין מזיו השכינה. ועולם האצי' נק' בשם מדבר כמ\"ש ועל הכסא דמות כמראה אדם כו'. ולפי משל הנ\"ל מדצח\"מ שהם בערך זה לזה שיש שייכות האדם עם הדומם אחר שהם נלקחים זמ\"ז בערך ושייכות, וא\"כ לפ\"ז גם ד' עולמות אבי\"ע הרי הם בערך וכמו מל' דאצי' נעשה כתר לבריאה ומל' דבריאה כו' שהוא בחי' אחרונה שבאצי' נעשה כתר וראש לעולם הבריאה ועכ\"פ יש איזה ערך ושייכות זל\"ז, וידוע מאמר הזהר איהו תפיס בכולהו עלמין ולית מאן דתפיס בי'. אך הענין הוא שיש למעלה ב' מיני השפעות ואמיתי' המשל להשפעה הב' אשר לית מאן דתפיס בי' הוא ממחשבה דו\"מ וכידוע שבי\"ע נק' בשם מדו\"מ. והענין הוא שיש ב' בחי' במחשבה ודיבור, היינו שיש דיבור אשר כל המח' נתפסת בהדיבור והוא הנק' התפעלות המח' מהדיבור, וכמו\"כ בשכל ומח' שיש מחשבת שכל אשר השכל נתפעל מהמח' עד שבעת שהוא מחשב שכל זה או מדבר מח' זאת לא יוכל להשכיל ולחשוב דבר אחר. ויש מח' ודיבור אשר המח' אינה מתפעלת כלל מהדיבור כמו דברים בטילים הנק' דברים של מה בכך שיכול לדבר והמח' יהי' מטורדת בענין אחר, וכמו שנראה שבעת העמקת האדם באיזה שכל מופלג ובא אחר ומדבר לו איזה ענין"],[1900740365,"קטן בערכו אזי הוא שומע דיבורו וזוכר הדבר ולא נתבטל כלל מהעמקת מח' שכלו ונק' בחי' מתעסק בעלמא. וכמו\"כ יובן בד' עולמות אבי\"ע שבאמת לית מאן דתפיס בי' שהשפעת אצי' בבריאה הוא כמו עד\"מ מתעסק הנ\"ל ולא מהות אצי' נתפס בבחי' בריאה. וכן מבריאה ליצי' שיצי' לא תפיס לעולם הבריאה וכו'. והנה לפ\"ז מאחר שאין ערוך מאצי' לבריאה ומבריאה ליצי' ומיצי' לעשי' מפני מה משפיע העלה להעלול, אך הוא מטעם הנ\"ל שנעוץ תחב\"ס שיש כח בתחתון מה שאין בעליון.\n<b>ועפ\"י</b> הקדמה זאת יובן למעלה ענין התלבשות מל' דאצי' בהיכל ק\"ק דבריאה שהוא חב\"ד דבריאה, כי בחי' מל' הרי גם שהיא בחי' אחרונה שבאצי' מ\"מ הרי היא עדיין בחי' אצי' ומי מכריח לה להתלבשות בעולם הבריאה בחב\"ד דבריאה, הוא ע\"י שיש כח בבחי' חב\"ד דבריאה מה שאין בבחי' אצי', כי שרש חב\"ד דבריאה הוא בחב\"ד דאצי', והגם שבחי' מל' מקבל ג\"כ מחב\"ד כי הרי הוא בחי' השתלשלות בע\"ס דאצי' עד מל' כו', אך ההשפעה שבבחי' מל' הוא רק הארה בעלמא אבל בבחי' חב\"ד דבריאה הוא מהות של חב\"ד דאצי' ולכן מתפשטת מל' בבחי' חב\"ד דבריאה כדי לקבל חיות ואור חדש מה שאין בה מצד עצמה, והוא ענין תלמוד בבריאה שהוא תורה הנגלית לנו דייקא, כי אורייתא סתום וגליא ותורה הנגלית יש בה כח עליון יותר מבחי' תורה נסתר וכמארז\"ל אשרי מי שבא לכאן ותלמודו בידו, שבג\"ע הוא לימוד הנשמות בסודות התורה בבחי' סתום תורה והוא דייקא ע\"י לימוד התורה נגלית וכמו אין מגלין רזי תורה אלא למי שעסק בתורה לשמה שהוא תורה הנגלית דייקא, וכמו רשב\"י שע\"י צער מערה זכה לתורה הנגלית בכ\"ד קושיות ופירוקי כו'. ויובן זה בתוס' ביאור ע\"פ מ\"ש שמח זבולון בצאתך ויששכר באוהליך, שזבולון עסק בפרקמטיא ויששכר עסק בתורה וכתיב יששכר יודעי בינה כו' לדעת מה יעשה ישראל, ומ\"מ הקדים זבולון ליששכר שמח זבולון בצאתך להיות שמח בעסקו שיצליח כו' ואח\"כ ויששכר באהליך אהל תורה, מפני שזבולון הוא מפרנס ליששכר שיוכל לעסוק בתורה ונק' בשם"],[1900740366,"תמכי אורייתא והוא בחי' נו\"ה בחי' רגל ויש כח בתחתון מה שאין בעליון כו' כנ\"ל, וכמאמר הזוהר אי לאו עלין לא אתקיים אתכלי' כו', וכמאמר בינה יתירה ניתנה באשה יותר מבאיש כו'.\n<b>ובזה</b> יובן ג\"כ ענין היכל ק\"ק שהי' בבהמ\"ק בגשמיות ולוחות גשמיי', שלכאורה אינו מובן היתרון מעלה בזה, שהרי מכה\"כ ויש היכל ק\"ק דבריאה כו' וק\"ק דעשי' ברוחני'. אך הוא כנ\"ל מפני שדייקא ע\"י בהמ\"ק גשמי' בלוחות גשמיי' שם הי' התגלות מהותו כמו בבחי' אצי' ממש בבחי' דילוג הערך ולא בסדר השתלשלות כמו ק\"ק הרוחני', ומשחרב בהמ\"ק אין לו להקב\"ה בעולמו אלא ד\"א של הלכה. הקב\"ה בעולמו הוא בחי' התגלות עצמו' אלקו' בעולמות הוא ע\"י ד' אמות של הלכה שהוא תורה הנגלית כו' וד\"ל. וזהו ענין יחוד גאולה ותפלה. ורב ברונא דסמיך גאולה לתפלה לא פסיק חוכא מפומי' כולא יומא כו' כי יחוד גאולה ותפלה הוא ענין יסוד ומל' והיחוד הוא ע\"י הכח שבמקבל מה שאין במשפיע, כי מי נתן לו הכח הזאת מאחר שהמשפיע הוא בחי' מקבל לגביו מוכרח להיות שהוא ממקום הגבוה גם מהמשפיע כו' כנ\"ל."],[1900740367,"<h3>שמע ישראל</h3>\n<b></b><b>אור ליום ה' פ' ראה תקע\"ז</b>\nאור ליום ה' פ' ראה\n<b>שמע</b> ישראל ה' אלקינו ה' אחד וארז\"ל כל המאריך באחד מאריכין לו ימיו כו' ועיקר האריכות הוא בד' רבתי דאחד. וצ\"ל מה שכתוב ב\"פ מס\"נ דידוע דבפסוק שמע ישראל ה' אחד הוא למסור נפשו באחד ואח\"כ כתיב ואהבת בכל לבבך ובכל נפשך כו' עוד פעם מס\"נ. אך הענין הוא דשמע ישראל קאי על שרש הנשמה ומ\"ש ואהבת קאי על הנשמה שבגוף שגם היא תמסור נפשה, ולכן ואהבת הוא בגי' ב\"פ אור ואור בגי' רז וב\"פ רז בגי' יתד כמ\"ש ותקעתיו יתד במקום נאמן כו', והוא ענין יחוד של שרש הנשמה עם הנשמה שבגוף, ונק' בשם ישראל ויעקב דהיינו שרש הנשמה נק' בשם ישראל. וזהו שמע ישראל, והנשמה שבגוף נק' בשם יעקב, ובואהבת הוא יחוד ישראל ויעקב. וזהו ענין יפה את רעייתי כתרצה שהוא חיבור הב' רצונות רצון שרש הנשמה ורצון הנשמה שבגוף כו'.\n<b>והענין</b> יובן ע\"פ מה שמבואר בתורה דמי מנה עפר יעקב כו' כי הנה כתיב ולכבודי בראתיו יצרתיו אף עשיתיו דמשמע שבכל נשמה בפרט יש ג' בחי' אלו בי\"ע וכמ\"ש נשמה שנתת בי טהורה היא אתה בראת אתה יצרת אתה נפחת בי כו', ולפ\"ז א\"א לחלק כלל ולומר שזה יש לו נפש דעשי' לבד וזה יש לו נשמה דבריאה כי מהפסוק בראתיו כו' או מענין המאמר נשמה שנתת בי כו' משמע שבכל נשמה בפרט יש ג' בחי' אלו, דלא כמלאכים שחלוקים זה מזה שיש מלאכים דבריאה שאינם שייכים לעולם העשי' כו'. ובאמת נמצא בס' קבלה מבואר שיש חילוקי מדרגות, שיש שיש לו נשמה"],[1900740368,"נמוכה בחי' נפש דעשי' לבד וזולתו יש לו נשמה דבריאה, וכמו שמצינו בכל דור ודור שיש ת\"ח ראשי הדור בחי' מוח, ויש בחי' רגל לבד, בחי' מעשה, כי בי\"ע נק' בשם מדו\"מ. וכן מדורו של משה עד עכשיו שדורו של משה הוא דור דעה כמ\"ש כי כל העדה כולם קדושים ודור הזה הוא בחי' עקבי משיחא בחי' רגל, והגם שבדורו של משה היו ג\"כ בחי' רגל וכעת יש ג\"כ בחי' ראשי אלפי ישראל, מ\"מ נפקותא גדולה בין רגל שבראש לראש שברגל.\n<b>אך</b> הענין יובן ע\"פ מ\"ש בצלם אלקים עשה את האדם וכתיב נעשה אדם בצלמינו כדמותינו, וצלם ודמות הוא ענין ב' בחי' הנ\"ל. בחי' צלם נק' שרש הנשמה כמו שהיא למעלה ודמות הוא הנשמה שבגוף והוא כמשל צורת האדם שמציירין אותה על הלוח בכל פרטי אופני', שצורת האדם עצמו נק' בשם צלם בחי' צורה העצמי' והצורה שעל הלוח הוא הדמות מצורה העצמית. וכמו\"כ יובן בענין הנשמות שהנשמה בשרשה נק' בשם צלם וחלק הנשמה שבגוף נק' בשם דמות. והנה ידוע דחטאים ועונות אינם פוגמים רק בנשמה שבגוף הנק' דמות כמ\"ש ואם פגמתי באות יו\"ד פגמתי באות ה', כי נר הוי' נשמת אדם שבנשמה יש שם הוי' וע\"י חטא ועון נפגם כמ\"ש נפש כי תחטא תווהא הוא דקאי רק על הנשמה שבגוף וכידוע דהנשמה שבגוף נק' בשם טהורה, טהרה מכלל דאיכא טומאה. והנשמה שלמעלה נק' בשם קדושה בעצם ששם אינו מגיע טומאה ופגם כלל. וזהו ענין הפלוגתא דב\"ש וב\"ה, דב\"ה אומר אפי' חגרת או סומא מ\"מ כלה נאה וחסודה כמ\"ש כולך יפה רעייתי ומום אין בך, ופעם כתיב מכף רגל ועד ראש אין בו מתום, אך הוא כנ\"ל שמצד שרש הנשמה כולך יפה רעייתי ומ\"ש מכף רגל ועד ראש אין בו מתום הוא מצד התלבשות נשמות בגופים שיכול להיות בחי' חיגרת שאין לו בחי' רגל שהוא"],[1900740369,"ההילוך אחרי הוי' תלכו בחי' פו\"מ, וראש הוא בחי' חכמה כו' וסומא שאין לו חוש השמיעה וחוש הראי' באלקות כו'.\n<b>והנה</b> מ\"ש בצלם אלקים עשה את האדם קאי גם על הנשמה שבגוף והוא כמארז\"ל אע\"פ שחטא ישראל הוא, והוא ענין הזהירות בסו\"מ וע\"ט גם שעובר על כמה עבירות מ\"מ יש שארי מצות אשר בלתי אפשר לו לעבור כמו לחלל שבת ולאכול חמץ בפסח וכדומה, נמצא שבבחי' זו שוין כמעט צדיק ורשע (והוא הנק' בל\"א עצמיות יהודעשקעט שבכל נפש מישראל כו'), ועיקר הראי' הוא ממס\"נ על קדה\"ש שגם קל שבקלים מוסר נפשו על קדה\"ש ומבואר בתניא שהוא מצד בחי' חכמה שבנפש בחי' כח מ\"ה, וכידוע מענין בע\"ת שפתאום נתעורר בנפשו בחי' תשובה בחרטה גדולה רק לה' לבדו כו'. ויש בחי' צדיקים נמוכי' מבע\"ת כי בע\"ת מגביהים תפלת צדיקים, כי פעם יש שאין יכולים לעלות מצד שאין הדור זכאי לכך או מצד מקטרגים וכמ\"ש ובפרישכם כפיכם אעלים עיני מכם גם כי תרבו תפלה אינני שומע כו', וע\"י שנמצאו בדור בע\"ת אמיתי' נגבהים ועולים לרצון תפלות הצדיקים אשר בלעדם היו נשארים למטה. ולכן קינא רבי לראב\"ד שיצאה נשמתו בבכי' גם שרבי הי' יחיד בדורו בתורה ומצות ומס\"נ בתכלית וראב\"ד הי' משוקע בעמקי רע, רק ששב בתשובה במרירות מעומקא דלבא עד שיצאה נשמתו, כי רבי ראה שע\"י בע\"ת דייקא יוכלו לעלות כל תפלות הצדיקים.\n<b>לפ\"ז</b> יתורצו ב' דברים הנראי' כסותרים זא\"ז, שמה שמבואר בס' קבלה חילוקי מדרגות הוא בענין הגילוי היינו שמי שיש לו נשמה דעשי' לבד הביטול שלו הוא רק בבחי' מעשה ובחי' מוח ולב אינם בגילוי אבל בהעלם ישנם אצלו, והראי' היא ממס\"נ שנתעורר בנפשו בחי' פנימי'. ומי שיש לו רוח דיצי' הביטול שלו הוא בלב. ומי שיש לו נשמה דבריאה הביטול שלו הוא במוח ורוח ונפש שהוא בחי' לב ומעשה נכללים בו, והוא כמשל מי שרואה את המלך שממילא יהי' נתפעל בלב ובמעשה לרוץ אחריו ולעשות רצונו. וז\"ש ולכבודי בראתיו יצרתיו כו', או נשמה שנתת בי טהורה היא אתה"],[1900740370,"בראת אתה יצרת כו' קאי על בחי' ההעלם ששוה בזה דורו של משה שהיו מבחי' חכמה לדור דעתה דעקבי משיחא בחי' רגל ועקביי' כו'.\n<b>ועתה</b> צ\"ל ההפרש שבין נשמות למלאכים כי הלא גם במלאכים יש ג' בחי' אלו כמ\"ש בדבר ה' שמים נעשו וברוח פיו כל צבאם, ויש מלאכים בעולם המחשבה ונקראים מלכי שלם, ויש מלאכים בעולם העשי', וידוע שא\"א להיות דיבור בלא מח' ועשי' בלי דיבור וא\"כ מהו ההפרש בין נשמות למלאכים. אך הענין יובן ע\"פ מ\"ש תשורי מראש אמנה והוא בחי' קול ודיבור, וצ\"ל שהלא הקול נמשך מהבל הלב ושרש הדיבור הוא השכל שהרי נראה שהתינוק שאין בו שכל אין יכול לדבר ונמצא שהדיבור שרשו מלמעלה והקול מלמטה ואיך מתייחדי' כא'. אך הענין הוא כי שרש מח' ודיבור הוא בעצמות הנפש, כי ידוע שבנפש עצמה יש ג\"כ בחי' אותיות כמ\"ש בלק\"א והוא בחי' כ\"ב תנועות הנפש רק ששם הם בתכלית הרוחני וכשבאים במבטא גשמי נתגשמו, ולא הדיבור הוא מחמת מבטא הגשמי רק הוא מחמת שבעצמות הנפש יש ג\"כ בחי' אותיות כו' וכמו שתי רוחות מספרות זו עם זו וכמו נפש המדברת גם בלא גוף יש בחי' דיבור רוחני. ונמצא ששרש המח' הוא הרצון שבפנימי' הנפש כי מח' ורצון הם ענין א' כמו אשר חשב לעשות אשר רצה כו', ונמצא שמח' זאת היא בחי' עצמיות אחר ששרשה מרצון הנפש, הגם שהנפש הוא למעלה מרצון אבל התגלות פנימי' הנפש הוא ברצון. ולכן לפעמים נק' הנפש בשם רצון כמ\"ש היש את נפשך שפירושו רצונך כו', ופעם משמע ששרש המח' הוא מלמטה כמו ענין הרהורי לבא שדבר הנחמד בלב אזי עולה במחשבתו להרהר זאת, ושניהם אמת כי אינם סותרים זל\"ז כלל רק שניהם באים כא', רצון הלב ורצון פנימי' הנפש והוא הנק' יחוד ישראל סבא ולאה או יחוד יעקב ולאה שהרצון שבפנימי' הנפש נק' בשם יש\"ס כו'. וכמו\"כ יובן בעבודת ה' שרצון הנשמה שלמעלה בשרשה ונקודת הרצון שבנשמה שבגוף מתייחדי' כא'. וזהו בצלם אלקים עשה את האדם, ואדם הוא אלף דם, אלף הוא שרש הנשמה ודם הוא הנשמה שבגוף מתייחדי' כאחד, כי הנשמה"],[1900740371,"בשרשה היא בחי' אלקות דהיינו שאינה אלקות עצמו רק הוא בחי' אלקות שהביטול שלה לאלקות היא בבחי' עצמיות אחר שנלקחה מאלקות, ונשמות הם הממוצעים בין אלקו' לעולמות בע\"ג כו'. והנה שרש הנשמה נק' בשם מים עליונים ונשמה שבגוף נק' בשם מים תחתונים, והוא ענין חכמה בראש וחכמה בסוף כו', ומים תחתונים בוכי' אנן בעינן למהוי קדם מלכא והוא בחי' נקודת הרצון ונשמה שבגוף כו'. וכדוגמא זו יהי' לעתיד דכתיב והשיב לב אבות על בנים ולב בנים כו', אבות נק' הנשמות שלמעלה ובנים הם הנשמות שבגופים כו' וכמ\"ש בזוהר זכה ב\"נ יהבין לי נשמתי' דהיינו גילוי שרש הנשמה שלו, וכידוע שאם הי' לאדם גילוי שרש נשמתו זהו יותר טוב מגילוי אליהו ורוה\"ק כו'. ולכן נק' הנשמות מהלכים והמלאכים נק' עומדים כמ\"ש ונתתי לך מהלכים בין העומדים האלה שהמלאכים הם עומדים תמיד במדרגה א' ואין שייך בחי' היחוד עם מה שלמעלה כנ\"ל בנשמות, אבל הנשמות נק' מהלכים וכמו נשמת משה שירדה בגוף והגוף לא הסתיר כלל, ונשמת אליהו עלה למעלה כמ\"ש ויעל אליהו בסערה השמים, וכמו חנוך דכתיב ויתהלך חנוך את האלקים ואיננו כו' מחמת שהם בחי' עצמיו' ולכן יש בכוחם לעלות ולירד כו', אבל המלאכים גם שכתיב בהם עלי' וירידה אינו אלא באותו עולם שהם שם כמ\"ש עולים ויורדים בו דייקא, וראי' מנפילים שירדו למטה ונתגשמו עד שחטאו בחטא גמור. וזהו ענין שמע ישראל ואהבת הנ\"ל ב\"פ מס\"נ כנ\"ל, ואהבת הוא ב\"פ אור בגי' רז וב\"פ רז בגי' יתד כמ\"ש ותקעתיו יתד במקום נאמן, שעיקר היחוד הוא באמת ויציב היכל הרצון כו'. והנה הגורם להיות יחוד ב' רצונות אלו ישראל ויעקב הוא ע\"י הארת אור עליון הגבוה משניהם יחד כו' כמ\"ש במ\"א וד\"ל."],[1900740372,"<h3>ראה אנכי נותן</h3>\n<b></b><b>שבת פ' ראה תקע\"ז לפ\"ק</b>\nשבת פ' ראה\n<b>ראה</b> אנכי נותן לפניכם היום ברכה וקללה, את הברכה אם תשמעון ואת הקללה אם לא תשמעון כו'. הנה כתיב אחת דבר אלקים שתים זו שמענו, והוא ענין אנכי ולא יהי' לך שבדיבור א' נאמרו וזכור ושמור בדבור אחד נאמרו, כי כל הדברות נאמרו כל דיבור בפ\"ע ואנכי ולא יהי' לך בדיבור אחד נאמרו כו'. ואנכי הוא שרש רמ\"ח מ\"ע ולא יהי' לך הוא שורש שס\"ה ל\"ת. וזהו ג\"כ ענין ראה אנכי נותן לפניכם היום ברכה וקללה כו'.\n<b>להבין</b> ענין זה צריך להבין ענין פ' של ק\"ש שיש בה ג' דברים, שמע ישראל ה' אלקינו ה' אחד הוא מצות יחוד אלקות, כמארז\"ל שתמליכהו בשמים וארץ וד' רוחות העולם, ואח\"כ כתיב מצות ואהבת לאהוב את ה', ועיקר הפי' של ואהבת הוא אבה פי' רצון לאלקות, ואח\"כ כתיב מצוה ג' והוא והיו הדברים האלה אשר אנכי מצוך היום כו' ואחר ג' אלה כתי' וקשרתם כו', והעיקר הוא הג' אלה. והנה ארז\"ל ע\"פ אשר אנכי מצוך היום, בכל יום ויום יהיו בעיניך כחדשים, וצ\"ל ענין חידוש זה מהו והלא התורה כבר ניתנה בזמן מת\"ת וכתיב ודבר אלקינו יקום לעולם ודבריו חיים וקיימים. וענין לימוד התורה דכעת הוא כמ\"ש את ה' האמרת היום שצריך לאמר דבר ה' אשר ניתן אז וכמ\"ש ודברי אשר שמתי בפיך, שמתי כבר, ותושבע\"פ הוא רק הפי' וביאור של תושב\"כ, ומהו זה שארז\"ל שבכל יום יהיו בעיניך כחדשים. וגם אנו"],[1900740373,"מברכין בברכת התורה בא\"י נותן התורה לשון הוה דמשמע שהוא נותן בכל יום. וגם אנו מבקשים והערב נא את דברי תורתך כו'. אך להבין זאת צריך להקדים בענין חידוש מע\"ב כמ\"ש המחדש בטובו בכל יום (תמיד) מעשה בראשית, וזה כל האדם לידע איך שהעולם מתחדש תמיד מאין ליש כמ\"ש חדשים לבקרים רבה אמונתיך, שבכל בוקר מתחדש כח אמונה זו, שבכל בקר מאיר כח חדש מנשמתו להכיר את בוראו, ואין המכוון להכיר בדרך פשט אלא שיהי' נקבע בלבו. וזהו שארז\"ל כי זקיף אינש לימא זוקף כפופים שזהו הטעם שהאדם הולך בקומה זקופה מצד שיש בו הכרה למה שלמעלה ממנו, כמ\"ש דע מאין באת כו'. ובחי' זו יש בכל נפש מישראל מצד נשמתו כמו ענין ההרגשה שבמילי דעלמא שהוא כמו טבע, כמו\"כ בכל נפש מישראל יש בחי' זו כמו טבע, רק שיתן אל לבו זאת ואם אינו נותן אל לב אזי הוא כבהמה שהולך אחר תאוות נפשו הבהמית למצא טרף לנפשו ונק' להחיות כחיי הגוים, וכתיב אדם אתם אתם קרויים אדם ואין אוה\"ע קרויים אדם, שדוקא בבנ\"י יש בחי' אדם להכיר את בוראו שהוא כמו טבע, אבל באוה\"ע גם דקרו לי' אלקא דאלקיא כו' אבל הדבר רחוק מהם ואפיקורסים כופרים לגמרי ואומרים לא הוא כו', ובישראל יש בחי' הכרה* כנ\"ל, וזהו תכלית עבודת האדם כל משך חייו בעוה\"ז כמ\"ש כי צל ימינו עלי ארץ, וכתיב ימי שנותינו בהם שבעים שנה ובהם פי' בהם בהסתר אלקות שנראה העולם ליש כו' וצריך ליתן לב איך שמתחדשים מאין ליש בכל עת ורגע, ואם אינו נותן לב למה לו לחיות כו'.\n<b>וצריך</b> להבין ענין חידוש העולמות שהלא ודבר אלקינו יקום לעולם וא\"כ כשאמר יהי אור הרי דיבורו הוא בחי' נצחי', כי כמו שאא\"ס הוא נצחי' כן דיבורו הוא בחי' נצחי' ולמה צריך לחדשו בכל יום ובכל שעה כידוע שי\"ב שעות היום י\"ב צירופי הוי' ויב\"ש הלילה י\"ב צירופי אד' כו'. אך הענין"],[1900740374,"הוא כי דבר ה' נק' בשם דבר מלך שלטון כו' כמו המלך שגוזר ואומר לעשות איזה דבר אזי תיכף מקיימים גזירתו, וכמו\"כ למעלה כתיב ההוא אמר ולא יעשה, וכמ\"ש דברי אשר יצא מפי לא ישוב ריקם כ\"א עשה כו', וכמ\"ש ויאמר אלקי' יהי אור ויהי אור כו' יהי רקיע כו'. אך בזאת אינו שוה דיבורו העליון לדיבורו של מלך ב\"ו, כי במלך ב\"ו הרי הדיבור נפרד מאתו דהיינו כשמדבר דבר הגזירה אזי מקיימים עבדיו ואינו צריך הדיבור שיצא מאתו להמלך, אבל למעלה כתיב כי עמך מקור חיים שהמקור חיים של העולמות בטל הוא לגבי עצמותו ולא אחר שדיבר יהי אור אינו צריך כלל למקורא דכולא רק הוא בטל אליו, ולכן צריך לחדשו תמיד שיומשך אותו החיות עצמו להחיות העולמות. ונק' בשם מחדש דהיינו שאינו חידוש גמור שהרי אינו חידוש בעצם שהלא האור והרקיע הם אותם עצמם שמאז בשי\"ב ואין בהם השתנות כלל, רק בהנהגת העולמות יש התחדשות מזמן לזמן על צבא המרום במרום כו', אבל גוף העולמות הם אותם עצמם שמשי\"ב, כי דבר אלקינו יקום לעולם ודבריו חיים וקיימים רק החידוש הוא באותו האור והרקיע עצמם שהלא הדיבור הוא בטל למקורו וצריך שיומשך אותו החיות עצמו מחדש. וה\"ז כמשל המאכל שאדם אוכל שע\"י המאכל והשינה מתחזק חיות האדם ואם לא יאכל יסתלק החיות, והחיות שע\"י המאכל אינו חיות חדש רק בכדי שאותו החיות עצמו לא יסתלק כו'. וזהו מ\"ש וידעת היום והשבות אל לבבך כי הוי' הוא האלקים כי זהו תכלית עבודת האדם ג\"כ לידע שאלקים מקבל משם הוי' תמיד כו'.\n<b>והנה</b> כ\"ז נק' בשם מילי' דהדיוטא ולאו אורחי' דמלכא לאשתעי במילין דהדיוטא בענין הנהגת העולמות, וה\"ז כמשל מלך ב\"ו שמדבר דברים השייכי' להנהגת המלוכה כמ\"ש וישב שלמה על כסא ה' כו' שהי' מלך על כל העולם והי' צריך לדבר דברים השייכי' לענין המלוכה, כמ\"ש מלך במשפט יעמיד ארץ, ובהדיבור יש חכמה ורצון השייך למלוכה, אבל דברי חכמה\nשהי' מדבר כמ\"ש וידבר שלשת אלפים משל זהו בודאי יותר נעלה\nמדיבור שבשביל הנהגת המלוכה כו'. ועפי\"ז יובן למשכיל למעלה שעשרה מאמרות הם בחי' חיצוני' ונק' בשם מילין דהדיוטא וגם החכמה שבהם כמ\"ש"],[1900740375,"בראשית ברא כו' בחוכמתא ות\"י בקדמין ברצונו כ\"ז רצון וחכמה השייך להנהגת מלוכה, אבל עשרת הדברות הם בחי' פנימי' חכמתו העצמי'. ועשרה מאמרות תלויי' בעשרת הדברות כמארז\"ל שלש שעות ראשונות יושב הקב\"ה ועוסק בתורה שניות יושב ודן את כל העולם כולו שלישית יושב וזן כו', שיושב ודן הוא השייך להנהגת העולמות כמ\"ש מלך במשפט כו' ויושב וזן מקרני ראמי' ועד בצי כנים כו' הוא גוף ההשפעה שנתקבל במקבל לכל א' כפי המשפט שבתחלה, וכ\"ז תלוי ע\"י שתחלה יושב ועוסק בתורה שהוא בחי' חכמתו העצמי' ואח\"כ יושב ודן ויושב וזן כו'.\n<b>והנה</b> עפ\"י זה יובן מארז\"ל בכל יום יהיו בעיניך כחדשים, שמאחר שמבואר לעיל שחידוש מעשה בראשית שהוא עשרה מאמרות מתחדשים בכל יום כנ\"ל, מובן מזה גם על בחי' הפנימי' שצריך להתחדש ממקורו כנ\"ל. ועפי\"ז יובן ענין ואהבת שבפ' ק\"ש, כי הנה בתחלת בריאת העולמות כתיב כי חפץ חסד הוא טבע הטוב להטיב, אך כעת חיות העולמות תלוי באתעדל\"ת כי באתעדל\"ת אתעדל\"ע, שהתעוררות בחי' רצון למעלה תלוי ע\"י מעשה התחתונים. והנה מאחר שצריך לעורר הרצון, צריך לעורר מדרגה שלמעלה מרצון והוא בחי' בעל הרצון וזהו דייקא ע\"י בחי' ואהבת, כי שמע ישראל הוא בחי' מח' והתבוננות איך שה' אלקינו ה' אחד שתמליכהו בשמים וארץ וד' רוחות כו' ופסד\"ז ושתים לפניה, שם מבואר בענין התהוות העולמות יש מאין, אך איך יהי' ההתהוות הוא ע\"י ואהבת כי שמע הוא בחי' מח' ולית מח' תפיסא בי' בבחי' עצמיות שהוא בחי' בעל הרצון, ואפי' התפעלות של מח' לא תפיסא בי' כו', אבל ע\"י רצון שהוא ואהבת פי' אבה לשון רצון והוא בחי' נקודת הרצון שבכל נפש מישראל נתעורר בחי' בעל הרצון. וענין והיו הדברים האלה שהוא ת\"ת למה צריך מאחר שנתעורר בחי' נקודת הרצון בנש\"י ועי\"ז נתעורר בעל הרצון ולמה צריך עוד לת\"ת לזה. הענין הוא כי ע\"י ואהבת נתעורר למעלה, אבל הסבה שיומשך למטה הוא ע\"י ת\"ת דייקא.\n<b>וביאור</b> הענין הוא כי הנה כתיב עוטה אור כשלמה שהתורה נק' בשם אור, והנה יש ב' מיני אור כמבואר בס' החקירה שההתפשטות של הנר"],[1900740376,"דהיינו האור המאיר אינו כמו עצם האור של הנר, והראי' לדבר שהרי אינו מאיר כ\"א במקום חושך המנגדו משא\"כ שרגא בטיהרא לא מהני ואלו הי' האור המאיר כמו עצם האור הי' מאיר גם במקום אור כו'. אבל אור השמש אינו כן שהאור המאיר הוא בדומה לעצם, ומה שיש נרתק לשמש כמ\"ש כי שמש ומגן הוי' אלקים כו' שכמו הנרתק לשמש כו' יש סברא שהנרתק אינו מסך המסתיר האור רק הנרתק גופא הוא מאיר. ומ\"ש לע\"ל יוצא חמה מנרתקה אין פירושו שהחמה יוצא מנרתקה שלא יהי' הנרתק אלא שהנרתק לא יסתיר כלל כו', והוא ת\"ת שנק' בשם אור הוא אור הדומה לעצם. וזהו ענין והיו הדברים האלה שאחר ואהבת דהיינו להיות המשכה למטה הוא ע\"י לימוד התורה שיקבע עתים לתורה כפי העת והפנאי שלו, ויש דעה שק\"ש נמי ד\"ת הוא כו'. ומ\"ש וקשרתם לאות על ידך כו' הוא בחי' מצות מעשיות. הענין הוא כי יש בנ\"א שאין בהם בחי' ואהבת כו' דהיינו התעוררות נקודת הרצון ואיך יתעורר על ידם בחי' בעל הרצון, ובאמת אמרז\"ל כשם שא\"א לעולם בלא רוחות כך א\"א לעולם בלא ישראל דמשמע דלא פלוג כלל דקיום העולמות הוא ע\"י כל ישראל אפי' אותם שאין בהם בחי' ואהבת כו'. אך הענין הוא כי כל ישראל מלאים מצות כרמון אפי' פושעי ישראל והמצות המה פנימי' רצונותיו, וע\"י עשיית המצוה מעוררים למעלה בחי' בעל הרצון. והעיקר הוא מצות צדקה כי מצות צדקה היא כוללת כל המצות כמ\"ש וצדקה תהי' לנו כי נשמור לעשות את כל החוקים כו', כי רמ\"ח מצות רמ\"ח אברין דמלכא, וכמו למשל האבר שבכל אבר יש חיות פרטי כו' אבל מצות צדקה היא כוללת כל המצות כו'.\n<b>ועתה</b> צ\"ל מ\"ש בפ' והי' א\"ש תשמעו בכל לבבכם ובכל נפשכם ונתתי מטר ארצכם כו' ואח\"כ כתיב השמרו לכם פן יפתה לבבכם וסרתם ועבדתם אלקים אחרים, דלכאורה יפלא מאד אחר שאמר בכל לבבכם ובכל נפשכם בחי' מס\"נ בתכלית למה צריך להזהיר על אלקים אחרים שלא יכפור לגמרי בה', כי איך שייך באדם שהוא בתכלית מס\"נ לה' לבדו שיוצרך הזהירה לבלתי יכפור בה' לגמרי רק שייך להזהיר אותו שלא יפול מאותה מדרגה"],[1900740377,"שהוא בה. וגם כזה ג\"כ אינו מובן ענין אנכי ולא יהי' לך, שאנכי הוא בחי' כתר ורצון אנכי מי שאנכי ואיך שייך שם צריכו' הזהירה לא יהי' לך שלא לכפור בה' כו'. להבין זאת צריך להקדים בענין הפלוגתא בענין חושך אם הוא בריאה אם לאו, שהרמב\"ן סובר שהחושך אינה בריאה שהרי לא נכתב בעשרה מאמרות יהי חושך כמו יהי אור, אלא החושך הוא העדר אור דהיינו ענין חושך לא שייך רק אחר שיש מציאת אור ונעדר האור אזי ממילא יחשך. ויש סתירה לזה שהלא כתיב בראשית ברא אלקים כו' והארץ היתה תהו ובהו וחושך כו' שגם שלא היתה אור הי' חושך בעולם וכדאיתא במדרש אור וחושך היו משתמשין בערבוביא כו', וכמ\"ש ויהי ערב ויהי בוקר כו'. אך הענין ששניהם אמת, כי מ\"ש ברישא חשוכא והדר נהורא חשך זה הוא בריאה אבל החשך סתם אינו נברא כלל רק הוא העדר מציאת האור, כמו למשל כשעוצם עינו מלראות שלא נסתלק האור לגמרי שהרי מציאת האור ישנו בעין כו'. ויובן זאת בעבודת ה' כי הנה ארז\"ל אין רע יורד מלמעלה רק כמ\"ש תיסרך רעתך שע\"י רעת האדם נברא מקטרג ומייסר, כמ\"ש על כי אין אלקי בקרבי מצאוני הרעות האלה כו', כי כשיש גילוי אלקות אזי אין מקטרגים כלל אבל כשאין אלקי בקרבי מצאוני הרעות כו', ונמצא שהרע אינו בריאה כלל והוא ענין חסד ודין שחסד אל כל היום כו' הוא בריאה אבל מדה\"ד אינה בריאה, ובאמת בבחי' השתלשלות יש בחי' קו ימין וקו שמאל חו\"ג כו'. אך הענין הוא כי בשכל ומדות יש חסדים וגבורות כמו שכל נוטה כלפי זכות ושכל נוטה כלפי דין. וכן בלב יש מדת החסד ומדת הגבורה. וכמו\"כ יובן למעלה דכתיב ויבאו בני האלקים להתיצב על ה' ויאמרו החנם ירא איוב כו' שהוא הקטרוג בשכל וסברא כו'. או כמו בשעת קרי\"ס שאמר מדה\"ד מה נשתנו אלו מאלו כו'. ומה שאמרו אין רע יורד מלמעלה קאי על בחי' רצון אשר למעלה מהתחלקות קוין. ויובן"],[1900740378,"עפ\"י משל באדם שרוצה בחיי נפשו שאין שייך לחלק על ב' קוין לומר שהוא רוצה לחיות זהו קו א' וקו הב' הוא שאינו רוצה למות, כי מילתא חדא היא כו'. וכמו\"כ יובן למעלה בענין אנכי ולא יהי' לך בדבור אחד נאמרו שאנכי הוא בחי' פנימי' כתר שם אנכי ולא יהי' לך בדבור א' נאמרו שאנכי הוא שרש רמ\"ח מ\"ע ולא יהי' לך הוא שרש שס\"ה ל\"ת שהוא נגד רצון העצמי ונמצא שהם בדיבור א'. ובזה יובן מ\"ש וסרתם ועבדתם כו' אחר בכל לבבכם ובכל נפשכם, דהיינו שמיד שתסורו מנקודת הרצון אזי ועבדתם כו', וזהו ג\"כ ענין אנכי ולא יהי' לך כו'.\n<b>ובזה</b> יובן מ\"ש ראה אנכי נותן לפניך היום ברכה וקללה, שמבחי' אנכי יסתעפו שניהם הקללות והברכות שעל הר גריזים ועל הר עיבל כו'. וזהו את הברכה אשר תשמעו לנקודת הרצון ואת הקללה אם לא תשמעון לנקודת הרצון אזי ממילא יבא היפוכו שהוא שס\"ה ל\"ת. ומ\"ש ראה נתתי לפניך את החיים והטוב ובחרת כו' דתלוי מצד הבחירה, הענין הוא שכאשר נתתי לפניך שנשמות בגופי' אז הוא הבחירה ויכול לבחור ברע ולמאוס בטוב, אבל בשרשם הוא בחי' עצמי כו' כנ\"ל וד\"ל."],[1900740379,"<h3>אחרי ה' אלקיכם תלכו</h3>\n<b>שבת פ' ראה הנ\"ל</b>\n<b>אחרי</b> ה' אלקיכם תלכו ואותו תיראו ואת מצותיו תשמרו ובקולו תשמעו ואותו תעבודו ובו תדבקון כו'. הנה כתיב כי מנסה ה' אלקיכם אתכם לדעת הישכם אוהבים את ה' בכל לבבכם ובכל נפשכם ובא אליך הנביא ויתן לך אות או מופת כו'. וצ\"ל ענין הנסיון מלמעלה לדעת הישכם אוהבים והלא הכל גלוי וידוע לפניו כל תעלומות, דאין ספיקא קמי שמיא ויודע כל עבודת האדם בפרט במוח או בלב, ולמה צריך לנסיון שאח\"כ ידע הישכם אוהבים כו'. וגם באמת אינו צריך לנסות כלל שבודאי יש בכל נפש מישראל בחי' בכל לבבכם ובכל נפשכם, וראי' לדבר ממס\"נ על קדה\"ש שגם קל שבקלים ימסור נפשו שלא להמיר דתו בפו\"מ וכמו שנראה בבע\"ת שנתעורר פתאום לה' במס\"נ ממש כמו ראב\"ד שיצאה נשמתו בבכי' כו' ונתן צוציתא. אך ענין הנסיונות הוא מה שטבע האדם שאינו רואה חוב לעצמו וכל דרכי איש זך בעיניו והוא בעיניו כשר וישר, ואינו עושה חשבון עם נפשו כלל איך שויכל בהבל ימיו כו', וגם אם פעם מוצא איזה חוב עליו אזי מכביד לבו ומוצא קולות לעצמו עד שנעשה נקי בעיניו. והסבה זו היא מלמעלה כענין ואני הכבדתי את לב פרעה כו' ובלשון גמרא אין מספיקין בידו לעשות תשובה, ובזוהר נק' נזיפא דמארי' היינו שגם באיזה פעם מתעורר בנפשו לעשות חשבון עם נפשו מכבידין לבו שאינם רוצים כלל עבודתו ומוחו ולבו כלל, ומזמינים לו הרבה מונעים ומנגדים. והסבה לזה הוא מלמעלה שכך הוא רצון ה' להיות נכבד לבו, אבל זולת זה הי' בא בקל בגילוי בחי' בכל לבבך כו'. והטעם לזה הוא כי כך עלה ברצונו להיות לו תענוג מזה דייקא שיהי' הסתר אלקות ומתוך ההסתר דייקא יאיר אור האלקי והוא כענין קליפה ופרי שא\"א לבא להפרי כ\"א ע\"י שברון הקליפה, כמו\"כ יובן בענין הנ\"ל שא\"א לבא לאור בחי' בכל לבבכם כו' שיש בכל נפש מישראל כ\"א ע\"י שברון הקליפה. והשברון הוא המרירות להיות נשבר לבו בקרבו מזה גופא על גודל ההסתר מה שלבו נכבד כו'."],[1900740380,"<b>וכמו\"כ</b> ג\"כ כעת בענין המו\"מ שנראה אדם שהוא המרויח והוא המצליח כחי ועוצם ידי כו' שאם מצליח הוא מצד חכמתו ואם לאו אזי הוא מצד שלא עשה כהוגן בענין העסק, ובאמת כתיב השלך על ה' יהבך והוא יכלכלך שהכל תלוי מצד אלקו', וכמו דהמע\"ה שאמר כי ממך הכל ומידך ממש נתנו לך כו'. ולפעמים יכול להיות שלפי עשיית העסק הי' צריך להפסיד ומ\"מ מרויח ונק' זה בשם גלות השכינה כמ\"ש בכתבי האריז\"ל דהיינו מה שמרויח בעסקיו הוא מחמת ברכת אלקות ששורה בו והוא מדמה שהוא בעצמו העושה כחי ועוצם ידי כו' זהו הנק' בשם גלות השכינה. והגם ששם שמים שגור בפי הכל ואומרי' יהי שם ה' מבורך כו' אין זה אלא בחי' חיצוני' כו', ולעתיד כתיב וישבו איש תחת גפנו כו' שהפרנסה שיגיע לכל אחד ידע וישיג שה' הוא הנותן לו זאת, ובחי' זו יהי' אצל כולם אפי' אצל הפח\"ע שיהיו. אבל כעת הוא הסתר אלקות ונראה שהאדם עצמו עושה ולא ה' פעל כל זאת רק כשמבטשין אותו כמו בעסק המו\"מ גופא שמפסיד פעם ושתים אז עולה ה' בזכרונו שיד ה' עשתה זאת כמו שיהי' לעתיד בלי שום ביטוש כלל, וכעת הוא דייקא ע\"י ביטושי' והוא ג\"כ כענין קליפה ופרי הנ\"ל שא\"א לבא להפרי כ\"א ע\"י שברון הקליפה, והשברון הוא ע\"י מבטשי' הנ\"ל.\n<b>וזהו</b> ענין הנסיונות כי מנסה אתכם ה' כו' ובא הנביא שהי' מטעים לו בדברים בטוב טעם ומ\"מ צריך שלא ישמע לו. וכמו\"כ עכשיו ענין הנסיונות הוא טרדת הפרנסה שעי\"ז אינו רואה חוב לעצמו כו' ככל הנ\"ל, והתענוג שיש לה' מזה הוא יותר נעלה משיהי' בגילוי בחי' בכל לבבכם כו', אלא עיקר התענוג הוא דייקא כשיש מונעים ומנגדים המכבידי' לבו ומ\"מ שב לה' ושובר הקליפה כו'. והטעם מה שבעבודת ה' הוא ע\"ד זה ובמו\"מ הוא מפני שבהשתלשלות העולמות הוא ג\"כ עד\"ז. והענין יובן ע\"פ מ\"ש כי אל דעות הוי', ב' דעות מיש לאין ומאין ליש. והוא ע\"פ מ\"ש כי עמך מקור חיים שהוא ית' מקורא דכולא, ופעם כתיב אתה אל מסתתר כו'. הענין הוא כי השפעת העולמות מאלקות שהוא בחי' א\"ס נק' האלקות בשם יש אמיתי מקור כולם והוא בחי' מיש לאין שאלקות הוא היש אמיתי והעולמות נק' בשם אין כולא קמי' כלא חשיבי כמ\"ש הן כל הגוים כאין נגדו מאפס ותוהו נחשבו כו'. ומ\"ש"],[1900740381,"אתה אל מסתתר הוא על השפעה אלקי' שבתוך העולמות כח הפועל בתוך הנפעל שאינו נראי' רק גוף העולמות והכח אלקי שבהם הוא מוסתר ונעלם ונק' בשם מאין ליש שהכח אלקי הוא בבחי' אין והעולם נראה ליש, כמו למשל הנפש שמחי' הגוף שאינו נראה רק הגוף וחיות הנפש הוא מוסתר ואינו נראה, ומפני שהשפעת אלקות לעולמות הוא עד\"ז לכן גם בעבודת ה' הוא עד\"ז.\n<b>והנה</b> בחי' זו נק' אחרי ה' תלכו בחי' אחוריים לבד, שלעתיד יהי' התגלות פנימי' כמ\"ש וידע כל פעול כי אתה פעלתו, ולא האדם לבד. ולכן יבוטלו טורפים ומזיקים כמ\"ש לא ירעו ולא ישחיתו כו' ופרה ודוב תרעינה ומכש\"כ באדם שיבוטל. ולא כמו עכשיו שיש טורפים ומזיקים בחיות ובהמות וגם במין האדם איש את רעהו חיים בלעו, אבל לעתיד לא יהי' רע כלל וכמ\"ש ובאו במערות צורים ובנקרת הסלעים מפני פחד ה' כו'. ופחד הוא מקרוב כי מדבר הרחוק לא יפחד כלל, כי הפחד הוא דייקא מדבר הנראה לעין, וכעת הוא בחי' אחרי ה' תלכו בחי' אחוריים לבד.\n<b>ואותו</b> תיראו הוא בפ' שני' דק\"ש. הענין הוא כי יש ד' בחי', דחילו ורחימו רחימו ודחילו. ודחילו ראשונה שהוא בחי' יראה תתאה הוא בפסוקי דזמרה שהוא הסיפור בהתהוות העולמות כמ\"ש הללוהו במרומים כו', וגם בשתים לפניה שהוא סיפור איך שהמלאכים משבחים ומפארים כו', כ\"ז נק' בשם אחרי הוי' כו' שהוא ההתבוננות בבחי' אחוריים שהוא התהוות העולמות שהוא בחי' מאין ליש. וגם המלאכים הם בחי' יש גם שהם בבחי' ביטול כמ\"ש וצבא השמים לך משתחוים מ\"מ הם בבחי' יש רק שהיש הוא בטל וכמ\"ש שרפים עומדים ממעל לו, ממעל לשכינתי' שכח אלקי הוא בתוכם כו'. ומהתבוננות זו שהוא בחי' אחרי הוי' מזה מקבלים בנ\"י יראה והוא בחי' יראה תתאה שהוא ההסכם על הפו\"מ. ובפ' ראשונה דק\"ש ואהבת כו' הוא ע\"י ההכנה מאהבת עולם"],[1900740382,"אהבתנו שהוא האהבה שמאא\"ס לנש\"י כמו שכתוב בסיום הברכה בא\"י הבוחר בעמו ישראל באהבה, עי\"ז נתפעל בלב ישראל אהבה לאא\"ס וזהו ואהבת כו'. ובאהבה זו יש ב' אופנים הא' הוא אהבה אשר לפי שעה ואח\"כ חולפת ועוברת, והב' הוא אהבה תמידית אשר לא יופסק כלל כי בואהבת יש ב' פי' הא' הוא לשון ציווי והוא נגד אהבה אשר יכולה לפסוק, והב' הוא ואהבת לשון להבא שבודאי תאהוב והוא בחי' אהבה שני' אהבה תמידי' והוא ענין ב' בחי' רחימו. ומ\"ש ואותו תיראו הוא נגד דחילו הב', כי בתיראו יש ב' פי', הא' הוא לשון ראי' והב' לשון יראה והיא בחי' יראה עילאה, והכל הוא ענין א' כמ\"ש הן יראת ה' היא חכמה כו'. והוא הדוגמא דלעתיד שיהי' פחד ה' כו' והוא כמארז\"ל אמר רבי יהושע בן קרחה למה קדמה פ' שמע לוהי' א\"ש כדי שיקבל עליו עומ\"ש תחלה ואח\"כ יקבל עליו עול מצות, כמשית\"ל. וזהו ואותו תיראו, אותו בעצמו תיראו ולא אחרי הוי' כו' והוא הנק' ירא בושת, בושה מקמי קוב\"ה וכמאמר כל נהוראן אתחשכאן קמי' אפי' אור צח ומצוחצח אוכם הוא לגבי עלת כל העלות כו', והבושה אינו אלא ע\"י ראי' מקרוב משא\"כ מרחוק לא יפול בושה כלל.\n<b>והנה</b> ב' בחי' אלו הוא מלמטה למעלה. ואח\"כ כתיב ואת מצותיו תשמרו ובקולו תשמעו שהוא מלמעלה למטה. וביאור הענין הוא כי הנה כתיב שומר מצוה לא ידע דבר רע כו', כי ע\"י עשיית האדם מצוה אזי נעשה שומר ומקיף לבלתי יפול ברע. וגם התועלת הוא שאם נפל באיזה רע שלא ישתקע שם ליקח אותו משם כו'. וזהו משארז\"ל עשה רצונו כרצונך כדי שיעשה רצונך כרצונו שע\"י עשיית רצונו שהוא מצות מעשיות כי המצות המה רצה\"ע, עי\"ז יעשה רצונך כרצונו שלא תפול ברצון והתקשרות זר כו'. ובטל רצונך הוא מצות ל\"ת כו'. וזהו ואת מצותיו תשמרו.\n<b>ומ\"ש</b> ובקולו תשמעו הוא ת\"ת שהוא השימור להמצוה. וצ\"ל שהלא מצוה בעצמה היא בחי' שומר ולמה צריך להמצוה גופא שמירה. הענין הוא כי הנה כתיב נר מצוה ותורה אור שהמצוה נק' בשם נר והנר הוא שמן ופתילה שהוא ענין אחיזה באיזה דבר. ועבירה מכבה מצוה שע\"י עבירה עושה"],[1900740383,"כלי אחר עד שמכבה מצוה. ותורה נק' בשם אור כמו למשל גוף האור שאינו נכבה רק הנר הוא נכבה. ולכן ארז\"ל ת\"ח אין אור של גיהנם שולטת בהן כו' ות\"ח נק' העוסקים בתורה כי התורה אור היא כו'. וזהו ובקולו תשמעו לקול דבר ה' שעי\"ז יהי' נשמר המצוה שלא יכבה, וגם התועלת הוא שאם כבר נכבה המצוה ע\"י איזה עבירה אזי התורה מאירה אותם כמ\"ש ותורה אור כו'.\n<b>ואותו</b> תעבודו ובו תדבקון. הנה ואותו תעבודו הוא בחי' עבד דהיינו שצריך לקיים המצות דייקא בבחי' עבד בבחי' עול, והוא היותר נעלה גם מאותו תיראו שהוא בחי' בן. והענין הוא כי יש מצות אשר בנ\"י קבלו אותם בבחי' חביבות כמו מצות מילה ושבת וכו', ויש מצות אשר הם בבחי' עול כענין מארז\"ל אל יאמר אדם אי אפשי בבשר חזיר אלא אפשי אבל אבי שבשמים גזר עלי, ועי\"ז דייקא ובו תדבקון. וענין הדביקות הוא ענין התאחדות כמו הדבק שמחבר ב' דברים יחד. וצ\"ל כי ענין דביקות לא שייך אלא בלב או במוח שנדבק לו זולתו במוחו (הנק' בל\"א צו גיקלעפט) כמו אהבת דוד ויהונתן שאהבת נפשו אהבו, שהנפשות היו מקושרות ודבוקות יחד, אבל איך שייך ענין דביקות במעשה. אך הענין הוא כמ\"ש סוף דבר הכל נשמע את האלקי' ירא ואת מצותיו שמור כי זה כל האדם, כי כל זה נק' תחלה תלכו תיראו כו', אבל מצות בפו\"מ הם נק' סוף וכתיב כי ז\"ה כ\"ל האד\"ם כו'. וזהו ובו תדבקון בנו\"ן פשוטה ולא כתיב תדבקו כמו תיראו תשמעו דלא כתיב תשמעון, כי ענין הנון פשוטה מורה על המשכת אלקות למטה מטה כמ\"ש ימינך פשוטה לקבל שבים שגם המקושר בעמקי רע יתעורר בתשובה והוא ע\"י ואותו תעבודו, שהוא קיום המצות בבחי' עבד ולא מצות אנשים מלומדה מצד הרגלו מאביו אלא בבחי' קבלת עול כענין אפשי בשר חזיר אבל אבי כו', עי\"ז דייקא דייקא ובו תדבקון כו'.\nאחר שבת פ' ראה נסע אדמו\"ר שי' לראהאצאוו . . . עד קודם ר\"ה."],[1900740384,"<h3>כי המצוה</h3>\n<b>בעז\"ה, ערב ר\"ה</b>\n<b>כי</b> המצוה הזאת אשר אנכי מצוך היום לא נפלאת היא ממך ולא רחוקה היא לא בשמים ולא מעבר לים כו' כי קרוב אליך הדבר מאד בפיך ובלבבך לעשותו. כי המצוה הזאת קאי על מצות התשובה. וצ\"ל מפני מה בכל המצות לא נאמר בהן אנכי כ\"א במצות התשובה. וגם להבין מ\"ש דרשו ה' בהמצאו קראוהו בהיותו קרוב אלו עשי\"ת, ומבואר הקושיא בספרים דהלא בכל יום צריך לעשות תשובה ומהו דייקא עשי\"ת. וגם להבין מ\"ש זה היום תחלת מעשיך זכרון ליום ראשון כו'. וההקדמה להבין זאת הוא ממאמר הזוהר תלת קשרין מתקשראן, ישראל מתקשראן באורייתא ואורייתא בקוב\"ה, שהן שלשה קשרים ישראל הם קשר התחתון וקוב\"ה הוא קשר העליון ואורייתא הוא קשר האמצעי ומאחר שמקושרים זב\"ז הרי הם כקשר א'. ופי' ישראל מתקשראן באורייתא קאי על נשמות כו'. וגם אמרו בזוהר אורייתא סתים וגליא, קוב\"ה סתים וגליא, וידוע דגליא דקוב\"ה הוא מה שהוא מחי' את כולם כח הפועל בנפעל בחי' עלמין דאתגליין, וסתים הוא מה שהוא סוכ\"ע כמ\"ש המלך המרומם והמתנשא מימות עולם. ואורייתא סתים וגליא ג\"כ דהיינו תורה הנגלית לנו כמו אנכי ולא יהי' לך דכתיב וירד ה' על הר סיני נק' בשם גליא וסתים הוא התורה כמו שהיא בבחי' סתימות כמארז\"ל תורה קדמה לעולם כמ\"ש ואהי' אצלו אמון שעשועי' כו' בחי' חכמתו העצמי'. והנה ממילא מובן שבנש\"י יש ג\"כ סתום וגליא מאחר שהן מקושרים אב\"א כמאמר תלת קשרין כו', ומאחר שבתורה וקוב\"ה יש סתים וגליא מוכרח להיות שבנשמות יש ג\"כ סתים וגליא, ובנשמות נק' בחי' גליא הכח שיש להם להתפעל מהתבוננות בחי' ממכ\"ע איך שאתה מחי' את כולם, וסתום הוא ההתבוננות בבחי' סוכ\"ע."],[1900740385,"<b>והנה</b> כתיב המחדש בטובו בכל יום מע\"ב, מחדש מאין ליש, והחידוש הוא בב' בחי' הן בבחי' ממכ\"ע שהוא בחי' גליא והן בבחי' סתום שהוא ע\"ס דלא אתגליין, כי מאחר שנק' בשם סובב לעלמין הרי הוא ג\"כ בכלל השפעה וצריך לחדשו תמיד בכל יום. וכן בתורה כתיב והיו הדברים האלה אשר אנכי מצוך היום, בכל יום ויום יהיו בעיניך כחדשים, וכמו שאנו מברכי' בא\"י נותן התורה ולא נתן לשון עבר אלא נותן לשון הוה. והחידוש הוא ג\"כ בבחי' סתום וגליא שבה וכמארז\"ל שלש שעות ראשונות יושב הקב\"ה ועוסק בתורה שניות יושב ודן שלישית יושב וזן כו', שיושב ודן וזן תלוי לפי שיושב ועוסק בתורה שהוא חכמתו העצמי', ומאחר שהחידוש הוא באורייתא וקוב\"ה, יש חידוש ג\"כ בנשמות כמ\"ש חדשים לבקרים כו', וא\"כ צ\"ל מהו היתרון מעלה של ר\"ה שנק' בשם זה היום תחלת מעשיך.\n<b>אך</b> להבין כל זאת צריך להקדים מ\"ש ראה נתתי לפניך את החיים והטוב ואת המות והרע ובחרת בחיים, שכעת הבחירה חפשית ביד האדם ויכול לבחור ברע כו' ולעתיד כתיב וידע כל פעול כי אתה פעלתו ויבין כל יצור כי אתה יצרתו, כל פעול דייקא ולא האדם לבד, כמו הדוגמא שהי' קודם חטא אדה\"ר שהי' גילוי אלקות על כל הברואים. כמו\"כ לעתיד כתיב ונגלה כבוד הוי' וכמ\"ש ובאו במערות צורים ובנקרות הסלעים מפני פחד ה' כו'. ועוד ראי' שיהי' גילוי אלקות שהרי יבוטלו טורפים ומזיקים כמ\"ש וגר זאב עם כבש ופרה ודוב תרעינה יחדיו ירבצו ילדיהן כו' וכמ\"ש לא ירעו ולא ישחיתו כו' מפני שיהי' גילוי אלקו' על כל הברואים, והוא מפני שלא יהי' רע כלל כמ\"ש ואת רוח הטומאה אעביר מן הארץ כו' ויהי' אז הגילוי אלקות כמו טבע בנפשו, כמו עד\"מ שטבע האש לשרוף וטבע המים לכבות, כמו\"כ יהי' לעתיד כמו טבעי' בנפש בחי' אלקו' כמו כעת ענין מילי דעלמא כו', ולא כמו הדעת דכעת שמצד התבוננות שאינו אלא לפי שעה לבד ואחר זמן חולפת ועוברת כו'."],[1900740386,"<b>והדוגמא</b> לזה כמו המלאכים דכתיב וצבא השמים לך משתחוים שביטולם הוא מחמת שמשיגים כח אלקי המהוה אותם, ולכן משתחוים ובטילים בהשתחואה תמידי' רגע לא יפסוקו כי אין בזה בחירה כלל שיהי' יכולים שלא ישתחוו כו'. זהו דוגמא להבין ענין דלעתיד, אבל עכשיו ניתנה הבחירה ביד האדם כי באמת צ\"ל מצד הנשמה כמו טבע שיבחר בטוב וימאס ברע וכמ\"ש בפסוק בלשון חיים וטוב ומות ורע, כמו עד\"מ דבר האהוב וטוב לגופו שנמשך אחר זה בכל לב ונפש, ולהיפך דבר המזיק לנפשו הוא מתרחק מזה תכלית הרחקה בלי שום בחירה כלל, כמו עד\"מ שילך באש כו'. וכמו\"כ יובן בעבודת ה' שמ\"ע הוא חיים וטוב להנשמה, ומל\"ת שהוא תועבת ה' הוא מות ורע לנשמה, ולעתיד יהי' כמו\"כ, אבל עכשיו כתיב ובחרת בחיים שהגוף מסתיר על נשמה האלקי' עד שיכול לבחור ברע ולמאוס בטוב כו', ולכן כתיב ובחרת בחיים. ובצד\"ג יש ג\"כ כעת שבחי' אלקות דהיינו ההתפעלות במוח או בלב או מעשה בפו\"מ הוא כמו חיות לנפשם, וההיפך דהיינו הרהור רע במוח ותשוקה זרה וכש\"כ מעשה בפו\"מ הוא כמו מות כו'. והבחירה הוא מצד הדעת כמ\"ש ישראל לא ידע עמי לא התבונן הוי גוי חוטא עם כבד עון כו'.\n<b>אך</b> הכח זה גופא שכעת שמצד הבחירה הוא הכח שמאיר בנשמה בכל בוקר כמ\"ש חדשים לבקרים רבה אמונתיך, שבכל בוקר ובוקר נתחדש כח אמונה זו. והכח זה נק' בשם ממוצע כמו עד\"מ הדם שבו מתלבש החיות כמ\"ש כי הדם הוא הנפש שהוא בחי' ממוצע, כי הנפש היא בחי' רוחני' והגוף הוא גשמי וכדי שיחי' הנפש את הגוף צריך לזה ממוצע, והממוצע הוא הדם שע\"י המאכל שאדם אוכל ונתברר הפסולת נדחה לחוץ ומהמובחר נעשה דם ועולה לכבד ומכבד ללב ומלב למוח כו'. כמו\"כ יובן עד\"מ למעלה כי הנה כתיב נשמה שנתת בי כו' אתה בראת שגם נשמות הם בחי' בריאה וא\"כ אינם בחי' אלקות עצמו, וכדי שיתפעלו מאלקות צריך לזה ממוצע והממוצע הוא הכח שמאיר בכל בוקר ובוקר וכמ\"ש כל אשר תמצא ידך לעשות בכחך עשה ואמרו בזוהר האי כוחא קדישא ולא קאי על כח הגוף, ולכן אין יום א' דומה לחבירו שפעם מתפעל במוח ופעם בלב דייקא ולא במוח, או במעשה לבד שאין לו לא התפעלות הלב ולא התפעלות המוח רק הביטול בבחי' מעשה"],[1900740387,"בסו\"מ וע\"ט כו', כי הוא תלוי לפי אופן כח הנשמה שמאיר בו, ופעם אינו מאיר כלל ונק' בשם יומא דפגרא בחי' מות ורע וכמ\"ש ימים יוצרו ולא אחד בהם, כתי' לא באלף וקרינן לו בוי\"ו, הענין הוא כי יש ימים שמאיר בהם הכח אלקי במוח או בלב או במעשה אזי ולו אחד בהם בויו שיש בהם הארת בחי' אחד. ואותם ימים שאין מאיר בהם כלל נק' ולא אחד בהם באלף. והטעם מבואר בס' הגלגולים. והנה חידוש זה שמאיר בנשמות הוא בב' בחי' כמ\"ש רבה אמונתיך שהוא בחי' אמונה גדולה. כי יש ב' בחי' אמונה, פי' אמונה הוא ענין התפעלות אלקות ויש אמונה גדולה שהוא ע\"י התבוננות דבחי' סוכ\"ע ויש אמונה קטנה שהוא ע\"י התבוננות דבחי' ממכ\"ע ונק' בשם סתום וגליא. וא\"כ לפי זה הדרא קושיין לדוכתי שהרי בכל יום יש התחדשות הנשמות.\n<b>וכמו\"כ</b> יובן בענין אורייתא סתום וגליא, דהנה כתיב זאת נחמתי בעניי כי אמרתך חייתני, פי' בעניי הוא עני מן הדעת דהיינו אחר התפלה כל היום שאז נפסק ההתפעלות כי א\"א לילך כל היום בהתפעלות אלקו' ונק' אז בעניי. ויכול ליפול בהבלי עוה\"ז אך זאת נחמתי כי אמרתך חייתני שהוא הדיבור בד\"ת כי ישראל מתקשראן באורייתא דס\"ר אותיות התורה הוא נגד ס\"ר נשמות ולכן ע\"י לימוד אדם בד\"ת אפי' פרק א' שחרית ופרק א' ערבית או ב' וג' פסוקים ויש דעה לחד מ\"ד בגמרא שק\"ש נמי ד\"ת הוא, אזי נעשה לו בחי' מקיף שהוא שמירה שלא יפול ברצונות זרים, וה\"ז כמשל חומה הסובב את העיר שגם שמקיף כל העיר יחד מ\"מ תלוי המקיף לפי ערך יישוב העיר כמ\"ש פרזות תשב ירושלים, שיכול להיות למזרח עד אין שיעור וכן לכל ד' סטרין כו', כמ\"ש בשכבך תשמור עליך והקיצות היא תשיחך. או שאם אירע ונפל באיזה רצון זר שלא ישתקע שם כו' כידוע. והחידוש באורייתא הוא ג\"כ בסתום וגליא כנ\"ל. וכמו\"כ בהשתלשלות העולמות בבחי' סתום וגליא. אך ההפרש שבין ר\"ה לכל השנה הוא, כי בכל השנה הוא אינו התחדשות חדשה אבל בר\"ה הוא התחדשות חדשה לגמרי.\n<b>והענין</b> יובן עפ\"י משל הידוע ההפרש שבין אכילה לרפואה, כי האכילה הוא לחבר הנפש בגוף ולא להמשיך חיות חדש, דהיינו שאם לא"],[1900740388,"יאכל ב' ימים אזי נסתלק החיות, והתועלת מהמאכל הוא לחבר חיות הנפש בגוף, אבל הרפואה הוא ענין סם חזק הממשיך חיות חדש לגמרי דהיינו שגם שיש איזה קלקול בדמים ע\"י הרפואה יומשך חיות חדש. וכמו\"כ יובן בין התחדשות החיות של כל השנה להתחדשות החיות שבר\"ה, שבכל השנה ההתחדשות שבנשמות ובאורייתא ובקוב\"ה אינו התחדשות מעיקרו כי כל המצות הוא לשם יחוד קוב\"ה ושכינתי' יחוד סובב בממלא כו', אבל בר\"ה הוא התחדשות חדשה.\n<b>וביאור</b> הענין כי בכל השנה ע\"י אתעדל\"ת אתעדל\"ע וצריך לילך מדרגא לדרגא, תחלה בחי' ממכ\"ע ואח\"כ סוכ\"ע, ומאחר שאתעדל\"ע הוא מצד אתעדל\"ת אינו נתעורר רק בחי' סוכ\"ע כמ\"ש המלך המרומם והמתנשא מימות עולם שהוא ההתנשאות אשר מימות עולם לבד, אבל בר\"ה אתעדל\"ע הוא מצד עצמו והוא מקום אשר אין אתעדל\"ת מגעת שם כלל, ולכן יש בכוחו למלאות ולהשלים כל החסרונות והפגמים כי קמי' כחשיכא כאורה. וז\"ש אנכי אנכי הוא מוחה פשעיך למעני, שיש ב' בחי' אנכי דהיינו בחי' אנכי שמתנשא מימות עולם לבד, ואנכי הב' הוא בחי' התנשאות בעצם, ואנכי זה דייקא הוא מוחה פשעיך כו'. והוא ענין מ\"ש אשירה לה' כי גאה גאה, גאה על גיותניא כו' בחי' אנכי שבעצמותו, ובחי' אנכי זה הוא המתגלה בר\"ה. וכידוע דבכ\"ה באלול נברא העולם ואדה\"ר נברא בר\"ה ואמר ה' מלך גיאות לבש לבש, שלבש ב' מיני גיאות הנ\"ל, ולכן נק' ר\"ה דייקא בשם זכרון ליום ראשון שהוא המשכת חיות חדש לגמרי. והמשל לזה ידוע שהוא שני בנ\"א א' עומד בהר גבוה והשני עומד במקום עמוק, שיש ב' אופנים באופן יחודם או שהתחתון יעלה למעלה או שהעליון ירד למטה, ובכל השנה אתעדל\"ת מעורר אתעדל\"ע הוא כמשל עליית התחתון לגבי העליון שתלוי לפי אופן ההכנה של התחתון, אבל בר\"ה כתיב"],[1900740389,"השיבנו ה' אליך מלמעלה כו' שהעליון יורד לגבי התחתון מצד עצמו בלי התעוררות המקבל כלל. וזהו מ\"ש דרשו ה' בהמצאו קראוהו בהיותו קרוב אלו עשי\"ת שאז הוא בהמצאו ובהיותו קרוב.\n<b>ועתה</b> יתפרש היטב ענין פי' הפסוק כי המצוה הזאת אשר אנכי כו' דקאי על מצות תשובה, אשר אנכי כו' הוא בחי' אנכי שבעצמותו, כי כח התשובה מגיע עד שרש הראשון מפני שהיא בחי' כלל ולא ענין פרטי להתפעל במוח לבד או בלב כו'. והתשובה היא לעצמותו דייקא כמ\"ש והרוח תשוב אל האלקים אש\"ר נתנ\"ה כו'. וזהו לא נפלאת ולא רחוקה לא בשמים כו', פלא ורחוק הוא ענין ממכ\"ע וסוכ\"ע, כי פלא נק' דבר אשר מובן מעט עכ\"פ כמו למשל רב המשפיע שכל לתלמיד אם התלמיד מבין קצת ומה שהוא למעלה מהשגת שכל התלמיד אינו מבין, זה נק' בשם פלא, משא\"כ אם אינו משיג כלל לא שייך לקרות בשם פלא אלא בשם רחוקה שרחוק לגמרי כו'. והוא ענין ממכ\"ע וסוכ\"ע. וזהו כי המצוה הזאת שהוא מצות התשובה אשר אנכי שבעצמותו כו' ולא כפלא ורחוק שגם רחוקה הוא בחי' סובב של עלמין לבד, אבל התשובה מגיע לעצמו'. ואח\"כ מפרש הכתוב שלא תאמר מאחר שהוא מדרגה גבוה מאד א\"א להגיע לזה כלל, לזה אומר הכתוב כי קרוב אליך הדבר מאד בפיך ובלבבך לעשותו בחי' תשובה מטעם שכתוב דרשו ה' בהמצאו קראוהו בהיותו קרוב שהעליון יורד מצד עצמו כנ\"ל. ולכן נק' יוכ\"פ בשם יום כפורים שהיום בעצמו מכפר כמ\"ש כי ביום הזה יכפר עליכם כו' שמטהר כל לכלוך וחטא ונק' בשם נהרא דאפרסמונא דכיא כו', והתשובה שמלמטה הוא הכנה שיתקבל במקבלים כו' וד\"ל."],[1900740390,"<h3>זה היום תחלת מעשיך</h3>\n<b></b><b>ר\"ה תקע\"ח לפ\"ק, תורת אדמו\"ר</b>\nר\"ה תקע\"ח לפ\"ק, תורת אדמו\"ר\n<b>זה</b> היום תחלת מעשיך זכרון ליום ראשון, וצ\"ל מפני מה נק' ר\"ה בשם תחילת מעשיך זכרון ליום ראשון והלא בכל השנה הוא התחדשות החיות הן בנשמות כמ\"ש חדשים לבקרים כו' שנתחדש ב' בחי' אמונה כנ\"ל, וכן באורייתא ובהשתלשלות העולמות כמאמר תלת קשרין כמבואר לעיל באריכות. וגם להבין משארז\"ל ע\"פ דרשו ה' בהמצאו קראוהו בהיותו קרוב אלו עשי\"ת, והלא ב\"ק מכרזת בכל יום שובו בנים שובבים כו'.\n<b>להבין</b> זאת צריך להקדים מ\"ש כי אלף שנים בעיניך כיום אתמול, הענין הוא כי מה שלמטה הוא אלף שנה למעלה הוא יום א' כי כל שית אלפי שני דהוי עלמא הוא למעלה רק ששת ימים, דהיינו אלף ראשון הוא מבחי' חסדו של הקב\"ה כמארז\"ל דורו של אנוש היו ניזונין בחסדו של הקב\"ה הגם שהיו עע\"ז היו מושפעים כל טוב מפני שאלף שנה היו מבחי' חסד, וכל מה שיש באלף שנה עבר הוה עתיד למעלה הוא נכלל ביום א' שהוא מדת החסד. והוא יובן עפ\"י משל כמו מח' ודיבור שמה שבמח' הוא מחשב בסקירה א' איזה דבר כשבא הדבר לידי דיבור יש בה שיהוי זמן, כמו למשל כשרוצה לבנות בנין ומחשב שצריך לעשות הגג על אופן זה וחלונות על אופן זה. והנה במחשבה כשמחשב אופן הגג הוא נסקר בסקירה א' וכשצריך לומר בדיבור יש בזה התחלקות רבי'. וכמו\"כ יובן למעלה שכל האלף שנה של חסד במח' הם בסקירה א'. וכן האלף שנה של גבורה בחי' מלך מלך ימלוך במח' הוא בסקירה א' וכו'. ונק' בשם הוי' ואלקים, שבחי' מח' נק' בשם הוי' והדיבור נק' בשם אלקים שהוא בחי' כח הפועל בנפעל בדבר ה' שמים נעשו כו', וכל מה שיש"],[1900740391,"בבחי' שם אלקים בחי' עש\"נ, עולם הוא בחי' מהות הדבר ונפש הוא החיות כו' ושנה הוא זמן, קיומו בשם הוי' הם נסקרים בסקירה א'. והנה מח' זו נק' בשם מח' מיוחדת כמו במשל הבנין הנ\"ל שיש מח' מיוחדת להגג ויש מח' מיוחדת להחלונות, כמו\"כ למעלה יש ששה בחי' הוי' לשית אלפי שני כו'. ויש מח' כללי' הכולל כל הששה מחשבות ביחד כמו למשל בבנין שיש מח' כללית הכוללת כל הפרטי' הגג והחלונות יחד והוא המח' שרוצה לבנות בנין כזה. וכמו\"כ עד\"מ למעלה יש מח' כללית כמ\"ש צופה ומביט עד סוף כל הדורות בסקירה א' שתחלת אלף שנה של חסד וסוף אלף הששי שהוא בחי' יסוד נסקרים שם בסקירה א', ובחי' זו נק' בשם סובב הכללי כי מחשבה הכוללת אלף שנה לבד נק' בשם סובב פרטי ומח' זו הכוללת כל השית אלפי שני נק' בשם סובב כללי כו'.\n<b>והנה</b> לפ\"ז ההפרש שבין התחדשות של כל יום ויום להתחדשות דר\"ה הוא, שבכל יום ההתחדשות הוא מכלל לפרט דהיינו שבשנה יש שס\"ה יום וכל יום מתחדש החיות מהחיות כללי שנמשך בר\"ה לכל השנה, והשנה מתחלק' לי\"ב חדשים והחודש לשלשים יום, וכל יום ויום מתחלק לכ\"ד שעות י\"ב שעות היום י\"ב צירופי הוי' ויב\"ש הלילה י\"ב צירופי אד', וא\"כ צ\"ל שהלא גם השנה הוא חלק פרטי לבד מאלף שנה כמו שכל יום הוא חלק פרטי מהשנה וא\"כ ההתחדשות דר\"ה הוא מהכלל הכולל כל האלף שנה ומפני מה נק' תחלת מעשיך זכרון ליום ראשון, כי הלא אין זה התחדשות גמורה. ואם יתפרש שהחידוש הוא מבחי' מח' כללית הכולל כל השית אלפי שני, הרי ג\"כ אין זה התחדשות חדשה לגמרי.\n<b>אך</b> הענין הוא שהחידוש דר\"ה הוא מעצמותו אשר אין שייך לקרוא גם בשם סובב הכללי. והענין יובן עפ\"י הידוע דר\"ה נק' יום הדין כמבואר בפע\"ח שיום א' דר\"ה הוא דינא קשיא כו', ולכאורה אינו מובן שהלא ר\"ה הוא בחי' חסד כמאמר כל מזונותיו של אדם קצובים מר\"ה, שבר\"ה הוא המשפט על כל השנה כמה ירויח, וכמו\"כ ברוחני' כמ\"ש משפט לאלקי יעקב שיש משפט כמה"],[1900740392,"יומשך אלקות ליעקב. ומה שארז\"ל אדם נידון בכל יום וכמ\"ש חדשים לבקרים רבה אמונתיך, המשפט של כל יום הוא בהכלי במה יתלבש החסד גשמי ובאיזה אופן יגיע לו הריוח אם בקלות ואם ביגיעה שנק' חיי צער וחיי ריוח, אבל מה שנמדד לו בר\"ה שכזאת ירויח לא יוסיף ולא יגרע מזה גם אם יתייגע א\"ע מאד רק אם יש באדם איזה התחדשות במעשיו כו'. וכמו\"כ יובן ברוחני' שהמשכת גילוי אלקות קצוב לו מר\"ה אך במה יתלבש אם במוח או בלב או במעשה לבד והוא בחי' הממוצע והכלי שע\"י יומשך גילוי אלקות, ועל הממוצע הוא המשפט בכל יום.\n<b>וביאור</b> הענין הוא כי כל מה שמשיג ומתבונן במוחו בהתבוננות והסבירים לקרב אל השכל איך שמחי' מאין ליש, הרי אין זה ערך כלל לבחי' אמיתי' מאין ליש, רק מחמת שהנשמה מלובשת בנפש הטבעי' וצריך לקרב אל השכל באותו השכל עצמו של נפש הטבעי' אשר מאב ואם כמ\"ש הן בעון חוללתי ובחטא יחמתני אמי, צריך להסבירי' אבל כמו שהנשמה מצד עצמה אינה צריכה להסבר כלל, כי בה נקבע הדבר כמו שהוא וד\"ל. וההסבר זה נק' בשם ממוצע והוא בחי' לבוש דנוג\"ה הממוצע, כענין כי הדם הוא הנפש, שהנפש בעצמה היא בחי' רוחני' והגוף הוא גשמי וכדי שהגוף יחי' מהנפש צריך לזה ממוצע והוא הדם שהמאכל שאדם אוכל נתעכל ונהפך לדם המובחר של המאכל, והפסולת נדחה לחוץ, והדם הוא הממוצע שבו מתלבש חיות הנפש. וכמו\"כ יובן עד\"מ שהלבוש דנוגה הוא הממוצע שע\"י יתפעל מאלקות. וכמו\"כ יובן בהתפעלות הלב אוי\"ר שאינו ערך לבחי' אמיתי' אלקו'. וכמו\"כ במעשה המצות שהטלית הוא מצמר גשמי ותפילין קלף גשמי כו' והם ממוצעים שע\"י יתלבש אלקות כו', ועל זה הוא המשפט בכל יום. כי בר\"ה הוא המשפט כמה יומשך אלקות אבל ע\"י איזה כלי יהי' ההמשכה ע\"ז ארז\"ל אדם נידון בכל יום. ולכן אין יום א' דומה לחבירו שהיום הזה נתפעל במוח ולא בלב וזולתו בלב ולא במוח, ופעם אינו מתפעל לא במוח ולא בלב אלא הביטול בבחי' מעשה בפו\"מ כי תלוי לפי המשפט שנשפט למעלה. וא\"כ ר\"ה הוא בחי' חסד ומפני מה נק' בשם יום הדין. אך הענין הוא כי בר\"ה הוא בחי' העלאה כי הרי נק' בשם יום הזכרון וכמ\"ש מי לא נפקד כהיום הזה, שהחיות של כל הברואים דצח\"מ וגם החיות של הע' שרים וכל התומ\"צ הם בבחי' העלאה"],[1900740393,"וההעלאה הוא לעצמותו ולכן נק' בשם יום הדין שהרי לא נודע עדיין איך יהי' ההמשכה, וחסד נק' על שם ההמשכה שהרי באמת נמשך חיות לכל הברואים כמ\"ש החותך חיים לכל חי, וכמארז\"ל הנ\"ל מזונותיו של אדם כו' הן ברוחני' הן בגשמיות כנ\"ל. והנה עפי\"ז יובן ענין הנ\"ל, שמאחר שההעלאה היא לעצמותו לכן המשכת החיות הוא ג\"כ מאותו בחי' ששם הי' ההעלאה, ונמצא שההתחדשות דר\"ה הוא חידוש מעיקרו. וזהו זה היום תחלת מעשיך זכרון ליום ראשון לעצמותו ממש כו' וד\"ל.\n<b>ועתה</b> י\"ל ההפרש שבין תשובה של כל השנה שב\"ק מכרזת בכל יום שובו כו' ובין תשובה דעי\"ת שע\"ז אמר הכתוב דרשו ה' בהמצאו כו'. להבין זה צ\"ל שיש בחי' או\"פ ואו\"מ כמ\"ש בס' הקבלה ובזוהר נק' בשם ממכ\"ע וסוכ\"ע, ובכל השנה צריך לילך מדרגא לדרגא מתחלה או\"פ ואח\"כ או\"מ. והענין יובן עפ\"י הידוע שיש ב' בחי' אהבה, אהבת עולם ואהבה רבה. אהבת עולם הוא בחי' או\"פ שהאהבה מתיישבת בכלי המוח והלב והוא הנק' אהבה דבכל לבבך ובכל נפשך, ואהבה כזו נתהוה ע\"י התבוננות בבחי' ממכ\"ע שהוא מבחי' אלקות שבתוך נבראים, ואתה מחי' את כולם כח הפועל בנפעל. ואהבה רבה הוא אשר למעלה מהגבלת כלי המוח והלב והוא ע\"י התבוננות איך שהוא מופלא בערך בחי' סוכ\"ע, וע\"י התבוננות זו נעשה בחי' תשוקה בלב כמ\"ש ולדבקה בו, אבל אינה נכנסת בתוכו ונק' בשם או\"מ, וצריך לילך בהדרגה מתחלה או\"פ ואח\"כ או\"מ שא\"א להגיע למדרגת אה\"ר שהוא בחי' בכל מאדך כ\"א ע\"י אהבה דבכל לבבך ובכל נפשך. וכמו\"כ יובן בענין תומ\"צ שידוע שהתורה נק' בשם מזון לנפש כמ\"ש ותורתך בתוך מעי, כמשל המאכל שאדם אוכל שנכנס בתוכו ונעשה לו לחיות הגם שלא נודע איכותו ואופנו איך שהמאכל מחי', מ\"מ זה נראה ודאי שהוא מחי'. וכמו\"כ בתורה כתיב זאת נחמתי בעניי כי אמרתך חייתני כי ע\"י לימוד התורה נעשה תועלת לנשמה דהיינו שאם יתבונן בהתבוננות אלקו' יתפעל או בלב כו' או במעשה להשמר אותו מל\"ת כמ\"ש בשכבך תשמור עליך כו' ולתת לו חיזוק לקיים מ\"ע, רק אם הוא מתעצל בדבר ואינו עוסק כלל בזה, אבל אם רוצה לעסוק התורה שעסק נותנת לו חיות וחיזוק כמ\"ש כי אמרתך חייתני, ולכן נק' בשם מזון שהוא בחי'"],[1900740394,"או\"פ. והמצות נק' בשם לבושים כמ\"ש ימים יוצרו כו' כמ\"ש ואברהם זקן בא בימים באינון לבושי' כו'. והלבוש הוא בחי' מקיף, שע\"י עשיית המצוה אין זה תועלת לו להיות לו לחיו' כמו ע\"י תורה, והגם שכתיב אלה המצות אשר יעשה אותם האדם וחי בהם, קאי על לעתיד כו' אבל לא עתה, וצריך לילך בהדרגה ג\"כ מתחלה תורה ואח\"כ מצות. וכמו\"כ יובן בענין התשובה דכל השנה שיש ב' בחי' תשובה, תשובה תתאה ותש\"ע. תשובה תתאה הוא מצד הטעם והדעת מפני היותו ממארי דחושבנא איך שויכל בהבל ימיו ועי\"ז נשבר ונדכה לבו, ואח\"כ מגיע לתש\"ע שהוא למעלה מן הדעת כו' כידוע. אבל בעשי\"ת ארז\"ל דרשו ה' בהמצאו קראוהו בהיותו קרוב שהוא עצמ\"ו נעשה קרוב בלי קדימת אתעדל\"ת כלל. וההפרש הוא שבכל השנה מאחר שאתעדל\"ע תלוי מצד אתעדל\"ת הרי א\"א להתעורר כ\"א בחי' המתנשא מימות עולם לבד כנ\"ל, אבל בר\"ה ועי\"ת שהתעוררו' הוא מצד עצמו הוא בחי' אשר אין אתעדל\"ת מגעת לשם כלל, בחי' התנשאות עצמיו' וכמ\"ש ישוב ירחמינו ואמרו בזוהר מאן אתר ישוב, מההוא אתר עתיקא סתימאה וה\"ז כמשל ב' בנ\"א כו' כנ\"ל. וראי' לדבר שהרי בעי\"ת נתעורר בחי' פנימי' נקודה בלב כל א' מישראל כמ\"ש בקשו פני את פניך ה' אבקש כו', משא\"כ בכל השנה, והוא מצד שנתגלה בחי' עצמיות ולכן נתעורר ג\"כ למטה בחי' עצמיות, וכל הוידויים שאומרים אשמנו כו' הוא רק הכנה שיתקבל בתוכ\"ם כו' אבל הגילוי הוא מצד עצמו, והגם שב\"ק מכרזת בכל יום שובו כו' אין זה אלא התעוררו' לבד ולא גילוי כו', משא\"כ בעי\"ת וכמ\"ש השיבנו ה' אליך מלמעלה ואז ממילא ונשובה כו' כידוע וד\"ל."],[1900740395,"<h3>שובה ישראל</h3>\n<b></b><b>בעז\"ה שבת שובה פ' האזינו, תקע\"ח לפ\"ק</b>\nשבת שובה פ' האזינו\n<b>שובה</b> ישראל עד הוי' אלקיך כי כשלת בעוניך קחו עמכם דברים ושובו אל ה'. להבין ענין זאת צריך להקדים הקדמה א' בעיקר התחלת עבודת ה' שהוא מ\"ש אתה הראת לדעת כי הוי' הוא האלקים וכמ\"ש וידעת היום והשבות אל לבבך כי הוי' הוא האלקים, ואין המכוון של וידעת או לדעת בחי' ידיעה בעלמא רק פי' דעת הוא הנק' (בל\"א דער הער כו'). וידיעה זאת צ\"ל בב' בחי' הוי' ואלקים, בחי' סוכ\"ע וממכ\"ע, וז\"ש וידעת היום והשבות אל לבבך כי הוי' הוא האלקים בשמים ממעל ועל הארץ מתחת. שמים ממעל הוא בחי' סוכ\"ע בחי' שם הוי' ועל הארץ כו' הוא בחי' ממכ\"ע, והוא ענין ב' פסוקי שמע ישראל ובשכמל\"ו. שמע ישראל הוא יח\"ע ובשכמל\"ו הוא בחי' יח\"ת כו'.\n<b>והענין</b> הוא כמ\"ש שאו מרום עיניכם וראו מי ברא אלה, דהיינו שבכל בוקר ובוקר קודם נפילתו בטרדת העסק צריך להיות נותן לב מי ברא אלה, איך שואתה מחי' את כולם כי הוא ית' מקורא דכולא ולא כמו שנראה העולם ליש בפ\"ע. ולעתיד יהי' בחי' ידיעה זו בשלימות כמ\"ש וידע כל פעול כי אתה פעלתו ויבין כל יצור כי אתה יצרתו, ולא האדם בלבד אלא כל פעול כו'. אך עכשיו הוא בחי' הסתר אלקות עד שנראה העולם ליש וע\"ז כתיב השמר לך פן תשכח את הוי' אלקיך שהוא בחי' שכחה והיסח הדעת. וז\"ש וידעת היום והשבות אל לבבך כו' שגם עכשיו צריך להעמיק בזה הענין עד שיהי' נקבע בלב, וידיעה זאת צ\"ל בב' בחי' הוי' ואלקים. ובלשון רז\"ל נתאוה הקב\"ה להיות לו דירה בתחתונים, פי' לו היינו לעצמותו כמו שהוא למעלה כמו\"כ יהי' התגלות למטה. ובזוהר אמרו מאן דלא מהפך חשוכא לנהורא"],[1900740396,"ומרירו למתקא בהאי עלמא לית לי' חולקא בההוא עלמא, והוא ענין א' עם מ\"ש וידעת היום והשבות אל לבבך כי הוי' הוא האלקים.\n<b>והענין</b> הוא כי ההתבוננות איך שהוא מחי' את כולם כח הפועל בנפעל הוא בחי' אלקים, וההתבוננות בבחי' סוכ\"ע הוא בחי' הוי'. ובנפש האדם יש ג\"כ ב' בחי' אלו בשמים ממעל ועל הארץ מתחת בחי' סובב ובחי' ממלא. והענין הוא כי יש ד' בחי', שכל ומחשבה דיבור ומעשה, והוא מ\"ש בק\"ש שמע ישראל ואהבת הוא בחי' שכל ומח', ומ\"ש והיו הדברים האלה ודברת בם ואספת דגנך הוא בחי' דיבור ומעשה. וביאור הענין הוא כי שכל ומח' הוא בחי' ההשכלה באלקות, וענין ההשכלה הוא כמ\"ש שאו מרום עיניכם וראו כו' כמו איזהו חכם הרואה כו' והמכוון הוא לאהפכא חשוכא לנהורא, והוא ההסכם שנשאר אצלו על כל היום שלא להשכיל ולחשוב בעניני העולם והוא בחי' בשמים ממעל שבנפש. וענין דיבור ומעשה הוא הדיבור בת\"ת ומעשה הצדקה בפו\"מ והוא ג\"כ לאהפכא חשוכא לנהורא, ]ד[היינו שלא להיות עוסק בעניני מו\"מ בהתלהבות כחי ועוצם ידי כו' והוא בחי' על הארץ מתחת שבנפש כו'. והנה כתיב ב\"פ כי הוי' הוא האלקים גבי אליהו דכתיב וירונו ויפלו על פניהם ויאמרו הוי' הוא האלקים הוי' הוא האלקים, ב\"פ כי הם היו עע\"ז דהיינו שהי' בהם התאוה לע\"ז ולא שכפרו לגמרי כי הרי היו מקריבים קרבנות לה' ג\"כ, וע\"י אליהו שגילה להם בחי' אלקות נפלו על פניהם ויאמרו ב\"פ כי הוי' כו' כמשי\"ת לקמן.\n<b>והנה</b> אמרו בזוהר כי הוי' הוא האלקים כולא חד, כי עיקר ההתבוננות צריך להיות איך שכולא חד דהיינו ששמע ישראל שהוא בחי' יח\"ע ע\"ס דאצי' בחי' שמים ממעל. כמו\"כ בשכמל\"ו שהוא בחי' יח\"ת על הארץ מתחת שוה ממש. והענין הוא כמ\"ש אם אסק שמים שם אתה ואציעה שאול הנך, שמים הוא בחי' יח\"ע ואציעה שאול שהוא אשר מתחת לארץ, הנך ממש אותו אלקות עצמו שבשמים כו', וכמו שאמר יונה מבטן שאול שועתי כו', וכמ\"ש ומסדר את הכוכבים במשמרותיהם ברקיע כרצונו שהוא כרצונו הפשוט כו',"],[1900740397,"וכמ\"ש ויאמר הוי' אל בלעם כו' שלגבי' כחשיכא כאורה, ואין הפי' סוכ\"ע שהוא סובב למעלה ואינו נמצא למטה, אלא פי' שהוא שוה למטה כמו למעלה ממש. וכמו שמצינו בבהמ\"ק שהי' גילוי אלקות בהיכל ק\"ק ארון ושולחן ששם אלקים לא הסתיר כלל מפני שהי' התגלות שם הוי'. וכענין הנסים שהוא לשנות הטבע כמו גבי רחב\"ד שאמר מי שאמר לשמן וידליק יאמר לחומץ וידליק שעפ\"י שם אלקים צריך דייקא השמן להדליק ולא החומץ, אך שהאיר מבחי' שם הוי' שהוא מעלמא דאתכסיא כו'. וזהו ענין כ\"ו כל\"ח שהוא ענין התגלות שם הוי' בשם אלקים. והענין יובן עד\"מ מסך המסתיר את השמש שהאור הנראה מתוך המסך אינו כמו אור העצמי, אבל כשנלקח המסך או שעושים נקבים בהמסך אזי מאיר האור עצמי כמו שהוא. וכמו\"כ יובן בענין הוי' ואלקים ששם אלקים הוא מסתיר על שם הוי', כמ\"ש כי עמך מקור חיים באורך נראה אור בחי' הארה דהארה כו'. אבל כשנלקח ההסתר דשם אלקים אזי נתגלה שם הוי'. או כמו מה שנראה שמי שהוא נוטה למות יוכל להתרפאות לפעמים והוא ע\"י התגלות שם הוי'. או כמו גבי חזקיהו שהוסיפו לו על שנותיו חמשה עשר שנה. וכמו\"כ יובן ]הענ[ין בפרנסה. כי הנה ארז\"ל מזונותיו של אדם קצובים לו מר\"ה וכמ\"ש החותך חיים לכל חי, הן בגשמיו' הן ברוחניו', ולפעמים יכול להיות שיצליח וירויח יותר מכפי המדה שנמדד לו בר\"ה. וכמו\"כ יכול להיות ברוחני' בחיי אלקו'. כי הנה כתיב משפט לאלקי יעקב שבכל ר\"ה נשפט האדם כמה יומשך אלקות כו', אך ע\"י תשובה נתגלה מבחי' שם הוי' כו'.\n<b>והנה</b> עפ\"י כל זה יובן מ\"ש בזוהר כי הוי' הוא האלקים כולא חד, שאלקי' אינו מסתיר באמת על שם הוי'. וז\"ש בשמים ממעל ועל הארץ מתחת, פי' מתחת לארץ בשניהם בשוה אין עוד כו'. וענין מה שאמרו פעם ב' כי הוי' הוא האלקים כו' כי יש שם אלקים אשר למעלה משם הוי' ג\"כ, כי בחי' הוי' זה"],[1900740398,"הוא בחי' סוכ\"ע כמ\"ש המרומם והמתנשא מימות עולם כו'. ולהיות בחי' סובב לעלמין לזה צ\"ל ג\"כ בחי' צמצום והוא בחי' שם אלקים שהוא למעלה משם הוי'. וזהו כי הוי' הוא האלקים שהוי' זה הוא בטל ונכלל לגבי שם אלקים שלמעלה ממנו כו'. ועיקר התחלת עבודת ה' הוא ב' בחי' אלו הנ\"ל הוי' ואלקים. אלקים הוא ההתבוננות ואתה מחי' את כולם כו' ונק' בשם יעקב כו'. והוי' הוא בחי' סוכ\"ע. ובנפש הוא ד' בחי', שכל מח' דיבור ומעשה הנחשבים לשתים, שכל ומח' הוא ענין א', ודיבור ומעשה הוא ענין א', ואז נק' צלם אלקים בשלימות.\n<b>והנה</b> כ\"ז הוא כשהצלם אלקים בשלימות, אבל כשנפגם הצלם אלקי' כמ\"ש אם פגמתי באות יו\"ד פגמתי באות ה' כו', כי הנה כתיב נר הוי' נשמת אדם שבכל נשמה יש שם הוי' וכשנפגם אות יו\"ד אזי הוא חייב סקילה ובאות ה' שריפה כו'. והענין הוא כי הנה יו\"ד הוא בחי' חכמה לאסתכלא ביקרא דמלכא כמו איזהו חכם הרואה, וכשנפגם והפגם הוא ע\"י התחכמותו במשא ומתן ואומר כחי ועוצם ידי, כי באמת הותרה עסק הפרנסה כמ\"ש ואספת דגנך אך בתנאי שכתוב לעיל מיני' בכל לבבך ובכל נפשך בחי' מס\"נ בתכלית לה', רק שצריך לעשות כלי במה שהברכה ישרה בו כמ\"ש וברכך ה' בכל אשר תעשה וכמ\"ש השלך על ה' יהבך כו'. וזהו הנק' בשם גלות השכינה, שהשכינה היא בבחי' גלות שאומר כחי ועוצם ידי ולא ה' כו'. ובאמת הכל הוא מצד ה' הן אם מרויח או להיפך שמפסיד, הכל הוא השגחה אלקי' על כל פרט ופרט. ולעתיד יהי' בחי' זאת גם אצל הפח\"ע שכולם ידעו איך שהברכה היא מאלקות ולא האדם הוא העושה כו', אבל עתה הוא להיפך שגם אצל הגדול שבדור יוכל להיות שבעת שעושה העסק מדמה בנפשו כחי כו', הגם שכל א' יש לו בחי' יהדותו ואחר ההצלחה והריוח אומר ברוך ה' שהוא עשה זאת. וכן להיפך כשמפסיד ניכר אח\"כ ואומר ה' עשה זאת אבל בעת העסק אומר כחי ועוצם ידי כו', שמצד חכמתו הוא מרויח, ואם אינו מרויח הוא מצד טפשותו בדבר כו'."],[1900740399,"<b>והנה</b> עי\"ז נעשה פגם ביו\"ד וחייב סקילה כמו על ע\"ז גשמיות שמשתחוה לעץ ואבן שחייב סקילה באבנים גשמיי' כמ\"ש סקל יסקל כו', כמו\"כ יש סקילה רוחני' לע\"ז רוחני', וע\"ז רוחני' הוא מה שארז\"ל ישראל שבח\"ל עע\"ז בטהרה הם, וענין עע\"ז בטהרה הוא ענין התחכמות הנ\"ל ועי\"ז חייב סקילה רוחני', והוא עונש החמור מכולם דהיינו סקילה באבנים רוחני' והוא בחי' טמטום המוח כמו ענין לבו כלב האבן כו' שלא יהי' בו בחי' ראי' כמ\"ש שאו מרום עיניכם וראו כו'. ואם פגמתי באות ה' כו' הוא בחי' התפעלות הלב שבעסק הפרנסה וחייב שריפה לשרוף נפש]ו במחשבות[ זרות. ואם פגמתי באות וי\"ו ונתחייבתי הרג הנה הרג הוא מיתת סייף שחותכין ראשו מלבו והרג רוחני הוא מה שנבדל מוח מלב שגם שנתפעל במוח אינו נמשך בלב כו'. ואם פגמתי באות ה' אחרונה ונתחייבתי חנק הוא שאין בו בחי' והרוח תשוב כו'. וכשנפגם שם הוי' אזי א\"א להיות בו וידעת כי הוי' הוא האלקים כו', ע\"ז כתיב שובה ישראל עד ה' כו' דהיינו שיומשך הוי' מחדש.\n<b>והענין</b> יובן ע\"פ מ\"ש בכתבי האריז\"ל כל מי שאינו בוכה בר\"ה ויוה\"כ כו' וכמ\"ש הלך ילך ובכה נושא משך הזרע כו', כי הנשמה נמשכה מאור זרוע לצדיק כו' וכמ\"ש בית ישראל ברכו את הוי' שצ\"ל התקשרות תמידי', אך כשנפגם שם הוי' כמ\"ש אם פגמתי כו' וא\"א להיות בו בחי' וידעת כו', ע\"ז כתיב ובכה, כי הבכי' הוא מצד עצמיות כו' והוא בחי' יחידה שבכל נפש מישראל וכמ\"ש מיד כלב יחידתי שלשם אינו מגיע פגם של חטא ועון כלל, כי הפגם אינו רק ביו\"ד וה' כו', אבל בבחי' יחידה לשם אינו מגיע פגם דחטאי' כו'. ומפני שיש בבני ישראל בחי' יחידה זו לכן מתגלה בחי' י\"ג מדה\"ר להמשיך מחדש שם הוי' על כל השנה להיות בחי' וידעת כי הוי' כו'. וזהו שובה ישראל עד הוי' דהיינו עד שיומשך הוי' חדש וד\"ל. כי כשלת בעוניך כמ\"ש כשל בעוני כחי, וכחי הוא כח הנשמה שמאיר בכל יום כמ\"ש חדשים לבקרים כו' שכל מה שנתפעל בשכל ומח' או המעשה ודיבור בפו\"מ,"],[1900740400,"הכל הוא ע\"י הכח שמאיר בו, אך כשל בעוני כחי, ולכן שובה ישראל עד הוי' כו' כנ\"ל וד\"ל.\n<b>קחו</b> עמכם דברים ושובו אל ה', הנה דברים הוא כמ\"ש ודברת בם כו' והוא ענין תורה ומצות של השנה שעברה ועי\"ז שובו כו'. כי הנה כל בע\"ת שנתעורר בתשובה אלו לא הי' מקיים איזה מצוה או לימוד בד\"ת לא הי' מתעורר כלל לשוב, רק התעוררות תשובה הוא ע\"י שקיים מצוה פעם אחת או שלמד בד\"ת, עי\"ז דייקא מתעורר לשוב. כמו\"כ יובן בענין זה שהתשובה הוא דייקא ע\"י תומ\"צ שקיימו עכ\"פ בשנה שעברה ועי\"ז דייקא ושובו אל ה'. וכמו ענין תפלה של כל יום ויום שארז\"ל יפה שעה אחת בתשובה כו' והשעה אחת הוא שעת צלותא, כי התפלה נק' בשם תשובה שענינה הוא כלות הנפש והרוח תשוב כו', וכל תפלה תלוי' לפי ערך התומ\"צ שקיים ולמד ביום העבר כו' ועפ\"י אופן זה יובן גם כאן קחו עמכם דברים ושובו כו' כנ\"ל."],[1900740401,"<h3>יסובבהו יבוננהו</h3>\n<b>בעז\"ה, שבת שובה הנ\"ל</b>\n<b>יסובבנהו</b> יבוננהו יצרנהו כאישון עינו, וארז\"ל כל הנוגע בהם כאלו נוגע בבבת עינו כו'. הנה אישון עין הוא השחור שבעין, כי בעין יש ב' גוונין חיורא ואוכמא ועיקר ההסתכלות הוא מהשחור שבעין הגם שלכאורה הי' צ\"ל הראי' מהלבנונית שבעין אך נקוד' השחור שבעין הוא המצמצם ומכווץ כח הראי' בנקודה א', כמו למשל הרואה דרך נקב קטן או בכלי הבטה שיכול להביט מרחוק יותר, והטעם הוא כי נתצמצם כח הראי', כמו\"כ יובן בענין נקודה שחורה שבעין. וזהו כל הנוגע בהם כאלו נוגע בבבת עינו כו' כמו למשל באדם כשנוגעים לו בשחור שבעין נוגע זה אל עצמיותו כו'.\n<b>ולהבין</b> ענין ראי' למעלה הנה כתיב עיני ה' משוטטות בכל הארץ וכתי' משוטטים כו'. וכתיב ממכון שבתו השגיח ה' על כל יושבי הארץ השגחה בפרט על כל הברואים הן על מלאכים ואפי' על דצח\"מ ועל חיצוני' ומזיקים, והוא יודע כל תעלומות הן מחשבת בנ\"א ולבם ומעשיהם וכמ\"ש אז נדברו יראי ה' איש אל רעהו ויקשב ה' וישמע כו', וכמשארז\"ל דע מה למעלה ממך עין רואה ואוזן שומעת כו', וכמו כי אתה שומע תפלת כל פה שאפי' אדם המתפלל ביחיד אם מתפלל בבחי' נקודת הלב שומע ה'. והנה יש ב' בחי' ראי' למעלה, הא' הוא מ\"ש עיני ה' משוטטות בכל הארץ כו', והב' הוא מ\"ש עין ה' אל יראיו וכמ\"ש השקיפה ממעון קדשך מן השמים דייקא. והענין יובן מבשרי, כי אמת הוא שאוא\"ס הוא אחדות פשוט ואין לו גוף ולא דמות הגוף כמ\"ש כי לא ראיתם כל תמונה, אך דברה תורה כלשון בנ\"א כמ\"ש עין ה'."],[1900740402,"<b>ולכן</b> יובן זאת מכח הראי' שבאדם שיש ב' בחי', הא' הוא בחי' כח הראי' שמתלבש בכלי העין, כי כח הראי' עצמו הוא רוחני וכלי העין הוא גשמי רק שכח הראי' מתלבש בו, וה\"ז כמשל הרואה דרך זכוכית שבחי' הראי' מתלבש דרך מעביר לבד בתוך הזכוכית ולא שהזכוכית עצמה היא הרואה. והראי' שאם יש עכרורית בזכוכית אין מזה השתנות בכח הראי' עצמה. כמו\"כ יובן התלבשות כח הראי' בכלי העין. רק שמ\"מ אין המשל דומה לנמשל, כי הכלי זכוכית אינו כלל מעין כח הראי' אבל חומר כלי העין החומר הוא מעין הצורה ולכן מתלבש בו דייקא בחי' כח הראי' ונק' בשם אור מקבל שאינו אור בעצם והראי' שהרי אינו רואה כ\"א ביום ולא בלילה ואלו הי' בחי' אור בעצם הי' רואה גם בלילה כו'. והב' הוא בחי' ראי' רוחני' שבעצמו' הנפש שאינו שייך שם לומר בחי' ראי' על דבר גשמי, או כמו כח הראי' שבעין שא\"א לראות רק ס' מילין כו'. וכמו\"כ יובן למעלה שמ\"ש ממכון שבתו השגיח על כל יושבי הארץ או עיני ה' משוטטו' בכל הארץ הוא בחי' התלבשות כח הראי', כמו למשל באדם שכח הראי' רוחני' מתלבשת בכלי העין. כמו\"כ למעלה יש מלאכים ממוצעים הנק' מארי דעיינין מארי דאשגחותא אשר על ידם השגיח על כל יושבי הארץ. ומ\"ש השקיפה ממעון קדשך מן השמים הוא ראי' והבטה רוחני' כמו מה שצופה ומביט עד סוף כל הדורות בסקירה אחת. וגם יתפרש בחי' ב' ראי' הללו על נש\"י, כי נש\"י עלו במח' הוא בחי' ראי' רוחני', אך הנשמות שבגופי' מה שמתפעלים מאלקות שאינו ערך לפי השגת הנשמה למעלה ונק' בשם השתנות ממהות למהות, בחי' זו נק' בשם ראי' גשמי'.\n<b>והנה</b> מבחי' ראי' רוחני' נתהוה אח\"כ בחי' ראי' גשמי' שהוא הראי' שע\"י מלאכים, ונמצא לפ\"ז שנשמות גבוהים ממלאכים. וצ\"ל כי הנה כתיב וכל קרבי את שם קדשו שיש מלאכים הנקראים בשם קרביים כמו למשל המאכל שאדם אוכל שנתברר בתוך מעיו והפסולת נדחה לחוץ ומהמובחר נעשה דם ועולה ללב ולמוח ולכל איברים, כמו\"כ למעלה מלאכים הם המבררים ומבדילים חיצוני' מפנימי', וחיצוני' השפעה נמשכת לע' שרים כמו"],[1900740403,"ר\"ע שראה כרך גדול של רומי שחק ואמר אם לעוברי רצונו כך לעושי רצונו עאכ\"ו, כי כל התענוגים שלהם אינו רק מחיצוני' ומותרות כו' ופנימי' השפעה נמשכת לנשמות שמתענגין ונהנין מזיו השכינה בג\"ע העליון ובג\"ע התחתון, או לנשמות שבגופים שיתפעלו מאלקות שמקבלים ממלאכים, וכמו פסד\"ז ושתים לפניה שהוא הסיפור איך שהמלאכים משבחים ומפארים כו' ועי\"ז מקבלים נשמות שבגופי' בחי' התפעלות. וזהו מ\"ש אכלתי יערי עם דבשי פי' כי יש הפרש בין עץ עושה פרי לעץ אשר מאתו זבת דבש, כי הפרי הוא נבדל מן העץ אבל הדבש שזב מן העץ מוכרח להיות שבעץ גופא יש מתיקות רק ששם הוא בהגשמה. וכמו\"כ יובן בענין מלאכים ונשמות שיערי נק' מלאכים והוא בחי' יוצר אור שהוא האהבה שמקבלים ע\"י מלאכים שנק' בשם יערי שהתענוג הוא בהגשמה מאחר שע\"י נתפעל עם דבשי בשביל דבשי שהוא שמע ישראל בחי' תענוג הנשמה בעצם כו'. ולכן אין ההתפעלות בתפלה של יום א' דומה לחבירו כי הוא תלוי לפי אופן המלאכים כמו מיכאל וגבריאל שר של אש ושר של מים בחי' חו\"ג הם המשפיעים אוי\"ר לנש\"י. ולכן כל יום ההתפעלות הוא באופן אחר שתלוי לפי אופן השפעת המלאכים כו'. וא\"כ לפ\"ז הנשמות הם נמוכים מהמלאכים מאחר שהם מקבלים ממלאכים. אך הענין הוא כנ\"ל כי בנשמות יש ב' בחי' והוא חלק הנשמה שבגוף כמ\"ש נשמה שנתת בי כו' ושרש הנשמה שלמעלה מן הגוף. ושרש הנשמה היא למעלה ממלאכים כו' אך הנשמות שבגופים שמלובשים בגוף ונפש הטבעי' הנמשך ע\"י תאוה כמ\"ש הן בעון חוללתי ובחטא יחמתני אמי וההתפעלות הוא ע\"י מוח ולב של נפש הטבעי' ששרשה מפני בהמה חי' ועוף שבמרכבה כמו שנראה שיש בנפש הטבעי' בחי' אלו ונפש האלקי' מבררת בחי' אלו לאלקות, כי נפש האלקי' ג\"כ כלול מכל בחי' אלו כמ\"ש ופני אדם לארבעתם ושרש הנפש אלקי' הוא מבחי' פני אדם שבמרכבה, ונמצא שנפש האלקי' היא מלובשת בתוך נפש הטבעי', ולכן ההתפעלות שיש לנפש אלקי' ע\"י שכל ולב של נפש הטבעי' מקבלת ממלאכים. ולפ\"ז יתפרש יצרנהו כאישון עינו על נשמות שבגופי' שהוא תכלית ההסתר שהגוף מסתיר על נפש האלקי' בתכלית."],[1900740404,"<b>ועתה</b> יובן מ\"ש לעיל מיני' ימצאהו בארץ מדבר ובתוהו ילל כו' דקאי על ר\"ה ויוכ\"פ. כי הנה נשמות שבגופי' נק' בשם ימצאהו בארץ מדבר, שהתפעלות הנשמה הוא ע\"י נפש הטבעי' כנ\"ל. ובתוהו ילל הוא בחי' השפלות שע\"י וידויים בר\"ה ויוכ\"פ תעבנו תעינו כו'. והנה כתיב הבן יקיר לי אפרים אם ילד שעשועים ע\"כ המו מעי לו רחם ארחמנו נאום ה', כי הנה מעי הוא בחי' פנימי יותר גם מבחי' נקודת הלב ורחם ארחמנו הוא בחי' ר\"ר. והטעם שהמו מעי כו' הוא מפני שהוא ילד שעשועי'. והענין יובן עד\"מ מבן לאביו שבן גדול תלוי האהבה לפי אופן כשרון מעשיו כמ\"ש בן חכם ישמח אב כו', משא\"כ בן קטן שאין בו חכמה כלל רק האב משעשע בשחוק של התינוק, ובחי' זו היא מצד בחי' עצמיות כי מאחר שאין בו בחי' חכמה כלל שימלא רצון אביו וכדומה רק שקורא אבא ומפני זה משעשע בשחוק של התינוק אשר אין זה ערך כלל לגבי אב רק הוא מצד בחי' עצמיותו וה\"ז כמו אותו התענוג עצמו שמשעשע עם בנו הגדול כשהולך בדרך הישר שזה ג\"כ מצד עצמיותו. וראי' לדבר שהרי מאחר שאינו בנו שהולך בדרך ישר כזה אינו משתעשע כלל נמצא ששוה השעשועי' של תכלית הקטנות עם תכלית הגדלות שהכל הוא מצד בחי' עצמיות. והנה כמו\"כ יובן בעבודת ה' שאם אכשור דרי ונק' ישראל אשר בך אתפאר וכמ\"ש רק עם חכם ונבון כו', אזי השעשועי' הוא מצד מעשיהם כו', אבל בר\"ה ויו\"כ שאומרים אשמנו תעבנו כו' בחי' שפלות בתכלית וכל אדם יכול לומר הוידוי אשמנו ועל חטא הגם שאין בו חטא זה, כי כל ישראל ערבים זה בזה בחי' ציור אדם ראש ורגל, וכמו למשל כאב הרגל שמרגיש הראש דייקא, כמו\"כ יוסיף דעת יוסיף מכאוב על חטא שברגל ולכן אומרים כולם וידוי א', הוא בחי' ילד שעשועים. ובכלל כולם נק' בשם ילד שעשועי' הגם שיש צדיקים מופלגים בדור שיש להם התפעלות אלקות לאמיתו, כ\"ז נק' בשם ילד שעשועי' כי אין זה ערך כלל לגבי שרש הנשמה כמו שהיא קודם ירידתה לגוף כמ\"ש חי ה' אשר עמדתי לפניו כו' והעיקר הוא בר\"ה ויו\"כ שאז משפילים א\"ע עד קצה האחרון. וע\"ז כתיב כי בך ירוחם יתום,"],[1900740405,"ולכאורה אינו מובן מפני מה לא כתיב כי אתה תרחם יתום. אך הענין הוא כי יתום בגשמיות נק' שאין לו אב ואם ובעבודת ה' הוא בחי' הסתלקות אור אבא כי גילוי אא\"ס הוא בחכמה כו', אך בך ירוחם יתום שהרחמנות הוא בך בעצמותך בחי' ר\"ר, ומבחי' זו יומשך בחי' ר\"ר להיות נק' בשם אבינו כמ\"ש כי אתה אבינו. וזהו שאומרים בר\"ה ויו\"כ אבינו מלכנו כו'. וזהו הבן יקיר לי אפרים אם ילד שעשועי' שהוא בר\"ה ויוכ\"פ ע\"כ המו מעי לו רחם ארחמנו בחי' ר\"ר. וזהו ג\"כ ענין ימצאהו בארץ מדבר ובתהו ילל. ואח\"כ כתיב יסובבנהו זהו חג הסוכות שנק' בשם צילא דמהימנותא שמבחי' ר\"ר הנ\"ל נמשך בחי' מקיפים לכל או\"א שהוא הכח שיהי' יכול להתפעל מאלקות, אך בסוכות הוא עדיין בבחי' מקיף כמ\"ש וימינו תחבקני ואח\"כ נעשה יבוננהו. וביבוננהו יש ב' פי', הא' הוא לשון בנין, והב' הוא לשון בינה והוא בחי' בן י\"ה דהיינו שיהי' נמשך מבחי' מקיפי' לידי גילוי והוא בחי' הולדת המדות כו'. והוא ענין שמיני עצרת כי עצרת הוא לשון קליטה שיהא נקלט בחי' גילוי אלקות לכל חד וחד לפום שיעורא דילי'. ואח\"כ כתיב יצרנהו כאישון עינו שגם בנשמות שבגופים שהוא בחי' חושך ואפילה ומתוך החושך מאיר האור שם יהי' נמשך בחי' לא ינום ולא יישן שומר ישראל לית גביני דמכסיין על הני עיינין, כי השינה לא שייך רק בבחי' ראי' המלובש בכלי העין אבל בבחי' ראי' רוחני' לא שייך בחי' שינה. וזהו מ\"ש פקח עיניך פקיחא דעיינין, וכמארז\"ל וכי יש שינה לפני המקום. וזהו יצרנהו כאישון עינו שבתוך אישון עינו שם דייקא יאיר מבחי' לא ינום ולא יישן, כי הנה כתיב ויאכלו את ישראל בכל פה כי בכל דור ודור עומדים עלינו לכלותינו, וכשרוצים לכלות אותם לגמרי שם דייקא נתעורר בחי' נקודת אהבה עצמי'. וזהו יצרנהו כאישון עינו כו' וד\"ל."],[1900740406,"<h3>כי כארץ תוציא צמחה</h3>\n<b>שבת שובה הנ\"ל</b>\n<b>כי</b> כארץ תוציא צמחה וכגנה זרועיה תצמיח כן יצמיח ה' צדקה ותהלה נגד כל הגוים. הנה צדקה ותהלה הוא ר\"ה ויוכ\"פ וכתיב בר\"ה זה היום תחלת מעשיך זכרון ליום ראשון. להבין ענין זאת צריך להקדים מה שאומרים בעשי\"ת המלך הקדוש, כי בשלמא בר\"ה ניחא שאז הוא זכרון ליום ראשון לבחי' מח' הקדומה אנא אמלוך ולכן אומרים המלך הקדוש, כי קדוש הוא לשון מובדל, אבל מפני מה אומרים בכל עשי\"ת המלך הקדוש. וגם זה גופא צ\"ל איך שייך לומר המלך הקדוש, כי ידוע שאין מלך בלא עם שהוא ענין התפשטות על זולתו, וקדוש הוא בחי' מובדל ונמצא לפ\"ז שמלך וקדוש המה שני הפכי' כו'.\n<b>להבין</b> כל זאת צריך להקדים הקדמה א', שיש ב' בחי' קדוש וקדש. קדש הוא בעצמותו וקדוש בוי\"ו הוא המשכה מקדש, וכתיב קדושים תהיו וארז\"ל יכול כמוני ת\"ל כי קדוש אני קדושתי למעלה מקדושתכם. וענין קדושים תהיו הוא ע\"י מעשה המצות כו'. וצ\"ל ההפרש שבין נשמות למלאכים, ומפני מה לא ניתנה תומ\"צ למלאכים לפי אופן מדרגתם. אך הענין הוא כי הנה כתיב בדבר ה' שמים נעשו וברוח פיו כל צבאם, ששרש התהוות המלאכים הוא מבחי' רוח פיו. ויובן זאת עד\"מ מבשרי שהבל הלב מתפשט בדיבור ונמצא שהבל הזאת הוא מורכב בתוך הגוף אבל המח' שבמוח היא מתאחדת עם העצם, כמו שיש נפש המדברת ונפש השכלית קודם בואה לגוף,"],[1900740407,"כמו\"כ הוא אופן המח' שבמוח שמתאחד עם העצם, והגם שהמח' נמשכת ג\"כ בדיבור הוא בבחי' ירידה מעצמותו ולא כהבל הלב. והנה כמו\"כ יובן למעלה הגם שאין לו גוף ולא דמות הגוף מ\"מ אחר שכתיב וברוח פיו כל צבאם אזי הוא כמשל הבל הלב דהיינו שהתהוותם הוא מבחי' כח הפועל בנפעל בחי' ממכ\"ע. אבל נש\"י עלה במחשבה פי' למעלה ממח' ולכן ניתנו המצות דייקא לישראל כי נש\"י עלה במח' כנ\"ל. וגם המצות המה בחי' פנימי' רצונותיו כי המצות בשרשם המה בחי' תרי\"ג ארחי' דגלגלתא בחי' קדש, וגם נש\"י נק' בשם קדושים כמ\"ש לקדושים אשר בארץ המה. וצ\"ל שבשלמא כמו שהמצות המה בשרשם המה רצה\"ע ונש\"י ג\"כ כמו שהם בשרשם נק' בשם קדושים, אבל מהו היתרון בירידת המצות למטה בהתלבשותם במעשה המצות גשמיי' וגם נשמות המה מלובשים בגופים. אך הענין הוא כי הנה כתיב זורע צדקות מצמיח ישועות ונש\"י נק' ג\"כ בשם זריעה כמ\"ש וזרעתיה לי בארץ וכתיב והארץ אזכור.\n<b>ולביאור</b> הענין צ\"ל ענין כי כארץ תוציא צמחה כו'. הנה יש ג' מיני צמיחות, הא' הוא תפוחי הכרם הנעשה ע\"י נטיעת אדם ותיקונו שמשקה את השדה וכדומה והצמיחה שנעשה מזה הוא תפוח שיש בו טעם ומתיקות. ויש תפוחי היער שנעשה בלי תיקון האדם כלל רק שמעצמו נצמח והצמיחה הוא פרי אבל הפרי היא בלי טעם ומתיקות. וצמיחה ג' הוא הנק' ספיחי' כמו עשבים שאין בהם טעם כלל ואינם פרי כו'. והטעם של צמיחת הארץ ידוע כי בארץ הוטבע בטבע בחי' כח הצומח וכדי שיצמח מהעלם לגילוי לזה הי' המאמר תדשא הארץ דשא מזריע זרע ועץ עושה פרי כו'. וכמו\"כ יובן ג' בחי' אלו במעשה המצות שנק' ג\"כ בשם זריעה זורע צדקות כו' שעי\"ז נעשה צמיחה כו'.\n<b>כי</b> הנה כתיב ויברא ה' אלקים גן בעדן מקדם, כל עץ נחמד למראה כו', שיש ג\"ע העליון וג\"ע התחתון מתחלת בריאתם, ובג\"ע התחתון יש"],[1900740408,"כל עץ נחמד למראה וטוב למאכל כו' וג\"ע התחתון הוא בקו השוה בזה העולם וקרקע הגן הוא מרוחני' הד' יסודות ארמ\"ע, ונמשך הארה מבחי' תענוג שבשעשוע המלך בעצמותו לג\"ע העליון וג\"ע התחתון. והנה התרחבות הג\"ע להתוסף אור בג\"ע העליון ותחתון תלוי דייקא ע\"י מעשה המצות וכמ\"ש באדה\"ר קודם החטא ויניחהו בג\"ע לעבדה ולשמרה, לעבדה זו מ\"ע שע\"י יתוסף אור בג\"ע, ולשמרה זו מל\"ת שהוא להסיר כל המונעים ומנגדים להצמיחה, כמו למשל בגשמיות שצריך לסקל אבנים המונעים שאז יהי' יוכל להצמיח. ושרש המל\"ת הם גבוהים בשרשם יותר ממ\"ע. וכמו\"כ יובן ג\"כ כעת שע\"י המצות מעשיות נעשה התרחבות ותוס' אור בג\"ע כמו שמבואר בפע\"ח שע\"י מצות בכוונה ניתוסף אור בג\"ע העליון, וע\"י מצות בלא כוונה ניתוסף אור בג\"ע התחתון, דהיינו שכל המצות שעשה ימי חייו שבעים שנה, בצאת הנפש מהגוף יבא לג\"ע עם כל המצות שקיים ונעשה תוס' אור. וענין מצות בכוונה הוא שעושה המצוה מטעם שהוא משיג איך שהיא רצה\"ע ועושה אותה בכוונה פנימי', ע\"י מצוה כזאת ניתוסף אור בג\"ע העליון, וע\"י מצות בלא כוונה, ואין הפי' שהוא בחי' מצות אנשים מלומדה מצד שאביו הרגילו, אלא שעושה בבחי' קבלת עול לבד והוא הנק' (בל\"א זיך אוועק גילאיגט כו') עי\"ז נעשה תוס' אור בג\"ע התחתון. ויש מצות הנק' ספיחי' דהיינו שעושה המצוה בלא שום כוונה אף לא בחי' קבלת עול אלא מצד רגילות לבד, ומ\"מ נק' בשם מצוה שהרי עכ\"פ נעשה רצה\"ע. והנה ג' מצות אלו הם בדומה לנמשל לג' מיני צמיחות הנ\"ל, כי מצות בכונה הוא נמשל לתפוח השדה שהוא ע\"י תיקון האדם ויש בו מתיקות. ותפוח היער שהוא בלי תיקון האדם כלל הוא המשל למצות בלא כונה רק בחי' קבלת עול. והמצות שהם גם בלי קבלת עול נמשל לספיחי' כמו עשב. וזהו כי כארץ תוציא צמחה וכגנה זרועיה תצמיח שהוא ג' מיני צמיחות הנ\"ל, כן יצמיח ה' צדקה ותהלה כו'."],[1900740409,"<b>והנה</b> אם אינם בשלימות כל הג' בחי' אלו רק אדרבה שיש חטאים ועוונות, וההפרש שבין חטא לעון הוא כי חטא הוא לשון חסרון והוא ביטול מ\"ע כי ידוע שמ\"ע הוא המשכת אלקו' וכשביטל מ\"ע אזי נק' בשם חטא וחסרון אור האלקי. ועון הוא שעבר על מל\"ת כי עון הוא לשון העוו את דרכם בחי' ארחות עקלקלות, כי ע\"י עשיית עבירה אזי משפיע תוס' יניקה לחיצונים, ולא די שנחסר האור האלקי ע\"י ביטול מ\"ע אלא אף זו שנתן יניקה לחיצונים, אשר ע\"ז נאמר מה לך לספר חוקי, אשר כמעט גם המצות שלו אינם כלום. ופי' לספר אינו כמו סיפור בעלמא אלא גם שפעם מתעורר בנפשו לעסוק בתומ\"צ עליו נאמר מה לך כו' שאינו נמשך לך כי יראים ליתן לו ההשפעה אלקי' מאחר שהעוה דרכו ויוכל להיות מזה השפעה לחיצונים. וזהו מה לך שאינו נמשך לך אלא שנעשה בבחי' הסתלקות. אך בזה הוא יתרון מעלה שבר\"ה ויו\"כ להשלים כל החסרונות שבביטול מ\"ע ולתקן כל הפגמים שע\"י מל\"ת. וזהו ענין צדקה ותהלה צדקה הוא בר\"ה ותהלה הוא ביוכ\"פ. כי הנה צדקה הוא צדק ה' בחי' דינא דמלכותא כו'. הענין הוא כי בר\"ה הוא התעוררות בחי' מלוכה עצמי' והוא כמו למשל באדם שיש בו בטבע מדת התנשאות כמ\"ש ורדו בדגת הים ובעוף השמים כו' הגם שאין על מי להתנשאות אך יש בו בטבע מדת התנשאות ולכן כשיש על מי להתנשאות מתנשא עליהם, משא\"כ בבהמה וחי' שאין בהם טבע זו בעצם. כמו\"כ יובן עד\"מ למעלה שבר\"ה הוא התעוררות מדת מלוכה אנא אמלוך שבעצמותו. ובזה יתכן מה שאומרים המלך הקדוש דקאי על בחי' מלוכה עצמי', ובכל עשי\"ת אומרים המלך הקדוש שהוא נגד ע\"ס, ובכל יום נמשך מדה א' עד יוה\"כ שאז התגלות רעוא דכל רעוין. אך צ\"ל מה שנק' בשם דינא דמלכותא כו'. הענין הוא כי דין הוא בחי' צמצום דהיינו כדי שיתעורר בחי' מלוכה בעצם צריך לזה ג\"כ בחי' צמצום ולכן נק' בשם דין. ועוד שצריך לבא השפע בהתחלקות לכל א' לפום שיעורא דילי' הן בגשמיו'"],[1900740410,"כמארז\"ל כל מזונותיו של אדם קצובי' לו מר\"ה כו', והן ברוחני' כמ\"ש משפט לאלקי יעקב שיש משפט בר\"ה כמה יומשך אלקות ליעקב כו'. ולכן נק' בשם צדקה צדק ה', צדק הוא דינא דמלכותא וה' הוא ה\"ח כו' כמאמר מכלכל חיים בחסד כו'. והנה מאחר שההמשכה הוא מבחי' אנא אמלוך לכן יש בכחו להשלים ולמלאות כל החסרונות הנק' חטא שהוא ביטול מ\"ע. ומ\"ש כי כארץ תוציא צמחה כו' כן יצמיח כו' הגם שבר\"ה ויוכ\"פ הוא התגלות אתעדל\"ע שאין אתעדל\"ת מגעת לשם, אך שמ\"מ הצדקה כו' תלוי מחמת ההכנה דמעשה המצות שנעשו עכ\"פ בשנה העברה כו'. ותהלה הוא ביוכ\"פ. הנה תהלה הוא הוי' בניקוד אלקים. הענין הוא כי תהלה הוא לשון אור כמ\"ש בהלו נרו עלי ראשי, יהל עלי אורו כו' והוא בחי' הבהקת האור. כי יש ב' מיני אור, הא' הוא אור שכאשר בא בתוך החושך אזי נכהה אורו, והב' הוא אור גדול שכאשר מאיר בתוך החושך אזי מהפך גם החושך לאור, וזהו ענין תהלה שהוא התגלות אור עליון מאד אשר מהפך חשוכא לנהורא מרע לטוב זדונות נעשו כזכיות.\n<b>נגד</b> כל הגוים. הענין הוא כי יש ז' מדות רעות ועשו וישמעאל הוא הכולל כולם. עשו הוא בחי' חמימות ותגבורת התאוה ברשפי אש, וישמעאל הוא בחי' חסד דקליפה בחי' קרירות והוא בחי' פריקת עול. וע\"י תהלה נעשה נגד כל הגוים, כמו הדוגמא שכתוב רוממות אל בגרונם וחרב פיפיות בידם לעשות נקמה בגוים, שע\"י רוממות אל שהוא השבחי' שבפסד\"ז אזי וחרב פיפיות בידם לעשות נקמה בגוים לאהפכא חשוכא לנהורא. ולכן נק' פסד\"ז פי' זמיר עריצים כו'. ולכן יש סברא שפסד\"ז הוא למעלה בשרש משמע ישראל כי שמע ישראל הוא ההתפעלות של הנשמה בעצם אין זה חידוש כ\"כ, אבל פסד\"ז שהוא לאהפכא חשוכא לנהורא מוכרח להיות הארה ממקום עליון יותר. וכמו\"כ"],[1900740411,"יובן גם כאן שע\"י תהלה נעשה נגד כל הגוים. כי הנה כתיב תיסרך רעתך, כי אין רע יורד מלמעלה רק האדם עצמו הוא העושה כמ\"ש מהרסיך ומחריביך ממך יצאו, שע\"י רע האדם מעורר למעלה כח הדין עליו, ולכן נתעוררי' למטה ג\"כ שונאים על ישראל בכל דור ודור עומדים עלינו לכלותינו כו', וע\"י תהלה נעשה נגד כל הגוים לאהפכא חשוכא לנהורא, קטיגור נעשה סניגור ברוחני' ובגשמי'. ומ\"ש הוי' בניקוד אלקים, כי הלא הוי' הוא כולו רחמים ומפני מה הוא בניקוד אלקים, הוא בחי' הגבו' שמאל דוחה לסט\"א כמשל התינוק שלכלך בגדו שא\"א להעביר הכתם כ\"א בדבר חריף. כמו\"כ יובן ביוה\"כ הוא התגלות רדכ\"ר כדי לטהר כל לכלוך וחטא ולכן הוא הוי' בניקוד אלקים כנ\"ל."],[1900740412,"<h3>להבין שרש ענין יוכ\"פ</h3>\n<b>עי\"כ תקע\"ח לפ\"ק</b>\n<b>להבין</b> שרש ענין יוכ\"פ שנק' בשם שבת שבתון שבו מאיר הארה מיום שכולו שבת. להבין זה צ\"ל מ\"ש כי הוי' הוא האלקים וביוכ\"פ אומרים ז\"פ כי הוי' הוא האלקים כו'. הנה בהוי' הוא האלקי' יש ב' פי', הא' הוא שהוי' נמשך ונתגלה בשם אלקים, והב' הוא ששם אלקים עולה ונכלל בשם הוי'. ולפי ב' הפי' אלו שם אלקים הוא למטה משם הוי'. והנה באליהו כתיב וירא העם ויפלו על פניהם ויאמרו כי הוי' הוא האלקים כו' ב\"פ, כי פעם ב' הוי' הוא האלקים פירושו ששם הוי' יש לו עלי' לבחי' אלקים שלמעלה גם משם הוי' כמ\"ש והי' הוי' לי לאלקים כו'. והנה ב' פי' הנ\"ל של הוי' הוא האלקים הוא ענין שילוב הוי' באדני או שילוב אדני בהוי', כי שילוב הוי' באדני הוא שהשם הוי' מאיר בשם אדני, ושם אדני הוא מה דאשתמודעא אדון על כולא כמ\"ש אל אדון על כל המעשים כו'. והיו\"ד הוא תחלה ואח\"כ האלף ואח\"כ ה' משם הוי' ודלית משם אדני כו'. וזהו הכלל שהאותיות ראשונים המה העיקר והבאים אחריהם המה טפלים. והוא פי' הא' של הוי' הוא האלקים שהוי' נמשך בשם אלקים ואינו נראה רק שם הוי' ושם אלקים הוא בטל וטפל לגבי שם הוי'. ושילוב אדני בהוי' הוא להיפך שהאלף תחלה ואח\"כ היוד כו' ושם אדני הוא הנראה עיקר, והוא פי' הב' של הוי' הוא האלקים ששם אלקים עולה בשם הוי' כו' כמשי\"ת."],[1900740413,"<b>ולביאור</b> הענין צ\"ל מ\"ש ואתה מחי' את כולם, את\"ה הוא א\"ת וה' הוא ה' מוצאות הפה אחה\"ע מהגרון כו', וכמ\"ש בדבר ה' שמים נעשו כו' שהתהוות כל העולמות הוא מבחי' אותיות ודבר ה', וצ\"ל מפני מה לא נברא העולם מבחי' מחשבה עליונה. אך הענין הוא עפ\"י משל מבשרי כשהדיבור הוא בא בהתחלקות כל אות מובדל בפ\"ע ע\"י שנצרף אות א' מאותיות אחע\"ה כו' ואות א' מדטלנ\"ת כו', כמו אותיות אדון עולם כו', הגם שבדיבור הוא ג\"כ בהתאחדות אבל כל אות ניכר במבטא בפ\"ע, משא\"כ במח' שם נסקרים כל האותיות בסקירה א' מבלי קדימת ראש וסוף. והוא כמשל תערובות יבש ביבש שגם שנתערבו יחד אבל כל דבר הוא מובדל בפ\"ע אבל מח' הוא כמו תערובות לח בלח. או כמשל עשרה חתיכות בצק שנילושו יחד שנעשו גוש א' כו'. והנה כמו\"כ יובן למעלה הגם שבאמת אין לו גוף ולא דמות הגוף כי אא\"ס הוא אחדות פשוט בתכלית הפשיטות אך מאחר שכתיב בדבר ה' שמים נעשו כו' הרי דברה תורה כלשון בנ\"א וניתן רשות להבין מדוגמא שבאדם למעלה ג\"כ. כי הנה נראה שבריאת העולמות הוא בהתחלקות, כמו שנראה בדצח\"מ שאבנים הוא מיסוד המים כמ\"ש אבנים שחקו מים, ומתכת הוא מיסוד האש הרי חלוק אבנים ממתכת. ובאבנים גופא שיסודם א' הוא ג\"כ יש הרבה חלוקי' שאין אבן א' דומה לזולתו. וכמו\"כ במתכת יש מיני מתכת טובים ויש מיני מתכת רעים. וכמו\"כ בצומח יש עשבים ממיתים ויש עשבים טובים המחיי' לנפש. זהו ההפרש בכלל ובפרט יש בעשבי' רעים חילוקי מדרגות הרבה, וכמו\"כ בעשבים טובים כו'. וכן בחיות ובהמות שיש טורפים ומזיקים ויש רחמנים. וכן בעופות העורב הוא אכזרי ונשר הוא רחמני. וכן במדבר שיש בנ\"א טובים בעלי חסד ויש בנ\"א רעים ואכזרים שחלוקי' מן הקצה לקצה. ובבנ\"א טובים גופא יש התחלקות כו'. וכמו\"כ בכוכבים שברקיע שאינם דומים הכוכבים שבצד א' ברקיע לכוכבים שבצד השני. וכמו\"כ יובן למעלה במלאכים דכתיב פני ארי' אל הימין שהוא מחנה מיכאל שעבודתם הוא בחי' אהבה, ופני שור אל השמאל מחנה גבריאל בחי' יראה, הרי חלוקי' הם בכללם. ובמחנה"],[1900740414,"מיכאל גופא יש הרבה חלוקי מדרגות כידוע שבמחנה מיכאל יש תק\"פ אלף מדרגות כו'. ולכן התהוות עולמות הוא דייקא מבחי' דיבור שהוא צירופי אותיות ויכול להיות התחלקות עד אין שיעור כמבואר בס\"י בענין רל\"א שערים המתגלגלות פנים ואחור כו' כמ\"ש בלק\"א. אבל מבחי' מחשבה אינו יכול להתהוות עולם הפירוד פי' שנתפרד לחלקים כי המח' הוא סוקר הכל בסקירה א' כמאמר במח' אחת צופה ומביט עד סוף כל הדורות בסקירה א' כו'. ועוד טעם שלא נתהוו העולמות מבחי' מח' מפני שהמח' מתאחדת עם העצם כמו כל הכוחות שכלולי' בנפש קודם בואה לגוף, ראי' שמיעה דיבור, כמו\"כ המח' שבמוח גם אחר שנתלבשה במוח היא מתאחדת עם העצם כמו הדוגמא קודם ירידתה לגוף. והגם שהמח' יורדת בדיבור שהרי מה שמחשב זה הוא מדבר, הוא בבחי' ירידה כו'. ולכן א\"א להיות התהוות העולמות מבחי' מח' כו'. וזהו ענין ב' הפי' הנ\"ל של הוי' הוא האלקים, שפי' הא' שהוי' מתגלה בבחי' אלקים הוא שמח' מאיר בדיבור והוא ענין שילוב הוי' באד'. והפי' הב' ששם אלקים יש לו עלי' לשם הוי' והוא שילוב אד' בהוי' הוא שבחי' דיבור יש לו עלי' במח'.\n<b>והענין</b> יובן עפ\"י הידוע שיש ב' מיני ניסים, נס בתוך הטבע ונס אשר למעלה מן הטבע. נס אשר למעלה מן הטבע הוא כמו הפך ים ליבשה שטבע המים להיות ניידי כו' ונמצא שהטבע נהפכה. או כמו גבי רחב\"ד שאמר מי שאמר לשמן וידליק יאמר לחומץ וידליק שהוא התגלות שם הוי', כי עפ\"י שם אלקים נטבע הטבע בשמן שידלק ולא בחומץ וכדי שהחומץ ידליק מוכרח להיות ההתגלות מבחי' מח' ששם נסקרים כל האותיות כא' מבלי קדימה ראש לסוף ויכול לשנות הצירופים. והוא ענין ברוך ה' אלקי ישראל מן העולם ועד העולם מעלמא דאתכסיא לעלמא דאתגליא. והוא ענין כ\"ו כל\"ח שהוא הארת שם הוי' בשם אלקים. וגם ענין הארת שם הוי' בשם אלקים יובן מהדוגמא דלעתיד שארז\"ל עה\"ב אין בו אכילה ושתי' אלא צדיקים יושבי' ונהנין מזיו השכינה. ומבואר ברמב\"ן שעוה\"ב יהיו הנשמות בגופים רק לא כמו"],[1900740415,"הגוף דעכשיו שמאב ואם כמ\"ש הן בעון חוללתי ובחטא יחמתני אמי, אלא שבנין הגוף יהי' מעצם הנשאר הנק' גרמא והוא כדוגמא עצמות דיחזקאל. אבל עכ\"פ גוף יהי' רק שיהי' מזוכך. ובאמת אם נשער ריחוק הערך שגוף יהנה וישבע מחיי אלקי כמו מאכילה ממש כמ\"ש ישבעו ויתענגו כו' ישבעו ממש, או כמו ויחזו את האלקים ויאכלו כו' שאינו עפ\"י טבע רק הוא היפך הטבע והוא הארת שם הוי' בשם אלקים שאינו נראה רק שם הוי' והוא ההיפך הטבע. וכבר הי' לעולמים דוגמא זה בימי משה דכתיב לחם אבירים אכל איש לחם שמלאכי השרת אוכלים אותו בעלייתו להר מ\"ם יום, ואחר ירידתו הי' צריך לאכילה גשמיו' ואם לא הי' אוכל לא הי' חי, ואותו הגוף עצמו בעלייתו לא אכל וחי מאלקות. זהו ג\"כ הדוגמא דלעתיד והוא הארת שם הוי' כו'. וכמו שנראה באדם שמרגיש כל הקורות אותו בבת אחת הכאב שבצפורני רגליו הגם שהחיות מובדל בפ\"ע בכל אבר ואבר לפי מזגו, מוכרח להיות שיש כח מנפש שמקיפם כולם כאחד. ועפ\"ז ג\"כ יובן ענין הארת שם הוי' בשם אלקים, כי אלקים הוא כח הפועל בנפעל וכל א' יש לו מדרגה בפ\"ע וע\"י הארת שם הוי' נתהפך הטבע כו'. ונס אשר בתוך הטבע הוא כמו הנס דאחשורוש והוא ענין עלי' דיבור במח' לקבל שם אור וירד למטה כמו שהוא ונק' שילוב אד' בהוי', ושם אד' הוא העיקר שהטבע נראית וד\"ל. וע\"פ קבלה נק' או שבריאה יש לה עלי' באצי' או שאצי' נמשך בבריאה.\n<b>וב'</b> בחי' אלו ישנם ג\"כ בענין הפרנסה, כי הנה ארז\"ל מזונותיו של אדם קצובים לו מר\"ה על כל השנה, וממה שקצוב לו בר\"ה לא יפחת ולא יוסיף גם שיהי' מייגע עצמו מאד בכל מיני התחכמות כו'. והנה אם הפרנסה באה לו ע\"י עסקו במו\"מ באופן שדרך הטבע מחייב שצריך להרויח זה נק' בשם נס בתוך הטבע. ונס אשר למעלה מן הטבע הוא כמארז\"ל אין אדם יודע במה משתכר, שלפעמים משתכר בדבר שעפ\"י דרך הטבע הי' צריך להפסיד, והוא ענין נס אשר היפך הטבע, ובזמן הבית לא הי' הגשמיות מסתיר על הרוחני' כלל כמ\"ש וברכך ה' אלקיך בכל אשר תעשה כו'. ובכלל בזמן הגלות הוא בחי' שילוב אדני בהוי', כמאמר הזוהר קוב\"ה בגלותא אסתלק לעילא"],[1900740416,"לעילא כו'. ולעתיד יהי' שילוב הוי' באדני כו'. ועפי\"ז יובן ב' הפי' הנ\"ל של כי הוי' הוא האלקים, או שמח' מאיר בדיבור, או שדיבור עולה במחשבה. והענין הוא כי עשרה ימי' שמר\"ה עד יוכ\"פ הוא בחי' עליות שם אלקים בשם הוי', ועשרה ימים שמיוכ\"פ עד שמע\"צ הוא המשכות הוי' באלקים, ועצרת הוא זמן הקליטה כו' כידוע.\n<b>ועתה</b> י\"ל פי' הב' של כי הוי' הוא האלקים ששם הוי' יש לו עלי' בשם אלקים. הענין הוא כי ע\"ס נק' בזוהר רזא דשמא קדישא, בחי' ע\"ב ס\"ג מ\"ה ב\"ן שם לבד, כמו שם האדם עד\"מ שאינו אלא לפנות לקוראו כשיקראוהו בשמו, אבל השם אינו עצמותו כו'. כמו\"כ יובן למעלה שאא\"ס הוא אחדות פשוט בתכלית הפשיטות וכדי שיתהוה בחי' הוי' שהוא ע\"ס כי קוצו של יו\"ד הוא בחי' כתר, ויו\"ד חכמה, ה' בינה כו', צ\"ל לזה צמצום עצמותו והוא בחי' שם אלקים שלמעלה משם הוי', דהיינו כדי שיתהוה בחי' הוי' שהוא גם בחי' מח' אחת הצופה ומביט כו' שמרומז באות יו\"ד כו', צריך לזה צמצום והוא הנק' שם אלקים. וביו\"כ הוא עליי' שם הוי' בשם אלקים הנ\"ל. וזהו ענין אמירת ז\"פ כי הוי' הוא האלקים בנעילה דיוכ\"פ. ועתה יתפרש ענין כי הוי' הוא האלקים הנ\"ל, שמר\"ה עד יוכ\"פ הוא עליו' שם אלקים בשם הוי', וביוהכ\"פ ההוי' עולה לבחי' שם אלקים שלמעלה ממנו, ומיוכ\"פ עד שמע\"צ ההמשכה הוא משם אלקים לשם הוי' ומשם הוי' לשם אלקים שלמטה ממנו כו'.\n<b>והנה</b> לעתיד נאמר והי' ביום ההוא יום א' הוא יודע לה', שמה שעכשיו הוא כ\"א יום דהיינו מר\"ה עד יוכ\"פ יו\"ד ימים עליות, ויו\"ד ימים שמיוכ\"פ עד שמע\"צ הרי כ' יום ושמע\"צ הרי כ\"א ולעתיד יהי' מכ\"ז יום א'. והענין יובן עפ\"י משל הידוע, שני בנ\"א א' עומד בהר גבוה והשני עומד בגיא עמוק שיש בזה שני אופנים שיתייחדו, או שהתחתון יעלה למעלה ושם יהי' מקום היחוד, או שהעליון ירד למטה. וכמו\"כ יובן שעכשיו שיש בחי' מעלה ומטה שייך לומר עליות וירידות, אבל לעתיד יהי' אא\"ס למטה כמו למעלה ואין שייך"],[1900740417,"לומר עליות וירידות כלל כידוע. ולכן יבוטלו טורפים ומזיקים לעתיד כמ\"ש לא ירעו ולא ישחיתו כו' וכתיב וגר זאב עם כבש כו' מפני שיהי' גילוי אלקות.\n<b>והנה</b> הארה מעין דלעתיד הוא ג\"כ עכשיו ביוהכ\"פ כי ביוה\"כ העלי' הוא לבחי' אלקות שלמעלה משם הוי' אשר לגבי בחי' זו אין שייך לומר מעלה ומטה כלל, והוא ע\"י בכי' ותשובה שישראל עושי' למטה ומעוררים רחמים על עצמם ע\"י שמשפילים א\"ע ואומרים אשמנו תעבנו כו'. וזהו שובה ישראל עד הוי' אלקיך, שהוי' יהי' לו עלי' לבחי' אלקים הנ\"ל כמ\"ש והי' הוי' לי לאלקים כו'. והענין הוא כי הרחמנות נק' בשם בריח התיכון המבריח מן הקצה אל הקצה, מן הקצה העליון עד קצה התחתון, ותחלה צ\"ל קצה התחתון דרחמנות, כי ענין רחמנות אינו נופל אלא על דבר אשר נעדר מאתו כל מעלה, כי על איש עשיר אינו נופל לשון רחמנות, או על בעל תורה ויר\"ש אינו נופל שם רחמנות כו' רק רחמנות הוא דייקא על דבר המושפל בתכלית השפלות. וההפרש שבין רחמנות למדת חו\"ג הוא, שמדת חסד ]הרי[ יש מדת הדין המנגד למדת החסד שגם שירצה להיטיב חסדו לזולתו יבא מדה\"ד ויגבר על מדת החסד, וכמו\"כ ]בהתג[בר מדה\"ד יעמוד נגדו מדת החסד, משא\"כ למדת הרחמים לא יסתור מדה\"ד שהרי מדה\"ר היא אחר מדה\"ד שגם שחטא וראוי לעונש מ\"מ מצד הרחמנות יכופר עון. ובמדת הרחמים גופא יש ב' מדרגות. יש רחמים אשר יש להם גבול כמו אם הורג נפש שלזה גם מדה\"ר לא ירחם עליו, אבל יש רחמים הנק' ר\"ר והוא כמו הרחמנות של אב לבן שגם אם יעשה הבן כל החטאים לא יכלו מדת הרחמים של אביו עליו, או כמו אדם לעצמו שכל מה שיעשה גם אם יהרוג נפש מ\"מ יהי' לו רחמים על עצמו. וזהו מ\"ש ובכה תבכה, ב' מיני בכיות כו'. והנה התעוררות רחמים שביוכ\"פ הוא בחי' ר\"ר, והתעוררות רחמים זו בא דייקא ע\"י הריחוק כמשל בן שנתרחק מאביו שהרחמנות הוא ביתר שאת וכפליים. וכמו\"כ יובן בעבודת ה' כמאמר מים תחתונים בוכי' אנן בעינן למהוי קדם מלכא, מים תחתונים קאי על נשמות שבגופים שנתרחקו מאד מאור פני מלך חיים, בוכי' אנן בעינן כו' מפני שקודם ירידתם בגוף היו שם כמ\"ש חי ה' אשר עמדתי לפניו כו'"],[1900740418,"ונתרחקו לכן גדלה הרחמנות. וזהו ענין הבכי' דיוהכ\"פ בשפלות עצומה אשמנו תעבנו כו' שאין בו שום מעלה כלל, שהוא בחי' קצה התחתון דרחמנות, עי\"ז נתעורר קצה עליון שהוא בחי' ר\"ר כמו הדוגמא דלעתיד דכתיב וברחמים גדולים אקבצך, והוא בחי' שם אלקים שלמעלה משם הוי', ובחי' זו נמשכת על כל השנה ומתלבשת בתומ\"צ. ויש הפרש בין תורה למצות, שבמצות ארז\"ל עבירה מכבה מצוה אבל אין עבירה מכבה תורה. והענין יובן עפ\"י מה שמבואר במדרש ע\"פ זמירות היו לי חוקיך כו' משל למלך שהי' לו עבד מיטב נגן והגם שחטא פעמים רבות מחל לו המלך על סרחונו מפני שאם יענשהו ויהרגהו לא יהי' לו מנגן, אחר זמן אירע שחתכו לו אצבעותיו והתחיל המלך לתבוע כל החטאים שעשה עד הנה, כי הטעם שמחל לו הוא רק מפני שהי' מנגן אבל עכשיו שבטל טעם הדבר תבע ממנו הכל כו'. והענין יובן ג\"כ לעניננו כי התורה נק' בשם זמירות כמ\"ש זמירות היו לי חוקיך כו', שיש ב' מיני זמירות, זמירות דתפלה וזמירות דתורה. והענין הוא כי התורה הוא בחי' פנימי' חכמה כמו שהחכמה היא בבחי' אין וידוע שיש בחי' יחידה בכל נפש מישראל שהוא ג\"כ בחי' פנימי' כנ\"ל, כי מ\"ש כולם בחכמה עשית הוא חכמה חיצוני', והנה כשישראל שיש לו נשמה בגוף לומד התורה שהיא בחי' פנימי' חכמה ונתלבשה באותיות התורה אזי הוא עושה בחי' ממוצע להחיות העולמות כמארז\"ל אין העולם מתקיים אלא בהבל תשב\"ר שע\"י לימוד בחי' פנימי' חכמה באותיות ונשמה שלומד היא ג\"כ מלובשת בגוף עי\"ז עושה בחי' ממוצע להיות העולם מתקיים. ולכן ארז\"ל ע\"פ על מה אבדה הארץ על עזבם את תורתי, ויתר הקב\"ה על ע\"ז ולא ויתר על ביטול ת\"ת, דמשמע שאם היו עוסקים בתורה גם שהיו עוברים על ע\"ז כו' לא אבדה הארץ מאחר שלומדים התורה שהוא בחי' ממוצע כמשל המנגן הנ\"ל, אבל אחר שעזבו את התורה שלא למדוה באותיות נמצא שאין הכלי כמשל הנ\"ל, לכן אבדה הארץ וד\"ל. ונמצא שאין עבירה מכבה תורה, אבל את המצות עבירה מכבה מאחר שהמצות מלובשים בפו\"מ כו' לכן עבירה מכבה אותה כו'. וזהו שובה ישראל עד הוי' אלקיך שהוי' עולה לבחי' אלקים הנ\"ל שלמעלה משם הוי', ואח\"כ קחו עמכם דברים שבחי' זו נמשכת בתומ\"צ כו' כנ\"ל וד\"ל."],[1900740419,"<h3>להבין שורש ענין סוכה ולולב</h3>\n<b>יום א' דסוכות, תקע\"ח</b>\n<b>להבין</b> שורש ענין סוכה ולולב, הנה מבואר בכוונות שכל ענין הלולב וח\"י נענועיו הוא להמשיך דעת לנוק' ולולב הוא אותיות לו לב. והענין הוא כי כנס\"י נק' בשם נוק' נשים דעתן קלות, וכתיב אשרי איש ירא את ה', איש דייקא ולא בחי' אשה. פי' נוק' הוא בחי' מקבל דהיינו אם יש התעוררות תשובה למעלה כמארז\"ל בת קול מכרזת בכל יום שובו בנים שובבים, אזי מתעוררי' בתשובה ואם לאו שאין התעוררות מלמעלה אין בהם הכח להתעורר מצד עצמם. וכמו\"כ בענין התפעלות אוי\"ר, אם יש התעוררות בחי' חסד למעלה נתעורר אהבה בלב כנס\"י וכשיש התעוררות בחי' יראה נתעורר בחי' יראה, אבל אין מתעוררי' מצד עצמם. ובחי' דכר הוא שיש בו הכח מצד עצמו להתעורר בהתעוררות תשובה ואוי\"ר כו' הגם שאין מעוררים אותו מלמעלה. וההפרש שבין בחי' איש לבחי' אשה הוא שבחי' אשה דעתן קלות פי' שהדעת שלהם אינו חזק ויכול להיות היסח הדעת, שהגם שבעת ההתעוררות הדעת שלהם חזק שבלתי יכול לדחות אותם מזה, הוא רק בחי' דמיוני אבל אחר זמן יכול להיות היסח הדעת שהדעת הראשון נעתק וניסח לגמרי כאלו לא הי' כלל לחפוץ היפוכו לגמרי. וכמו\"כ יובן בעבודת ה', שכשהוא בבחי' נוק' שהוא בחי' מקבל אזי הדעת קל ואינו מתקיים שמיד אחר התפלה יהי' לו דעת בההיפוך, אבל בבחי' דכר הדעת שלו חזק ואינו נפסק כלל. וזהו ענין ב' הפסוקים שהוא מ\"ש וידעת היום והשבות אל לבבך כו' וכתיב השמר לך פן תשכח כו', שבחי' וידעת והשמר המה שני הפכי' בתכלית, שוידעת קאי על דעת דדכו' שאין שייך בו בחי' שכחה כלל, והשמר פן תשכח קאי על בחי' אשה שיכול להיות שכחה והיסח הדעת כו'. וזהו ענין להמשיך דעת לנוק', ואין המכוון שהוא בחי' התעוררות שא\"כ הרי הוא עכ\"פ בבחי' נוק', אלא פי' להמשיך דעת לנוק' היינו שהנוק' יהי' לה בחי' דעת דדכורא בחי' איש."],[1900740420,"<b>ולביאור</b> הענין צריך להקדים שיש ב' בחי' דעת, דעת עליון ודעת תחתון. וענין דעת ידוע שאין פירושו לשון ידיעת פשט הדבר אלא פי' דעת הוא לשון הרגשה והוא (הנק' בל\"א דער הער כו'), וחוש זה הוא הוא מגידי המוח (הנק' נערון) וכמ\"ש ישראל לא ידע עמי לא התבונן, שהמכוון של הידיעה הוא ענין חוש הרגשה הנ\"ל, ולעתיד יהי' בחי' הדעת בשלימות כמ\"ש וידע כל פעול כו' בבחי' תמידי', ולכן לא יוכלו לבא לידי חטא כלל כמ\"ש יראת ה' על פניכם לבלתי תחטאו.\n<b>וענין</b> דעת הרגשה יובן ממילי דעלמא כמו עד\"מ האדם שמשכיל באיזה מו\"מ איך שיכול להרויח בזה, הנה אחר שהשכיל בשכלו איכות טוב המו\"מ אזי נקבע בחי' דעת בנפשו שהוא חוש ההרגשה של המו\"מ זה. או כמו בענין ההיפך שהוא להרחיק מדבר המזיק לנפשו כמו מאנשי רוצחים, שאחר שהשכיל בשכלו הפחד אזי נשאר בו חוש ההרגשה הנ\"ל עד שאין יכולים להסיר הפחד מלבו כלל גם אם יסתרו לו השכל. וכמו\"כ יובן בענין תאות האכילה שאם אוכל ושכלו הוא בדבר אחר אינו שומע ומרגיש כלל טעם המאכל, אבל אם משים לבו לדבר המאכל אזי נרגש בנפשו טעם המאכל, וכמו מארז\"ל אין קישוי אלא לדעת כו' וכמו והאדם ידע כו' שהוא בחי' ההתקשרות. וכמו\"כ יובן בעבודת ה' שההתבוננות ואתה מחי' את כולם כו' בהסבירים שונים לקרב אל השכל אזי נקבע בחי' דעת בנפשו, והוא הדעת שאחר ההתבוננות שהוא הקיצור אשר נקלט במוחו אחר התבוננו' באריכות, ובחי' זו נק' בשם דעת תחתון, דעת המתפשט כו'. ובחי' דעת עליון הוא ענין כח המביא כל הנפש. ויובן הענין מאדם הלומד שאם לומד בלי קדימת הרצון וחשק להלימוד אזי הלימוד הוא דרך מעבר בעלמא בלי חריפות והתחדשות סברות, משא\"כ כשקדם הרצון לזה דהיינו ההסכם שרוצה ללמוד ולהבין דבר זה ופונה א\"ע מכל עסקיו, אזי יהי' הלימוד בהעמקה עד שיוכל לחדש בו סברות והמצאות, והוא ענין מה שמביא נפשו בדבר זה ונק' בשם המשכת כל הנפש כו' (ובל\"א נק' ער לייגט זיך אריין כו'). וכמו למשל בענין הסיפור לאדם מאיזה פחד גזלנים אם לא ישים נפשו לזה כלל הגם שישמע לא ישמע וירגיש רק אם אם ישים נפשו לזה, אזי אז כשישמע מענין זה ירגיש הפחד הזה. ובחי' זו נק' בשם בר דעת והוא דייקא אצל דכר כי בבחי' נוק' אינו בטבע בחי' זו דהיינו שאחר שנקלט בה הדעת הוא אצלה בחיזוק לפי שעה. אבל בחי' ד\"ע שהוא"],[1900740421,"הנק' בחי' כח המביא אין בה כו'. ועפי\"ז יובן בעבודת ה' ענין דעת עליון שהוא ענין המשכת כל הנפש והוא ד\"ע דמזווג חו\"ב כו'. וע\"ז כתיב ובדעת חדרים ימלאון כל הון כו', שהדעת זה הוא כח ומקור לכל מיני התפעלות הן להתפעלות חדוה והן להתפעלות מרירות, מאחר שממשיך כל נפשו נכלל בזה כל הפרטי' כו', ולא כמו דעת תחתון שהוא בחי' פרטי' דהיינו הדעת והרגשה בדבר פרטי שאחר התבוננות כו'. וע\"ז קאי הציווי וידעת היום כו' אתה הראת לדעת על בחי' דעת עליון. וזהו מ\"ש לקנות חכ' ולב אין, שלכאורה אינו מובן שתולה דבר גדול בקטן כי הרי הלב הוא למטה מן החכ', אלא פי' ולב אין קאי על ד\"ע שהוא הרצון שירצה לזה החכמה כו', ואותה אנו מבקשים בברכת אתה חונן לאדם דעת, דעת עליון דוקא כו'. וזהו להמשיך דעת לנוק', להמשיך בה בחי' דעת עליון דייקא ע\"י נטילת לולב בסוכה. ובחי' זו נק' מקיף הבא לידי גילוי, כי הסוכה הוא בחי' מקיף כמ\"ש וסוכה תהי' לצל יומ\"ם מחורב כו', שהסוכה אינה מחיצה המפסקת לגמרי בין חום השמש ובין האדם, אלא הסוכה היא כדי שלא יבא להדיא חום השמש אלא שהשמש יתלבש בתוך הסכך ומשם יאיר השמש. וכמו\"כ יובן למעלה כי בחי' כעצם השמים לטוהר בחי' מקיפי' דטה\"ע אלו הי' מאיר בגילוי כמו שהוא הי' בחי' כלות הנפש לזאת נתלבש בסכך דסוכה בבחי' מקיף. וענין נטילת לולב בסוכה הוא להמשיך ממקיף זה לגילוי.\n<b>וביאור</b> הענין הוא כי הנה כתיב שמאלו תחת לראשי וימינו תחבקני, שמאלו תחת לראשי הוא בר\"ה ויוכ\"פ וימינו תחבקני הוא בסוכות כאדם המחבק לחבירו שמקיף ראשו ורגלו כאחד. והענין יובן עפ\"י משל האהבה דאב לבנו שיש ב' מיני אהבה, הא' הוא אהבה אשר מצד חכמתו כמ\"ש בן חכם ישמח אב שהשמחה היא מצד חכמתו או מצד מדותיו הטובים וכשהבן רואה אהבת אביו אליו מצד חכמתו אזי תיקר אהבתו אליו ג\"כ ומתגבר עוד בחכ' ומוסיף תוס' אהבה באביו. ויש אהבה לבן הנק' ילד שעשועים דהיינו האהבה לבן קטן שאין בו עדיין בחי' חכמה כלל רק האהבה הוא מצד העצמיות"],[1900740422,"וכי הוא בן זקונים שלו וכדומה, והתינוק אינו משיג כלל ג\"כ אהבת אביו אליו כו' ונק' בשם העלם בהעלם כו'. ועפ\"י משל יובן ההפרש שבין יוכ\"פ לסוכות, שביוכ\"פ הוא בחי' בן חכם ישמח אב ובסוכות הוא בחי' ילד שעשועים כמ\"ש הבן יקיר לי אפרים אם ילד שעשועים ע\"כ המו מעי לו כו'. כי ידוע שביוכ\"פ הוא בחי' עליות והעליות קאי על נשמות שלמעלה, כי סליחת עוונות שביוהכ\"פ הוא לשרש הנשמות. כי ידוע שיש ב' בחי' נשמות, נשמה שבגוף כמ\"ש נשמה שנתת בי כו' ושרש הנשמה שלמעלה כמ\"ש אך בצלם יתהלך איש כו', כמו אע\"ג דאיהו לא חזי מזלי' חזי, שלכל נפש מישראל יש בחי' מזל למעלה והמזל הוא השרש הנשמה. והנה ע\"י שנשמה שבגוף נפגמה בלכלוך חטאים ועוונות אינה יכולה בחי' שרש הנשמה שהוא נשמות שלמעלה לחיות מבחי' מקור חוצבם, וע\"י תשובה דיוכ\"פ שהוא ממעמקים בחי' עומק הלב כו' נסלחים עוונות וחטאים ויכולים לחיות הנשמות שלמעלה. וזהו ענין עליות הנשמות דיוכ\"פ כנ\"ל. ובחי' זו נק' בשם בן חכם ישמח אב שהשמחה עליונה הוא מצד החכ' כו' (כי בנשמות עליונות יש ג\"כ בחי' מוח ולב כו'). ובסוכות נק' בשם ילד שעשועים כי ענין סוכה ולולב הוא המשכה לנשמות שבגופים ובחי' זו נק' בשם ילד שעשועים שהאב משתעשע עמו מצד עצמיות ולא מצד חכמתו, כי כל מה שנשמה שבגוף משגת ומתפעלת מאלקות הגם שהוא על אופן היותר טוב אין זה ערך כלל לבחי' השגה של שרש הנשמה, כי הרי הנשמה מלובשת בנפש הטבעי' וההשגה היא עם אותו השכל עצמו שבזה העולם כו' ולכן נק' בשם ילד שעשועים. וזהו מ\"ש וימינו תחבקני בסוכות כמשל אדם החובק לחבירו שמקיפו כולו כא', כמו\"כ הוא בסוכות, כי ביוכ\"פ הרי האהבה מלובשת באיזה דבר פרטי שהוא מצד המוח והלב כנ\"ל אבל בסוכות אין האהבה מלובשת בדבר פרטי כלל רק מצד ילד שעשועים כו' וד\"ל.\n<b>וענין</b> לולב הוא להמשיך מבחי' מקיף זה לידי גילוי, ואותיות לולב הוא לו לב, ובלב יש ב' פי', הא' הוא ל\"ב נתיבות החכמה שהוא להמשיך בחי' דעת זה במוח, והב' הוא בחי' לב ממש להמשיך גם בלב. ולכן מברכים לולב בסוכה שהוא להמשיך ממקיף לידי גילוי והוא הדוגמא דלעתיד דאז יהי'"],[1900740423,"הדעת בשלימות כמ\"ש וידע כל פעול כי אתה פעלתו ויבין כל יצור כו' שאין הפי' ידיעה בעלמא שהלא גם עכשיו הכל יודעים שאתה מחי' את כולם, אלא פי' וידע הוא בחי' הרגשה כנ\"ל, מפני שאז יהי' גילוי אלקות, ולכן יבוטלו הטורפים ומזיקים כמ\"ש לא ירעו ולא ישחיתו כו' וכתיב פרה ודוב תרעינה יחדיו ירבצו ילדיהן שעכשיו הם מזיקים מפני שכעת הוא בחי' הסתר אלקות אבל לעתיד שלא יהי' רע כלל כמ\"ש ואת רוח הטומאה אעביר מן הארץ יהי' גילוי אלקות על כל הברואים ולא יוכלו לבא לידי חטא כלל כמ\"ש יראת ה' על פניכם לבלתי תחטאו כו' שלא יוכלו לבא לידי חטא כלל, כי עכשיו יכול להיות היסח הדעת וצריך לזה להזהיר השמר לך פן תשכח כו' אבל לעתיד לא יוכל להיות שכחה כלל, ובחי' זו מלובשת עכשיו בסכך דסוכה בשלימות וכמו בתיבת נח שהי' ג\"כ ההארה מעין דלעתיד שהרי היו שם מינים המזיקים זל\"ז ולא הזיקו אז כו'. וכמו\"כ הסוכה הוא ג\"כ כמו לעתיד, ובסכך דסוכה הוא ממש כמו לעתיד ואלו הי' מאיר בגילוי כמו שהוא בסכך דסוכה הי' ממש כמו לע\"ל שיהי' יראת ה' לבלתי תחטאו כנ\"ל, אלא שאינו מאיר בגילוי רק הארה אפס קצהו ע\"י לולב.\n<b>וביאור</b> הענין כי שרש דסוכה הוא למעלה מעה\"ד טו\"ר, והענין יובן עפ\"י הידוע שיש ב' בחי' תענוג, תענוג עצמי ותענוג שמצד השכל כמו בהתבוננות ואתה מחי' את כולם שמקרב אל השכל איך שהוא מחי' מאין ליש בהתבוננו' והסבירי' ונתפעל באהבה וכדומה, הנה התענוג שמצד האהבה הוא התענוג אשר נקנה מהשכל ויכול להיות אחר התפלה ההיפך שהוא האהבה זרה ותענוג זר כענין אברהם יצא ממנו ישמעאל כו', שאברהם הוא אהבה דקדושה ובהסתעפות יצא ממנו ישמעאל שהוא חסד דקליפה וחסד לאומים חטאת כל טיבו דעבדין לגרמייהו עבדין להתייהר כו', הגם שבשעת האהבה לאלקות לא ניכר שום תערובות רע אך מצד ההסתעפות רע מזה מוכרחים אנו לומר שיש"],[1900740424,"בזה ג\"כ תערובות רע. וכן יצחק יצא ממנו עשו שיצחק הוא גבורות דקדושה בחי' רשפי אש והתלהבות וד\"ח יקרים בעיניו מאד, ובהסתעפות יצא מזה עשו שהוא גבו' דקליפה רציחה וכעס מזה מוכרחים אנו לומר שיש תערובת רע בטוב, אבל יש תענוג עצמי שאין בו תערובות רע כלל, והוא התענוג מעצם הדבר כמו שהוא ולא ההסבר איך שואתה מחי' את כולם אלא מהות ועצם הדבר מאין ליש. ועפי\"ז יובן ענין סכך דסוכה ג\"כ ששרשו הוא למעלה מעה\"ד טו\"ר ולכן אין מסככין אלא בדבר שאינו מקבל טומאה, כי טומאה וטהרה הוא בבחי' השתלשלות עה\"ד טו\"ר אבל סוכה שרשה למעלה מעה\"ד טו\"ר ולכן אין מסככין אלא בדבר שאינו מקבל טומאה ששרשם ג\"כ מבחי' מקיפים עליונים שאין בהם תערובות רע כלל, וגידולו מן הארץ הגם שבארץ יש תערובת טו\"ר אך פי' וגידולו מן הארץ הוא כמו שהארץ היתה בלי תערובת רע כו', ומבחי' זו ממשיכי' הארה אפס קצהו ע\"י לולב, ובעצרת הוא ענין קליטה שהוא מה שנקלט בכל נשמה על כל השנה בחי' גילוי אלקות שמצד ההתבוננות כו' כמ\"ש במ\"א באריכות וד\"ל."],[1900740425,"<h3>להבין שרש ענין סוכה ולולב</h3>\n<b></b><b>בעז\"ה יום ב' דסוכות תקע\"ח לפ\"ק</b>\nיום ב' דסוכות\n<b>להבין</b> שרש ענין סוכה ולולב, הנה סוכות נק' זמן שמחתינו לשון רבים ב' שמחות, כי ביו\"כ השמחה הוא למעלה בשרש הנשמות כמ\"ש אם הבנים שמחה. בנים נק' נשמות שבגופים ואם הבנים הוא אימא עילאה שמחה ביוכ\"פ ע\"י תשובה של ישראל למטה, כי אם לא התשובה שלמטה לא הי' השמחה עליונה כ\"כ. ובסוכות נמשכת אותה שמחה עצמה למטה, רק ההפרש שבין יוכ\"פ לסוכות הוא שביוכ\"פ השמחה היא בפנימי' בינה כידוע שיוכ\"פ נק' בשם יובלא עילאה עולם החירות, ובסוכות אותה השמחה עצמה היא בבחי' חיצוני' כמשי\"ת, ולכן נק' שמחתנו שב' השמחות הם שלנו, שגם השמחה עליונה דיוכ\"פ היא שלנו ע\"י תשובה כנ\"ל.\n<b>ולהבין</b> זאת היטב צריך להקדים מה שמבואר בפע\"ח ע\"פ מכל מלמדי השכלתי כי עדותיך שיחה לי, שמכל מלמדי הוא בחי' חו\"ב שנק' בשם מלמדי כמ\"ש אאלפך חכמה אאלפך בינה, ועדותיך שיחה לי הוא תורה, וגם עדותיך הוא אותיות דעת שהוא הדעת אשר בחשאי. ותחלה צ\"ל ענין דעת שאין פירושו לשון ידיעה אלא דעת הוא לשון הרגשה כמבואר לעיל במשל מענין המו\"מ שאחר שהשכיל בשכלו איכות טוב המו\"מ אזי אז נשאר בו חוש ההרגשה שהוא מגידי המוח הנק' נערוין, ואחר שנתפעל בבחי' דעת זה אזי נסתלק השכל והטעם של הדעת זה. או כמו התפעלות הפחד מרוצחים וכדומה שמתחלה משכיל בשכלו שצריך לפחוד ואחר שהשכיל ונתפעל נסתלק השכל ונשאר בו חוש ההרגשה לבד, שגם אם יסתרו להשכל לא יסתור החוש. או כמו"],[1900740426,"תאות האכילה שא\"צ לזה שכל כלל להשכיל בענין אכילה אלא שמרגיש שרוצה לאכול וכדומה. ועפי\"ז יובן בעבודת ה' ג\"כ שהנה מתחלה מתחיל מהתבוננות והסבירי' איך שאתה מחי' את כולם מאין ליש, ואחר ההתבוננו' אז נקבע דעת והרגשה במוחו ואור הבינה נסתלק שהוא רוחב ההסבר רק שנשאר הקיצור שהוא מחי' את כולם, וממוח נמשך בלב כמ\"ש וידעת היום והשבות אל לבבך, שדעת זה עצמו נמשך בלב ג\"כ ונולד מזה בלב בחי' תשוקה והמשכה. וכמו\"כ יובן במוח החכמה שידוע ההפרש שבין חכמה לבינה, שבינה הוא ההסבר לאורך ורוחב וחכמה הוא לאסתכלא ביקרא דמלכא בחי' ראי' ולא התבוננות איך שהוא מחי' אלא שנקבע בו בבחי' ראי' כידוע, וה\"ז כמשל הרואה את המלך שא\"צ להסבר כלל, ובחי' ראי' זו נמשך ג\"כ בלב. ומבחי' ראי' לא שייך לומר שיש בחי' אהבה והמשכה בלב, אלא בחי' ביטול שהרי בראות האדם למלך הרי נתבטל מעצמותו ולא שייך לומר אז שיש לו אהבה להמלך. וזהו שכתוב מכל מלמדי השכלתי שהלב מקבל מב' הבחי' הן ממוח החכמה והן ממוח הבינה כמאמר הלב שומע הלב רואה, שחו\"ב נק' בשם ראי' ושמיעה. והנה בחי' חו\"ב הרי הם באים בגילוי בלב וע\"ז כתיב לבי ובשרי ירננו אל אל חי, בכל לבי דרשתיך כו', אבל עדותיך שיחה לי הוא הדעת שבחשאי כמו ענין צלותא בלחש וקולה לא ישמע.\n<b>ועפי\"ז</b> יובן ענין סוכות ולולב. ותחלה צ\"ל הטעם מה שנק' בשם חיצוני' שהלא סוכות הוא בחי' מקיפים ונק' בשם צילא דמהימנותא. אך להבין זה צריך להקדים המשל מהבל הלב שבאדם, שידוע שיש הבל בלב המורכב מאמ\"ר והוא בחי' החומר לבד. וצורת הבל זה דהיינו החיות תלוי כשמאיר בו בחי' רצון ושכל או אהבה כו' שאז יש בההבל חיות, משא\"כ כשאינו מאיר בו כלום אזי הוא כגולמי חומר בלא צורה. ועפי\"ז יובן ענין סוכה, כי הנה מיוכ\"פ עד סוכות ויום א' דסוכות בכלל נמשכי' חמש בחי' מקיפים שהוא כח\"ב חו\"ג והוא הנק' בשם רצון ושכל ומדות אך שהם בבחי'"],[1900740427,"מקיף, והוא כמ\"ש ואני בהמות כו'. וענין לולב הוא להמשיך מהעלם לגילוי בבחי' חיצוני' דייקא. והענין הוא כי ההתחלה הוא מיוכ\"פ שאז כתיב לפני הוי' תטהרו, כי נר הוי' נשמת אדם הוא נשמה שבגופים, אבל לפני הוי' תטהרו שביוכ\"פ קאי על שרש הנשמות כי ביוכ\"פ הוא עליית שרש הנשמות למקור חוצבם ע\"י תשובה כי תשובה בלא יוכ\"פ ויוכ\"פ בלא תשובה אינו מועיל רק דייקא יוכ\"פ עם תשובה מעומקא דלבא כמ\"ש ממעמקים קראתיך מעומק הלב.\n<b>והענין</b> כי יש הבל פנימי שהבל הנ\"ל המורכב מאמ\"ר הרי הוא מורגש בלב, אבל יש הבל פנימי דלא משתמע, ובחי' זו נתעורר ביוכ\"פ והוא מחמת שנגע אל לבו במאד על גודל הריחוק מאלקות, אשמנו תעבנו כו', וכל א' אומר זה בלב נשבר בלבא ריקניא עי\"ז נתעלי' הנשמות למעלה דהיינו דייקא ע\"י הריחוק כנ\"ל. והענין יובן עפ\"י משל בן שנתרחק מאביו כמה שנים, הנה בראותו אזי אז השמחה היא ביתר שאת ובכפליים משהיתה באמנה אתו. הענין כי אז נתעורר בחי' עצמיות יותר מחמת הריחוק, פי' כי כשהי' אתו יחד בקירוב לא יכולה אהבה זו לבא בגילוי וע\"י הריחוק דייקא נתעורר' אהבה זו. או כמשל מאהבת עצמו שאדם אוהב א\"ע, אבל התגלות האהבה עצמיו' שלעצמו הוא דייקא בהיפוכו כמו בצער הנוגע לו בגופו אזי אז נתפעל מאד ורואה כל תחבולות כי נתגלה אהבת עצמו. כמו\"כ יובן למעלה שדייקא מצד הריחוק שביו\"כ שמשפילי' א\"ע עד קצה התחתון באמרינו אשמנו כו' עי\"ז ניתוסף שמחה בשרש הנשמות יותר כנ\"ל וד\"ל. ושמחה זו עצמה נמשכת בסוכות בבחי' חיצוני' והשמחה שבבחי' חיצוני' שם הוא יותר התגלות העצמיו' שמחה. וכמשל הבן שנתרחק מאביו ואח\"כ כשנתקרבו יחד אזי השמחה אינה מלובשת בבחי' פנימי' אלא בבחי' התקרבות חיצוני'. או כמשל אדם שיש לו אוצר ממון בביתו וכשהוא בדרך ואינו רואהו רק יודע שיש לו אוצר אזי השמחה היא רק מצד בחי' אמונה, אבל כשבא לביתו ורואהו בעין אז הוא התגלות עיקר השמחה, והוא ג\"כ דייקא מצד הריחוק שכשהוא בביתו והאוצר תמיד למראה עיניו אין זה שמחה כלל, רק דייקא מצד הריחוק וכשרואהו אזי אז נק' בשם עונג, כי עונג הוא מקרוב ושמחה הוא מרחוק, ועיקר השמחה הוא בבחי' חיצוני' לגמרי, דהיינו כשאוחז המעות ומונה אותם, וזהו הנק' שמחה שלמעלה מעונג שהעונג מורגש, כי יש ב' בחי' שמחה כנ\"ל. או כמו מארז\"ל גבי ר' אבהו שמצא תוספתא חדתא ונהרין אנפוהי שהשמחה והעונג הוא"],[1900740428,"מהמצאת דבר חדש, והנה השמחה שאח\"כ שמלובשת בבחי' חיצוני' דהיינו שמחמת גודל השמחה יכול להשפיל עצמו לדבר דברים נמוכים כמו דברים בטלים שם הוא עיקר התגלות התענוג.\n<b>ועפי\"ז</b> יובן ענין סוכה ולולב, שמיו\"כ עד סוכות ה' ימים נמשכים ה\"ס בבחי' מקיפים. וענין לולב הוא להמשיך ממקיף לגילוי בבחי' חיצוני', כי לולב הוא אותיות לו לב, ויש בזה ב' פי', הא' שהוא למעלה מלב והב' שהוא ההמשכה ללב להיות לבי ובשרי ירננו אל אל חי, שגם הבל הלב הגשמי שם דייקא יהי' ירננו אל אל חי בחי' גילוי הבל פנימאה הנ\"ל. וטעם הירידה והמשכה זו מפני שהעלי' דיוכ\"פ היתה גדולה כ\"כ כי ידוע שעומק תחת הוא לפי ערך עומק רום, שמפני שאא\"ס למעלה עד אין קץ לכן הוא למטה עד אין תכלית, כי אין לו שיעור למעלה ואין לו שיעור למטה, לכן ההמשכה היא למטה כ\"כ בבחי' חיצוני', ולכן נק' סוכות בחי' חיצוני' בינה. ועוד שהרי ענין סוכות הוא ההמשכה לנשמות שבגופים, וכל מה שנשמה שבגוף משגת ומתפעלת גם על אופן היותר טוב מ\"מ מאחר שהנשמה מלובשת בגוף אין זה ערך כלל לכמו שהיתה הנשמה בשרשה למעלה ונק' בשם חיצוני' אך טעם הירידה הוא מפני עוצם העלי' כנ\"ל.\n<b>ובזה</b> יובן טעם ענין ע' פרי החג שמקבלים גם הע' שרים יניקה, והוא כמ\"ש הללו את ה' כל גוים שבחוהו כל האומים כי גבר עלינו חסדו, דלכאורה אינו מובן שמפני שגבר עלינו חסדו לכן שבחוהו כל האומים, אלא הטעם הוא שמחמת ההתגברות חסדים עלינו לכן מקבלים גם הע' שרים יניקה ממותרות ופסולת השפע וכ\"ז הוא ע\"י עלי' דיוכ\"פ שמצד הריחוק דייקא והוא כמשל בן יחיד שנתרחק מאביו זמן כביר ואח\"כ בבואו אזי השמחה של אביו גדולה עד מאד ועושה סעודה גדולה ורוצה שגם שונאיו יהנו ממנו נמצא שיש לשונאים ג\"כ מקום. כמו\"כ יובן שמפני שגבר עלינו חסדו לכן מקבלים הע' שרים יניקה מבחי' חיצוני' כי לישראל נשפע בחי' הפנימי' כי גם מה שנשפע להם פרנסה גשמיות בזה העולם השפל הפנימי' הוא לישראל, אין מזל לישראל"],[1900740429,"ואוה\"ע מקבלים בחי' מותרות השפע כי ישראל הם הפנימי' בכל מקום, כמו גם בג\"ע העליון וג\"ע התחתון הם הפנימי' לגבי המלאכים דכתיב וצבא השמים לך משתחוים בחי' ביטול חיצוני', משא\"כ נש\"י נהנין מזיו השכינה בחי' פנימי' כו'. וזהו מ\"ש מן המצר קראתי י\"ה ענני במרחב י\"ה, שמפני שמן המצר קראתי י\"ה ביוכ\"פ ממעמקים קראתיך מצד הריחוק, לכן ענני במרחב י\"ה בסוכות. ועצרת הוא ענין קליטה שנקלט ונתקבל בחי' אלקות על כל השנה בכל נפש מישראל להיות מכל מלמדי השכלתי כו' וד\"ל."],[1900740430,"<h3>ה' לי בעוזרי</h3>\n<b>שמע\"צ תקע\"ח לפ\"ק</b>\n<b>ה'</b> לי בעוזרי ואני אראה בשונאי, וצ\"ל ענין בעוזרי לשון רבים דמשמע שיש הרבה עוזרים, וגם להבין ענין הוי' לי בעוזרי, וכן בלשון רז\"ל הבא לטהר מסייעין אותו לשון רבים, וגם להבין ענין לטהר דמשמע זולתו ולא כתיב ליטהר דמשמע לעצמו. להבין כ\"ז צריך להקדים מ\"ש למען דעת כל עמי הארץ כי הוי' הוא האלקים, דפסוק זה נאמר על שמע\"צ. ולכאורה אינו מובן שמהו דייקא בשמע\"צ היחוד הוי' ואלקים והלא בכל יום ויום יש יחוד הוי' ואלקים כמ\"ש וידעת היום והשבות אל לבבך כי הוי' הוא האלקים, וכתיב אתה הראת לדעת כי הוי' הוא האלקים, וכתיב שמע ישראל הוי' אלקינו כו' וזהו תכלית כל התומ\"צ שהוא לשם יחוד קוב\"ה ושכינתי' שהוא הוי' ואלקים בחי' סוכ\"ע וממכ\"ע כי קוב\"ה נק' מה שהוא קדוש ומובדל ושכינתי' הוא מה שהוא שוכן בתחתונים. וזה כל האדם לדעת כי הוי' כו', ופי' דעת אינו לשון ידיעה אלא הרגשה כידוע. והענין הוא שצריך להתבונן בב' בחי' אלו, בחי' אלקים הוא מה שהוא מחי' את כולם כח הפועל בתוך הנפעל כמשל הנפש שמחי' את הגוף שמלובשת בתוך הגוף בכל אבר ואבר בפרט, וכתי' ואהבת את הוי' כו' שצריך להתבונן ולהעמיק בזה איך שהוא סוכ\"ע כמ\"ש המלך המרומם והמתנשא מימות עולם עד שיקבע בלב ויתפעל בבחי' אהבה כמ\"ש בכל לבבך ופי' בכל לבבך בתוך לבבך, דלא כמו אהבה של איש לחבירו שהאהבה היא חוץ ממנו (הנק' פון זיך כו'), אלא שיכנס האהבה בתוך לבבו בבחי' או\"פ כו'. ובחי' זו נק' בשם יחוד הוי' ואלקים דהיינו מה שהנשמה בתוך הגוף ומתפעל' מבחי' הוי' זהו יחוד הוי' ואלקים כו' וד\"ל. וא\"כ מהו זה שאמר בשמע\"צ דייקא למען דעת כל עמי הארץ כי הוי' הוא האלקים. אך ההפרש הוא בעמי הארץ לבד, שבכל השנה היחוד הוא רק ליחידי סגולה לבני ישראל עם קרובו שהוא"],[1900740431,"לנשמות בלבד, שבחי' דעת והרגשה הוי' ואלקים אינו רק מצד הנשמה, אבל בשמע\"צ הוא למען דעת כל עמי הארץ כו' שגם הנפש הבהמי' שכתי' הן בעון חוללתי ובחטא יחמתני אמי גם היא תדע ותכיר בהכרה גמורה שהוי' הוא האלקים, ובזה הוא עיקר ההפרש דיחוד הוי' ואלקים של כל השנה ובין שמע\"צ, שבשמע\"צ היחוד הוא פתוח וגלוי לעין כל גם לפני ע\"ה.\n<b>ולביאור</b> הענין נקדים להבין מ\"ש רני עקרה לא ילדה, שכנס\"י נק' בשם עקרה שפולטת הטפה, וכתיב כי חלה גם ילדה ציון את בניה שלע\"ל יהי' בחי' לידה, וצ\"ל שזהו כמו הפלא שבחי' עקרה תלד מאחר שפלטה הטפה ולא נקלטה מאין יהי' ההולדה. והנה להבין זה בעבודת ה' ענין עקרה מהו, הענין הוא שידוע שהקב\"ה נק' בשם חתן חות דרגא וכנס\"י נק' בשם כלה. והנה מצד המשפיע אין מניעה כלל שתמיד משפיע ונק' בשם אור זרוע אך כנס\"י נק' עקרה שאינה קולטת בחי' השפעת גילוי אלקות. ולכאורה אפשר לפרש שמה שנק' בשם עקרה שאינה קולטת הוא מפני שבשעת התפלה שאז מתבונן בבחי' הוי' ואלקים ונתפעל ואז רחוק ממנו בתכלית תאוות עוה\"ז ואינו יכול לחטוא אבל אחר התפלה יכול ליפול בהבלי עוה\"ז להתאוות תאוה ולא נשאר בו רשימו על כל היום להיות סו\"מ וע\"ט בפו\"מ, ובחי' זו נק' בשם עקרה כי בעקרה יש ג\"כ יחוד כמו אברהם ושרה שהיו עקרות ומ\"מ הי' ביניהם יחוד, והיחוד הוא יחוד דקדושה, אבל היחוד אינו רק לפי שעה ואינה נקלטת להיות נעשה מזה הולדה לאחר זמן. או כמו ענר אשכול וממרא שאברהם גייר אותם עד שקבע בחי' אלקות בנפשם שהי' להם מס\"נ בתכלית לה' אחד וכמ\"ש באברהם ויקרא לו אל עולם שהמשיך בחי' אל לעולם דהיינו שלא כמו שנראה העולם ליש אלא ואתה מחי' את כולם כו', אבל לא היו תולדות מענר אשכול וממרא כמו מאבות שאברהם הוליד את יצחק וכו' עד שנולדו י\"ב שבטים ואח\"כ נתהוו לע' נפש עד שנעשו ת\"ר אלף ועד עקבי משיחא לא נפסק יהדותם מבנ\"י הגם שיש בכל דור ודור שחוטאים מ\"מ עצם יהדותם אינו נפסק"],[1900740432,"וזהו ירושה מאבות כמ\"ש מה יפה ירושתינו כו', אבל בענר אשכול וממרא אינו נקלט בחי' אלקות להיות נשאר ירושה גם לבניהם אחריהם. ועפ\"י דוגמא זו יובן גם כאן שנק' כנ\"י בשם עקרה מפני שבשעת התפלה לבד הוא היחוד הוי' ואלקים אבל אינו נשאר על כל היום להיות נעשה מזה תולדה תולדותיהן של צדיקים מאי ניהו מעשים טובים כו'. אבל באמת אנו אומרים והאר עינינו בתורתך ודבק לבנו במצותיך שמבקשים שיוקלט על כל היום, ובאמת נשאר רשימו על כל היום ג\"כ שמקיימים מצות מצד קבלת עול והוא הרשימו שנשאר לו מן ההתבוננות דתפלה.\n<b>אך</b> הטעם שנק' בשם עקרה מפני שכל היחודים שנעשי' ע\"י תומ\"צ אינם נמשכים בגילוי למטה, כמו ע\"י לימוד התורה שידוע דאורייתא מחכמה נפקת והי' צריך למשך בו איזה תוס' אור במוח החכמה שלו, ומצות הצדקה הוא חסד דרועא ימינא, ואנו רואים שגם בעשות האדם איזה מצות אינו משתנה ממהותו הראשון להיות פועלת בו המצוה איזה שינוי למעליותא, והוא מטעם הנ\"ל שהיחוד הוא למעלה. כי הנה ידוע שאא\"ס הוא פשוט בתכלית הפשיטות וע\"י לימוד התורה ממשיך אא\"ס להיות נק' בשם חכים למעלה, וע\"י מצות הצדקה ממשיך אא\"ס בבחי' חסד כו', והגם שכתיב אלה המצות אשר יעשה אותם האדם וחי בהם, חי זה קאי על לעתיד שלעתיד יהי' ההתגלות למטה כמו למעלה ממש, אבל עכשיו אינו נמשך בגילוי למטה, ואפי' ההמשכה שנמשכת ע\"י מצות בג\"ע אינו כמו הגילוי דלעתיד, וכעת עיקר הגילוי הוא למעלה וכמ\"ש וירא אלקים את האור כי טוב, כי טוב לגנוז האור בכלים מכלים שונים, כי כל המצות הם כלים להשראת אא\"ס כידוע שהמצות המה פנימי' רצונותיו אבל כעת הוא בהעלם כמשל חיות הנפש בתוך הגוף בכל אבר ואבר שהחיות הוא גנוז ואינו נראה, או כמשל המים שבתוך הכלי שהכלי מכסה על המים ואינם נראים כו'. והנה מטעם זה נק' כנס\"י בשם עקרה שכל המשכות אלקות שע\"י תומ\"צ שלהם אינו נמשך ובא בגילוי למטה בתוך תוכם, אלא הוא רק להוסיף אורות באצי' כו'. והסבה לזה הוא מצד חומר הגוף ונפש הבהמית המסתירים על אור אלקי. אבל לעתיד כתיב כי חלה גם ילדה ציון את בניה,"],[1900740433,"שיהי' בחי' לידה דהיינו שיהי' התגלות למטה כמו למעלה כנ\"ל כמ\"ש ונגלה כבוד הוי', ולכן יבוטלו טורפי' ומזיקים כמ\"ש וגר זאב עם כבש ופרה ודוב תרעינה מפני שלעתיד לא יהי' רע כלל כמ\"ש ואת רוח הטומאה אעביר מן הארץ כו'.\n<b>והנה</b> הארה אפס קצהו מעין דלעתיד מאיר גם עכשיו בשמע\"צ, דהיינו שנפש הבהמית אינו מסתיר כלל כמו הדוגמא דלעתיד, וע\"ז כתיב למען דעת כל עמי הארץ כי הוי' הוא האלקים, שגם נפש הבהמית תדע שהוי' כו'. ובזה הוא ההפרש בין יחוד הוי' אלקים של כל השנה להיחוד דשמע\"צ.\n<b>וביאור</b> הענין הוא כי הנה סוכות נק' זמן שמחתינו, וצ\"ל והלא בכל השנה ג\"כ כתיב עבדו את ה' בשמחה. וכתיב תחת אשר לא עבדת את ה' בשמחה כו'. אך הענין הוא כי השמחה של כל השנה הוא שמחה פרטי'. כי הנה כתיב אם הבנים שמחה דהיינו ע\"י התבוננות אלקות נתהוה מזה בחי' שמחה, הנה השמחה הוא בדבר פרטי ולפי ערך . .תו ההתבוננות ככה הוא השמחה, וגם התענוג מזה כי השמחה הוא מגלה התענוג ג\"כ הוא תענוג פרטי. וכמו\"כ השמחה של מצוה הוא מפרט המצוה ונמצא שהמצוה היא העיקר והשמחה הוא טפל להמצוה כמ\"ש עבדו את ה' בשמחה שהעבודה תהי' בשמחה אבל העיקר הוא העבודה, ובאתעדל\"ת אתדל\"ע מתעורר בחי' שמחה עליונה כמ\"ש ישמח ה' במעשיו ג\"כ שמחה פרטי' לבד, אבל השמחה דשמע\"צ הוא שמחה כללי' כמ\"ש וישמחו בך ישראל מקדשי שמך, שבכל השנה מקדשי שמך לבד שיש קידוש ה' וטהרת ה' וקידוש ה' הוא אשר קדשנו במצותיו שהוא יחוד קוב\"ה ושכינתי' (ובאמת הא בהא תליא, שמפני מה ישמחו בך בשמע\"צ מפני שמקדשי שמך בכל השנה כו') ובשמע\"צ וישמחו בך, שהשמחה היא בעצמותו ממש והוא הנק' שמחת כל הנפש בחי' יחידה ובאתעדל\"ת אתעדל\"ע להיות ישמח ה' במעשיו"],[1900740434,"כו' שמחה עצמיות ג\"כ, והתענוג הוא תענוג כללי. ומפני שהשמחה הוא שמחה כללי לכן למען דעת כל עמי הארץ ג\"כ וכמו שנראה שבעת שמחת האדם אזי הוא מופשט אז מתאוות הגוף, שבעת שהאדם בשמחה נהפך טבע הגוף שלו שמקמצן יעשה פזרן. וכמו\"כ יובן בענין הנ\"ל שמפני שוישמחו בך ממש לכן גם למען דעת עמי הארץ שהוא הנפש הטבעי' כו', וכידוע שחצי המקיף מזכך הכלי מבחוץ וחצי המקיף מזכך הכלי מבפנים דהיינו שהשמחה כללי' של בחי' יחידה מזכך הכלי מבפנים להיות למען דעת כל עמי הארץ כו' וחצי המקיף שהוא השמחה העליונה מזכך הכלי מבחוץ כמ\"ש לא תאונה אליך רעה ונגע לא יקרב באהליך שהוא השמירה מבחוץ כו' וד\"ל.\n<b>ועתה</b> יובן מארז\"ל הבא לטהר מסייעין אותו וענין פי' הפסוק הוי' לי בעוזרי, כי הנה לטהר הוא לזולתו פי' בחי' שם ומל' שיהי' גילוי בעולם. כי יש ב' מיני טהרה כי פי' טהרה הוא דבר הבהיר כמו טהר יומא שכשהשמים מכוסים בעבים ונתפזרו העבים נק' בשם טהר יומא או טהר גברא. ויש טהרה הבא מכלל טומאה כמו אדם המטהר עצמו במקוה שמתחילה הוא טמא וע\"י טבילתו במקוה נעשה טהור, נמצא שטהרה זו היא מכלל טומאה וכמו שאנו מבקשים וטהר לבינו לעבדך באמת שהוא טהרת הלב מכל מחשבה רעה, וע\"ז אמרז\"ל טהרה מביאה לידי קדושה, שכשמטהר מחשבותיו וכו' נעשה כלי שיוכל להתקבל בתוכו בחי' קדושה עליונה. ויש טהרה הנק' טהירו בעצם דהיינו ע\"י התעוררות קדושה נעשה ממילא טהרה, ובחי' קדושה זו נק' בשם טהרה בעצם. וזהו הבא לטהר כו' דקאי על שמע\"צ שאז הוא התעוררות בחי' טהירו בעצם כנ\"ל, מסייעין אותו ר\"ל שהמצות בעצמן מסייעין, כי הלא המצות המה פנימי' רצונותיו והוא ורצונו אחד רק שבכל השנה אינם נמשכים בגילוי למטה מפני הסתר הגוף ונפש הבהמית אבל בשמע\"צ שהוא לדעת כל עמי הארץ כו' מפני שמחה עצמיו' הנ\"ל כנ\"ל אזי המצות בעצמן מסייעין. וזהו הוי' לי בעוזרי, שבעוזרי הם מצות כו' והוי' לי בעוזרי קאי על בחי' עצמיות הנ\"ל. ועיקר מארז\"ל הבא לטהר וגם פי' הפסוק הוי' לי כו' קאי על ואני אראה"],[1900740435,"בשונאי. הענין הוא כי ביוהכ\"פ ע\"י הוידוים שהוא ענין ליטהר לעצמו ומשפילי' א\"ע בתכלית השפלות באמרנו אשמנו תעבנו כו' עי\"ז נתעורר בחי' טה\"ע כעצם השמים לטוהר בחי' פנימי' בינה כמאמר תבא האם כו' צואת בנה כו' וכמ\"ש אם יהיו חטאיכם כשנים כשלג ילבינו כו' שזדונות נעשו כזכיות קטיגור נעשה סניגור. אך שביוכ\"פ הוא למעלה עדיין כמ\"ש לפני הוי' תטהרו ובשמע\"צ נמשך למטה ג\"כ. וזהו ואני אראה בשונאי שעיקר הנקמה בשונא אינו כשיש לו מפלה אלא כשמוכרח להפך בזכותו ג\"כ. ו]ז[הו ואני אראה כי קטיגור נעשה סניגור וכו' וד\"ל."],[1900740436,"<h3>הטעם שמעמידין החתן</h3>\n<b>תקע\"ח</b>\n<b>הטעם</b> שמעמידין החתן תחת החופה ביום חתונתו, כי החופה הוא בחי' מקיף וכל מה שיעסוק בעבודת ה' עד ימי חייו נמשך לו ממקיף בעת הזאת ולכן צריך לקשר מחשבתו בה' אז שע\"י כן ימשיך ממקיף אז כו' וד\"ל."],[1900420011,"<h3>שמח תשמח כו' שהקב\"ה נק' חתן</h3>\n<b></b><b>ב\"ה. ט\"ו מנחם אב ה'תקפ\"ו (חתונת בתי שרה תי' ונכדתי תי')</b>\n<b>שמח</b> תשמח<sup data-n=\"1\">1</sup> ריעים האהובים כשמחך יצירך בג\"ע מקדם כו'. הנה ידוע שהקדב\"ה נק' חתן וכנ\"י נק' כלה כמובן בשה\"ש<sup data-n=\"2\">2</sup>, וכל ענין זה בבחי' חו\"כ זהו כמו משפיע ומקבל שאהבתם נפלאה ביותר והמקבל תשוקתו תמיד אל המשפיע כמו ואל אישך תשוקתך וכן המשפיע אל המקבל כמ\"ש ע\"כ יעזוב איש<sup data-n=\"3\">3</sup> כו' ודבק באשתו, וכך הוא למעלה שהקדב\"ה נק' איש וכנ\"י נק' אשה ותשוקת כנ\"י להקדב\"ה בתמידות בהתקשרות עצמי' ופנימי' כמו צמא' לך נפשי כו' ולכך נק' כל\"ה ל' כלת\"ה נפשי<sup data-n=\"4\">4</sup> כידוע, וכן אהבת ה' לכנ\"י תמיד כמ\"ש אה\"ע אהבתיך<sup data-n=\"5\">5</sup> כו', וזהו שנק' למעלה יחוד קודב\"ה ושכינתי' וידוע דפי' שכינה למעלה הוא בחי' גילוי אור האלקי השוכן ומתלבש בתוך כל עלמין להחיותם בפ\"מ מאין ליש בתמידו' שזהו כח ואור וחיו' האלקי שנמשך להיות מזה חיות תמידי' בכללו' לכל העולמו' והברואים כדמיון חיו' הנפש המתפשט ומתלבש באברי הגוף או כמשל אותיו' הדיבור שבאי' בגילוי, ויהי' איך שיהי' הרי האור האלקי הזה מתלבש בתוך כל עלמין ונק' בחי' ממלא כל עלמין כידוע.\n<b>(ובאמת</b> לכאורה אין זה מובן דהאיך אפשר לומר דאין אור האלקי הזה רק בתו\"ך כל בריא' דמשמע בתוכ\"ו ופנימיותו לבד כמו חיות הנפש בגוף שיש לגוף מציאו' בפ\"ע בתחלה טרם שנכנס בו האור וחיות הרוחני ואיך אפשר לומר זה בעולמו' וברואי' שא\"א שיש להם מציאו' בגופם וחומרם בלא חיו' אלקי עד שנאמר שאור האלקי מתלבש בתוך תוכם ופנימיותם דוקא",[["1","1","<b>שמח תשמח</b>: כמה מעניני המאמר מיוסדים על ד\"ה שמח תשמח בס' ”מאמרי אדה\"ז על מארז\"ל\" ע' תצב ואילך. להלן ד\"ה שמח תשמח (השלישי) הוא תוכן מאמר זה בקיצור יותר.\nכמה מעניני המאמר, נמצאים ג\"כ בהרחב הביאור בד\"ה שמח תשמח בסה\"מ תרנ\"ז ע' קעג ואילך [ונסמן להלן בתחילת כמה סעיפים, המקבילות אליהם בסה\"מ תרנ\"ז].\nראה עוד ע\"ד המאמר, להלן בהוספות ברשימת הכתבי-יד."],["2","2","<b>שהקדב\"ה נק' חתן. . כמובן בשה\"ש</b>: ראה גם להלן בתחילת ד\"ה ”להבין שבברכה ראשונה\". וש\"נ."],["3","3","<b>ואל אישך תשוקתך. . ע\"כ יעזוב איש</b>: בראשית ג, ז. ב, כד."],["4","4","<b>צמא' לך נפשי. . כלת\"ה נפשי</b>: תהלים סג, ב. פד, ג."],["5","5","<b>אה\"ע אהבתיך</b>: ירמי' לא, ב."]]],[1900420012,"ומהיכן נמצא מציאו' החומר שלהם הלא גם הוא נתהוה מאור וחיו' האלקי שאין לך דבר חוץ ממנו כי אין עוד כו'. אך הענין הוא כידוע שכל התהוות החומר והצורה שיש בכל בריא' ובריאה יש שרש ומקור להתהוו' הצורה בפ\"ע ושרש ומקור להתהוו' החומר בפ\"ע, כמו מאותיו' הדיבור נמשך שרש להתהוו' הצורה הרוחניו' שבבריא' מבחי' רוחניו' וצורה של הדיבור ושרש התהוו' החומר נמשך מהחומר של הדיבור שהוא ההבל כידוע, וכן בדמיון חיו' הנפש בגוף אינו כמו שאנו מדמין שהחיו' נכנס לגוף שכבר ישנו במציאו' (כמו ויפח באפיו נ\"ח<sup data-n=\"6\">6</sup> כו') אלא גם החומר מתהוה עם הצורה יחד כמו הכלי שנעשה מיד הפועל האומן שעושה הגולם והצורה שלו כו' (וכמו במע\"ב שיצאו בצביונן ובקומתן<sup data-n=\"7\">7</sup> כאריה ושור שיצאו מן הארץ ע\"י מא' תוצא הארץ נפש חיה כו', וכך גם המלאכי' שנק' פני ארי' ופני שור כו' נבראו בחומר וצורה שלהם יחד כא' ממש), וכן במא' יהי רקיע<sup data-n=\"8\">8</sup> נתהוה הצומח וחי כא' כנפש הגלגל עם חומר הגלגל שסובב כא', וכידוע דאין החומר נבדל בערך פחו' כ\"כ מן הצורה בכל מלאך ובריא' עליונה כרקיע וכו\"מ משא\"כ בנפש אדם בגופו, ועכ\"ז חומר האדם הוכן בתחלה ביצירתו בבטן ואח\"כ נכנס בו הצורה (כמ\"ש בע\"ח דבנין הכלים קדם לאורות<sup data-n=\"9\">9</sup> כו'), וכך הוא גם בשאר הברואי' שחומר שלהם קדם לצורה אף שנבראו כא' כנ\"ל, ואע\"פ שבגילוי האור הצורה קדמה לחומר שהרי א' בע\"ח שמן התעבות האור עצמו נעשה הכלי<sup data-n=\"10\">10</sup> והחומר, אבל בבחי' ההעלם (שהוא האו\"מ) שרש התהוות החומר קדם לשרש הצורה, וכמ\"ש במ\"א בבחי' אי\"ן וי\"ש רוחניו' וגשמיות ששרש היש בבחי' מקיף דסובב כו' ושרש האי\"ן בבחי' ממלא כו'. ואמנם באמת הרי א' כי ממך הכל<sup data-n=\"11\">11</sup> כו' ודאי גם החומר מתהוה עם הצורה יחד כמו בבחי' פעולה ועשי' גשמי' וכאשר אומר ואתה מחי' את כולם<sup data-n=\"12\">12</sup> הכונה הוא גם אחר התהוו' צו\"ח של כל הברואי' עכ\"ז אין להם מציאו' כלל בלתי אור וחיו' האלקי שנק' ממלא כ\"ע ששופע בתוך תוכם דוקא כנ\"ל וד\"ל) (וכמ\"ש אד' ב\"ם<sup data-n=\"13\">13</sup> כו' ב\"ם ממש דמשמע בתוך תוכם דוקא דהיינו גם אחר שכבר נבראו במציאו' הצו\"ח ועכ\"ז א\"א להם להתקיים בלא אור וחיו' האלקי' שמאיר בתוך",[["6","6","<b>ויפח באפיו נ\"ח</b>: בראשית ב, ז."],["7","7","<b>במע\"ב שיצאו בצביונן ובקומתן</b>: ר\"ה יא, א. חולין ס, א."],["8","8","<b>תוצא הארץ. . יהי רקיע</b>: בראשית א, כד. א, ו."],["9","9","<b>כמ\"ש בע\"ח דבנין הכלים קדם לאורות</b>: ראה ס' מאמרי אדהאמ\"צ: שמות ח\"ב ע' תח. ויקרא ח\"ב ע' תתנט. במדבר ח\"א ע' רצד. ח\"ב ע' תכב. תר. דברים ח\"ג ע' תתיח. ח\"ד ע' א'שעו. [ובהנסמן בהמ\"מ במקומות אלו]."],["10","10","<b>בע\"ח שמן התעבות האור עצמו נעשה הכלי</b>: ראה ע\"ח שער העקודים פ\"ג ואילך. ס' מאמרי אדהאמ\"צ נ\"ך ע' קלד. וש\"נ."],["11","11","<b>במ\"א בבחי' אין ויש. . כי ממך הכל</b>: ראה בהנסמן לעיל פיסקא ”כמ\"ש בע\"ח\". דה\"א כט, יד."],["12","12","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["13","13","<b>אד' ב\"ם</b>: תהלים סח, יח."]]],[1900420013,"תוכם (וכמ\"ש בזוהר ע\"פ שרפי' עומדי'<sup data-n=\"14\">14</sup> ממעל לו ממעל לשכינ' לפי שכח האלקי הוא בתוך תוכם כחיו' הנפש בתוך הגוף וכן ענין חי העולמי' כו' (ומה שא' דממלא כל שמהן כו' ואי אנת תסתלק מנייהו אשתארו כגופ\"א כו' מבואר בסידור<sup data-n=\"15\">15</sup> ע\"ש) (ובמ\"א מבואר דכח האלקי' המחי' לכל העולמו' זהו מבחי' מקיף דהתנשאו' דבחי' מל' כמו מלכותך מלכות כל עולמים<sup data-n=\"16\">16</sup> וכן ואימת\"ך עליהם<sup data-n=\"17\">17</sup> כו' ומזה הם חיים וקיימי' כו', זהו בחי' סובב שבממלא עצמו כמ\"ש במ\"א). וזהו שנק' כח הפועל בנפעל בתוך הנפעל מאיר בו בתמידות ועכ\"ז אין שינוי כלל וכלל בין קודם הבריא' לאחר הבריא' כמו שאומרים אתה הוא קודם שנברא העולם כו' לפי שאין זה רק האר' דהאר' כו'.\n[ב] <b>אבל</b> הנה בחי' סובב כ\"ע הוא בחי' אור המקיף וסובב לכל ההמשכה והשפעה האלקי' שנמשך בתוך כ\"ע בבחי' כח הפועל בנפעל ממש הנ\"ל להיותו נבדל ומרומם בערך מהיו' בחי' גילוי אור ושפע ממש, כי אין גילוי אור ושפע רק בבחי' חיצוניו' האור הבא בהגבלה, כמו באותיות המגבילי' ומתארים לאור השכל והמח' שבהעלם וכמו גילוי הארת אור וזיו המאיר מן השמש וכן גילוי אור וחיו' הנפש שמתפשט להחיות דבר מה (כגילוי התנועה מן הכח המניע וככח הפועל בפעולה), שכל זה אינו רק גילוי העצם ואין לו ערך לגבי מוה\"ע<sup data-n=\"18\">18</sup> שממנו מתגלה ומתפשט (וכמו המראה והגוון או כמו שמגלה בציור ותמונה לבד כידוע), וכמו המשפיע שכל לתלמיד שלא יוכל להשפיע רק מבחי' היותר אחרון ומצומצם שאינו רק כפי ערך קבלת המקבל לבד שנמצא מה שא\"א לבא בכלי המקבל נשאר בבחי' מקיף וסובב עליו מכל צד וכה\"ג. ולפי שלא יוכל לבא לידי גילוי אור ושפע להיו' מקור לעולמו' נשאר בבחי' מקיף וסובב על גילוי אור ושפע המצומצם הנק' מקור לעולמו', וז\"ש כי עמך מקור חיים<sup data-n=\"19\">19</sup> כו' דבחי' ממלא כ\"ע שנק' מקור כל החיים עמ\"ך טפל כו'.\n<b>אך</b> א\"כ למה נק' גם בשם סובב כ\"ע מאחר שנבדל הוא בערך לגמרי שלא יוכל לבא בבחי' גילוי אור ושפע כלל כנ\"ל, הענין הוא דאין הכונה בפי' סובב זה רק מה שסובב מבחוץ ואינו נכנס בגילוי בתוך כ\"ע ממש, אבל אדרבא הרי הוא עיקר ומקור לכל מה שבא אח\"כ בגילוי אור ושפע האלקי'",[["14","14","<b>בזוהר ע\"פ שרפי' עומדי'</b>: ישעי' ו, ב. ראה זח\"ג מז, א. עט, ב. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תה. דברים ח\"ג ע' תתקמח. וש\"נ."],["15","15","<b>דממלא כל שמהן. . מבואר בסידור</b>: ראה סידור קסד, ב ואילך."],["16","16","<b>מלכותך מל' כ\"ע</b>: תהלים קמה, יג."],["17","17","<b>ואימתך עליהם</b>: ע\"פ פיוט אשר אימתך (מוסף ליוהכ\"פ). והובא גם בס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תתצ. ובס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשמא. במדבר ח\"ב ע' תז וע' תרכ. ח\"ג ע' א'מא. דברים ח\"ב ע' תפח. ח\"ג ע' א'ב. להלן ריש אות ד."],["18","18","<b>מוה\"ע</b>: מהות ועצמות. וכן רגיל ר\"ת של תיבות אלו בכ\"מ בגוכי\"ק אדהאמ\"צ — הוא\"ו לפני הה\"א."],["19","19","<b>כי עמך מקור חיים</b>: תהלים לו, יו\"ד."]]],[1900420014,"הנק' ממלא כ\"ע כי הרי הוא בחי' מקור עצמי ופשוט שממנו נמצא מציאו' האור והשפע האלקי' בעולמו' בבחי' ממלא כ\"ע כו'. ויובן זה במשלי' הנ\"ל כמו בגילוי אור וזיו השמש דודאי מה שמאיר אור זהו לפי שהשמש עצמו עצם ספירי ומבהיק ע\"כ יאיר אור זה, הרי בחי' האור וזיו המאיר לארץ אע\"פ שכלא חשיב לגבי מאור השמש עצמו מ\"מ מן הארת השמש מאיר הארה זאת והוא עיקר המקור למציאו' אור וזיו הזה, וכך הוא בגילוי אור וחיו' הנפש בגוף אעפ\"י שאינו רק בחי' גילוי העצם דנפש שאינו בגדר וסוג זה להיו' לחיו' ממש כו', מ\"מ הרי דוקא מעצם הנפש להיותו בחי' נפש חי\"ה בעצם ע\"כ יתפשט ממנו גילוי אור להחיות גם הגוף ובהסתלק הנפש יסתלק ממילא גילוי אורה שבגוף, וז\"ש אך בצלם<sup data-n=\"20\">20</sup> דמקיף דעצם הנפש יתהל\"ך איש באו\"פ בנר\"נ כו', וכמ\"כ במשלי' האחרי' כאותיו' הדיבור שבודאי מקבלי' תמיד מאותיו' המח' והשכל שאינם רק בחי' גילוי ההעלם ואין להם קיום בלא מקור העצמי' שלהם שהוא המח' והשכל (וכאור הנגלה מן המאור כנ\"ל) (ואע\"פ שנשאר במח' מה שלא יוכל להביא בגילוי הדיבור כלל ומקיף על הדיבור, מ\"מ הרי מן המח' נמשך לדיבור בכל רגע ורגע, והיינו מבחי' העלם המח' שנק' מקיף וסובב דוקא שאם אין או\"מ אין או\"פ. ויובן זה כמו עד\"מ במח' הכללי' שיחשוב בדרך כלל כמו לבנות בנין וכה\"ג שנכלל במח' זו כל הפרטים שמתגלה אח\"כ באותיו' הדיבור כאשר מצוה לבנות בפ\"מ וכל פרט ופרט של הדיבור והמעשה מקבלי' רק מכח המח' כללי' שהי' בהעלם בעצמותו ויצא לידי גילוי בחלקים של אותיו' הדיבור, ואע\"פ שהמח' הכללי' נשאר בהעלם ומקיף וסובב לכל הפרטי' שבאו בדיבור, מ\"מ עיקר המקור השופע לאותיו' הדבור בכל פרט הוא המח' הכללי' שמשם נמשך מח' בדיבור (ואע\"פ שגם זה אינו רק מדיבור שבמח' שהוא מה שנתצמצם במח' הכללי' לבא לגילוי בדיבור עכ\"ז מכלל נמשך אל הפרט ואם אין כלל אין פרט (וכמ\"ש בזוהר בענין קול ודיבור<sup data-n=\"21\">21</sup> שזהו ג\"כ בחי' כלל ופרט ופרט אצטריך לכלל כו').\n[ג] <b>וככל</b> דוגמא זו יובן ג\"כ למעלה בענין סובב כ\"ע וממלא כ\"ע, שבחי' ממלא כ\"ע הנ\"ל שהוא כח האלקי המתלבש בתוך כ\"ע בבחי' או\"פ מקבל תמיד מבחי' סובב כ\"ע, אע\"פ שהוא בבחי' מקיף וסובב על כל העולמו' ומקיף לכולם בשוה דהיינו מה שלא יוכל לבא משם בבחי' גילוי אור ושפע ממש להחיות העולמו' מאין ליש, מ\"מ מבחי' סובב זה ממנו דוקא נמשך ונמצא מציאו' האור ושפע האלקי' המצומצם בעולמו' דבי\"ע, כמשל אותיו' הדיבור דיו\"ד מאמרות שנמשך מהעלם המח' הכללי' שנק' מא' סתום<sup data-n=\"22\">22</sup> בבחי'",[["20","20","<b>אך בצלם</b>: תהלים לט, ז. וראה מאמרי אדהאמ\"צ דברים ח\"ב ע' תצח ואילך. ובכ\"מ."],["21","21","<b>בזוהר בענין קול ודיבור</b>: ראה זח\"ב ג, א. ס' מאמרי אדהאמ\"צ דברים ח\"ג ע' א'ז. ח\"ד ע' א'תנג."],["22","22","<b>מא' סתום</b>: שבת קד, א. וראה גם ס' מאמרי אדהאמ\"צ שמות ח\"א ע' ריג. במדבר ח\"ג ע' א'פה וע' א'רנה. דברים ח\"א ע' רפד. ח\"ג ע' תשצט. ובהמ\"מ שם."]]],[1900420015,"כלל שכולל כל ההמשכו' אלקו' הפרטי' שבא בגילוי בדיבור העליון ביו\"ד מאמרות ופרטי צרופיהן וכל ו\"א שני' דהוי עלמא בזמן ומקום וכל העליו' וירידו' כו' הכל נסקר בסקירה אחת כללי' טרם שיצא לגילוי, וכאמ' בראשי\"ת ברא בקדמי\"ן<sup data-n=\"23\">23</sup> בהעלם המח' כמו שחושב אדם לבנות בנין בכללותו כנ\"ל, וז\"ש כי אמרת\"י עול\"ם חסד יבנה<sup data-n=\"24\">24</sup> בבחי' חסד כללי עלה ברצונו הפשוט להאציל ולברוא כו' (והוא מה ששיער בעצמו בכח<sup data-n=\"25\">25</sup> ובהעלם המח' הכללי' מה שעתיד להיו' בפועל ובגילוי ברצון וחכ' ומדו' ומודו\"מ כו'). וזהו פי' הפשוט דברוך שאמר במח' כללי' והי' העולם בכלל ואח\"כ יצא מן הכלל אל הפרט בבחי' גילוי או\"פ כנ\"ל שאם אין כלל אין פרט שזהו ענין האו\"פ שמקבל מאו\"מ דוקא אע\"פ שנק' מקיף מלמעלה כו' כי אע\"פ שנק' מקיף וסובב בריחוק על כל העולמו' מ\"מ מקיף וסובב את כולם מראש לסוף בשוה ממש כעיגול שמקיף לקו שעליונו של קו ותחתיתו אחוז וקשור בעיגול הסובבו מלמעלה ולמטה כו'.\n<b>(ואמנם</b> לפ\"ז הרי לא בא מבחי' מקיף דסובב כ\"ע שום שפע ממש בעולמו' רק מרחוק מאיר על הכל בשוה ממש כדמיון מח' הכללי' שנשאר בהעלם ומה שמאיר ממנה בדיבור אין זה רק אפס קצהו כו' כנ\"ל, ובאמת אין הענין כן דודאי מאחר שבחי' סובב זה הוא עיקר ומקור הראשון שממנו נמצא מציאו' האו\"פ דממלא כנ\"ל מוכרח לומר דמקיף דסובב כ\"ע אע\"פ שנק' סובב נמצא הוא בכל העולמו' הנבראי' מאין ליש גם בכל פרט ופרט בכל חלקי ההשתלשלו' דעו\"ע עד גם האחרון המצומצם ביותר כד' יסודות ודצח\"ם הגשמיי' (שהרי נק' או\"ר מקיף וכל אור הוא המאיר ממש רק שהארתו למטה אינו בגילוי רק בהעלם ובשוה אבל בכל פרט ופרט בפ\"ע דוקא (וכמו הארה כללי' מן מח' הכללי' בכל פרט ופרט של הדו\"מ דוקא רק שהוא בהעלם ולא בגילוי ובכל הצירופי' בשוה ממש), שזהו למעלה מה שסובל את הכל ומלובש בהעלם בתוך כל פרט כו', כענין את השמים ואת הארץ (ר\"ת א\"ה ו\"ה<sup data-n=\"26\">26</sup> גי' טו\"ב שהוא בחי' יסוד שנק' כ\"ל כמ\"ש כי כ\"ל בשמי' וארץ דאחיד בשמיא וארע'<sup data-n=\"27\">27</sup> מראש לסוף כא', וזהו פי' אל עליון קונה שמים וארץ בהשווא' א') אני מל\"א, ופי' מל\"א זה היינו כמו בבחי' ממלא כ\"ע שהוא גילוי אור ושפע האלקי' בכל פרט בחיו' הבריא' מאין ליש, כך אני ממש שהוא שם הוי' בחי' סובב כ\"ע הנ\"ל מלא בשמים ובארץ כו' והוא כמ\"ש בזוהר דלית את\"ר פנוי מיני'<sup data-n=\"28\">28</sup> מעצמותו כו',",[["23","23","<b>בראשית ברא בקדמין</b>: בראשית א, א ובתרגום אונקלוס שם."],["24","24","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["25","25","<b>מה ששיער בעצמו בכח</b>: ראה להלן אות י\"א. וש\"נ."],["26","26","<b>את השמים ואת הארץ (ר\"ת א\"ה ו\"ה</b>: ראה זח\"א רנא, א. ס' מאמרי אדהאמ\"צ בראשית ע' רצד. שמות ח\"ב ע' תפז. במדבר ח\"ב ע' שעח וע' תקפד. לעיל ח\"א ע' לח. ובהמ\"מ שם."],["27","27","<b>כי כל בשמי' וארץ דאחיד בשמיא וארע'</b>: דה\"א כט, יא. ראה זח\"א לא, א. לקו\"ת דברים טו, ב־ כג, ד — ובהמ\"מ שם [הוצאת ה'תשד\"מ ואילך]. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשמב. וש\"נ."],["28","28","<b>בזוהר דלית את\"ר פנוי מיני'</b>: ראה תקוני זהר תנ\"ז (צא, ב). שם ת\"ע (קכב, ב). לקו\"ת ויקרא נב, ג."]]],[1900420016,"אבל הוא בהעלם ולא בגילוי ממש שא\"כ הי' חילוק מדרגו' מגעה\"ע לעוה\"ז השפל אלא הוא בהעלם אבל בכל את\"ר ואת\"ר בפרט לא פנוי מיני' כו', וא\"כ הרי בחי' מקיף זה דסובב כ\"ע מרומם ומתנשא מרחוק על כל העולמו' ומקיף לכולם בשוה כנ\"ל וגם הוא מלובש בתוך כל פרט בהעלם וג\"כ בכולם בשוה (ולע\"ל יתגלה מן ההעלם כמ\"ש ונגלה כבוד הוי'<sup data-n=\"29\">29</sup> וראו כל בשר כו'), וכמשל הנהר שמתחלק לחפירות רבות דאע\"פ שיש בכל חפירה מים בפ\"ע כולם מקבלי' מן הנהר (או כהאי בוצינא דאדליק לכל סטר<sup data-n=\"30\">30</sup> ולא נחסר ממנו כלום), וזהו כמו משל חיו' הנפש באיברי הגוף בכל אבר ואבר כפי מזגו דוקא, ועכ\"ז אע\"פ שעצם הנפש ממש מובדל ומושלל מכל בחי' אור וחיו' גלוי הרי מרגיש האדם בנפשו מכל כחו' וחיו' כל אבר ואבר בפרט וגם בכללות כולם כא' מרגיש מראשו לרגלו בשוה, רק שהרגשה זו בהעלם ולא בגילוי החיות וע\"כ הוא בשוה<sup data-n=\"31\">31</sup> בכולם ממוח שבראש עד צפרן הרגל. ומכל זה יובן הנמשל למעלה שכך הוא בבחי' מקיף דבחי' סובב הכללי המקיף (לד' עולמו' דאבי\"ע בשוה) שסובל את כל העולמו' בהשווא' א' ויודע את הכל בידיעה כללי' כנ\"ל ע\"כ הוא נמצא גם בכל פרט עד בחי' צמצום האחרון כמו בד\"י גשמיי' כנ\"ל רק שהוא בהעלם ובכולם בשוה בגעה\"ע כמו מתחת לארץ אין עוד בשוה כו'*).\n<b>וזהו</b> שאנו או' מלך יחיד חי העולמים, פי' חי זהו בחי' סובב כ\"ע שנק' מקור כל החיים העליוני' שבא בבחי' גילוי דממלא כ\"ע, כידוע דבחי' ממלא כ\"ע נק' אלקים חיים בבחי' התפשטו' וגילוי אור וחיו', ופי' ח\"י העולמי' זהו בחי' מקור החיים הכללי שממנו נמצא מציאו' אור ושפע האלקי' דמל' דאצי' בבי\"ע כנ\"ל וד\"ל (וגם בבחי' מל' דאצי' שנק' ממלא כ\"ע שנק' שכינה כנ\"ל יש בזה ג\"כ בחי' מקיף וסובב כמו בחי' סובב הכללי הנ\"ל, והוא ענין מלך מרומם כו' המתנשא מימ\"ע שמקיף בהתנשאו' על כל הברואי' כמו ואימתך עליהם<sup data-n=\"32\">32</sup> לפי שגם בבחי' גילוי דאו\"פ יש מקיף דמל' דאצי', אבל מובן מכל הנ\"ל דגם בחי' ממלא דסובב הכללי דשם הוי' (בחי' מח' הכללי' דהיינו הי' הוה ויהי' כא' כו' כנ\"ל) שזהו מ\"ש את השמי' כו' אני מלא<sup data-n=\"33\">33</sup> דלית את\"ר כו' הוא למעלה הרבה גם מבחי' סובב שבממלא שהוא מקיף דמל', וכמו שאנו או' והקדוש בשמי' ובארץ דאע\"פ שאת השמי' כו' אני מלא מ\"מ זהו בבחי' ההעלם בלבד ושוה ומשוה מראש לסוף כא' כנ\"ל ע\"כ נק' קדוש הוי' גם במל' דאצי' בבריא' כו'",[["29","29","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["30","30","<b>כהאי בוצינא דאדליק לכל סטר</b>: ראה זח\"ג רפח, א. תו\"ח נח סח, ג. ס' מאמרי אדהאמ\"צ שמות ח\"א ע' קסג וע' רפא."],["31","31","<b>בשוה כו'</b>: בכת\"י מעתיק נוסף: שזהו כמו בשמים ממעל ועל הארץ מתחת אין עוד בשוה כו'."],["32","32","<b>ואימתך עליהם</b>: ראה לעיל סוף אות א'. וש\"נ."],["33","33","<b>את השמי' כו' אני מלא</b>: ירמי' כג, כד."]]],[1900420017,"(וזהו שנק' מלך יחי\"ד ח\"י העולמי' וכן מלך מרומם לבדו ממש כמ\"ש אני הוי' לא שניתי כלל כו', משא\"כ בחי' ממלא דבחי' המל' אע\"פ שמתנשא מימ\"ע הרי בזה עצמו דוקא הוא בחי' מקור לחיו' העולמו' בגילוי גמור כמ\"ש מלכותך<sup data-n=\"34\">34</sup> דוקא מלכות כל עולמים כידוע וד\"ל).\n[ד] <b>והנה</b> בחי' סובב כ\"ע הנ\"ל נק' חתן ובחי' ממלא כ\"ע הנ\"ל נק' כלה בחי' מקבל. כי הנה פי' חתן ידוע שזהו ל' חו\"ת דרגא וכמו הוא כחתן<sup data-n=\"35\">35</sup> יוצא כו', כך למעלה בחי' סובב כ\"ע הנ\"ל הרי הוא בא בבחי' צמצום וירידה מן העצמות שלו להיו' ממנו נמשך מקור לגילוי אור ושפע האלקי' המצומצם להחיו' העולמו' כנ\"ל, ולפי שהוא ית' מקור הראשון כמ\"ש כי ממך הכל<sup data-n=\"36\">36</sup> כו' ע\"כ נק' בחי' חתן שהוא בחי' משפיע, ובחי' ממלא כ\"ע הנ\"ל שזהו בחי' גילוי אור הנמשך מסובב כ\"ע (כמו אותיו' הדיבור שנמשך בגילוי אור מבחי' העלם המח' והשכל או כגילוי אור וחיות הנפש בגוף שנמשך מעצם הנפש כנ\"ל והוא כפרט שיוצא מן הכלל כו') נק' כלה בחי' מקבל לפי שהוא בחי' מקבל שמקבל הארת אור זה מן המשפיע שהוא סובב כ\"ע שנק' ח\"י העולמי' כנ\"ל וד\"ל. וזהו שנק' בכלל יחוד הוי' אלקי' שזהו יחוד שם מ\"ה וב\"ן כיחוד דכר ונוק' שנק' יחוד קודב\"ה ושכינתי', וכמ\"ש כי שמש ומגן<sup data-n=\"37\">37</sup> הוי' אלקי' שבחי' אלקים הוא בחי' ממלא כ\"ע בחי' כלה שמקבל מן בחי' המשפיע שהוא שם הוי' בחי' סובב כ\"ע הנ\"ל, כמו הארת אור השמש שמקבל מגופו של השמש או כמו הלבנה שאין לה אור עצמה רק מה שמקבלת מאור השמש לבד כידוע, וכך למעלה בחי' שם אלקי' שהיא בחי' המל' לית לה מגרמה כלום רק כשמקבלת מאור שם הוי' דוקא, וזהו יח\"ת דהוי' ואלקי' וכמ\"ש כי הוי' הוא האלקי' דכולא חד ממש<sup data-n=\"38\">38</sup> כמ\"ש בזוהר בכמה מקומו'.\n[ה] <b>וזהו</b> פי' שמח תשמח ריעים האהובים. כי הנה בחי' משפיע ומקבל דסובב וממלא הנ\"ל נק' ריעים האהובים כמו שני ריעים האהובי' שלא יפרדו לעולם, וכמו חו\"כ הגשמיי' ודכר ונוק' שנק' ריעים האהובים שאהבתם נפלאה זא\"ז שהרי החתן עוזב או\"א ודבק באשתו כמ\"ש ע\"כ יעזב כו' וכן הכלה עוזבת בית אביה והולכת אחר אישה כמ\"ש ואל אישך תשוקתך כו', כידוע בזוהר דתאובתא דדכורא<sup data-n=\"39\">39</sup> לגבי נוק' להשפיע למקבל כי בלעדי זה אין לו שלימות",[["34","34","<b>אני ה' לא שניתי. . מלכותך</b>: מלאכי ג, ו. תהלים קמה, יג."],["35","35","<b>חתן. . חו\"ת דרגא. . הוא כחתן</b>: ע\"פ יבמות סג, א. תהלים יט, ו."],["36","36","<b>כי ממך הכל</b>: דה\"א כט, יד."],["37","37","<b>כי שמש ומגן</b>: תהלים פד, יב."],["38","38","<b>כי ה' הוא האלקי' דכולא חד ממש כמ\"ש בזוהר בכ\"מ</b>: זח\"א יב, א. זח\"ב קסא, א. זח\"ג קמג, א. רסד, א. ועוד."],["39","39","<b>ע\"כ יעזוב. . ואל אישך תשוקתך. . בזוהר דתאובתא דדכורא</b>: בראשית ב, כד. ג, ז. ראה זח\"א פה, ב. זח\"ב קסה, סע\"א."]]],[1900420018,"ולהיות שהמקבל שנק' אשה הרי היא אחת מצלעותיו כמ\"ש כי מאיש לוקחה זאת כו' ע\"כ יעזוב איש כו', וכמ\"כ תאובת' דנוק' לגבי דכורא תמיד לקבל השפע כי אין לה שלימות בלעדו כמ\"ש ואל אישך כו' (ובאמצעו' יחודם נק' אד\"ם דוקא שהוא דכ\"ר ונוק' כללא דאדם<sup data-n=\"40\">40</sup> כמ\"ש בזוהר, ואע\"פ שבטבעם הן ב' הפכי' ממש דטבע הזכר בבחי' החסדי' דוקא שהוא להשפיע חוץ ממנו וזהו עיקר התענוג שלו וטבע הנוק' הוא בבחי' גבו' רק לקבל השפע בעצמ' למלאו' חסרונה כו', ועכ\"ז מתכללי' יחד דוקא כי כל א' תשוקתו לדבק בהיפוכו דוקא, שהחסדי' דדכורא נמשכי' לידבק בגבו' דנוק' וגבו' דנוק' נמתקי' ונכללי' בחסדי' דדכורא שזהו יחוד והתכללו' דמ\"ד ומ\"ן ב' הפכי' דחו\"ג שמחמת זה יולידו<sup data-n=\"41\">41</sup> תולדה חדשה שהוא הולד שיוצא מחיבורם יחד דוקא, כידוע הכלל שכל ב' הפכים מנגדי' שיתדבקו בקירוב דוקא יולידו דבר חדש מאי\"ן ליש (משא\"כ בב' הפכי' מנגדי' שלא יסבלו זא\"ז כלל כאש ומים).\n<b>וכך</b> יובן למעלה בבחי' משפיע ומקבל דשם הוי' ואלקי' שנק' חו\"כ למעלה והוא יחוד דקודב\"ה ושכינתי' שנק' ריעים האהובים למעלה כמובן בכל ס' שה\"ש שמדבר בכל עניני החיבה ואהבת דודי' וריעי' דחו\"כ למעלה, שאהבת המשפיע למקבל הוא מה שיש בחי' עונג ותשוקה במשפיע העליון להשפיע רב חסד וטוב כמו שמטבע הטוב להטיב<sup data-n=\"42\">42</sup>, והוא מ\"ש כי אמרתי עולם חס\"ד יבנה כו' כי חפץ חסד הוא<sup data-n=\"43\">43</sup> כו', והיינו מה שיש בטבע בכל עילה בפרט תשוקה להשפיע לעלול המקבל ממנו, ואם לא הי' מציאו' חשק ועונג זה בכל משפיע להשפיע ולהתענג גם בירידה וצמצום זה שמצמצם עצמו כדי להשפיע לנמוך כו' לא הי' ענין ירידת ההשתלשלו' כלל, ובכללו' זהו בחי' החסדי' במשפיע הכללי שממנו מוצא מקור לבחי' גילוי האור ושפע שנק' מקבל שהוא כמו אותיו' הדיבור שהוא בחי' המל', כמו שמטבע הטוב לגלו' שפע החסד שבלבו או חכם לגלו' חכ' שבמוח החכ' בראש לדיבור בהתגלו' לחוץ ממנו אף שזהו בחי' צמצום וירידה אצלו אבל יש לו בזה תענוג ונמשך להשפיע למקבל ברצון וחשק גדול, וכמו שאמרו דיותר ממה שהעגל רוצה לינק<sup data-n=\"44\">44</sup> הפרה רוצה להניק וכה\"ג הרי יש רצון וחשק במשפיע להשפיע יותר ממה שיש רצון וחשק במקבל לקבל, והוא מ\"ש דתאובת' דדכורא לגבי נוק' כו' כמו ע\"כ יעזוב איש כו' ודבק באשתו, וכך הוא למעלה באיש העליון שמתענג בעונג העצמו' וחפץ חסד הוא להשפיע מאורו העצמי להיו' מקור למקבלי' כנ\"ל (וכמו במ\"ת שירד",[["40","40","<b>דכר ונוק' כללא דאדם כמ\"ש בזוהר</b>: זח\"א נה, ב. ועוד."],["41","41","<b>כידוע הכלל שכל ב' הפכים. . יולידו</b>: ראה בארוכה ס' מאמרי אדהאמ\"צ שמות ח\"ב ע' תג ואילך."],["42","42","<b>שמטבע הטוב להטיב</b>: ראה תניא בשהיחוה\"א פ\"ד. עמה\"מ שער שעשועי המלך רפ\"א. שומר אמונים ויכוח ב סי\"ד."],["43","43","<b>כי אמרתי. . כי חפץ חסד הוא</b>: תהלים פט, ג. מיכה ז, יח."],["44","44","<b>דיותר ממה שהעגל רוצה לינק</b>: ראה פסחים קיב, א."]]],[1900420019,"ה' על ה\"ס ברצון והארת פני' ברוב אה\"ר וחיבה יתירה להשפיע אור דתורה מח\"ע העצמי' לישראל פנים בפנים כו', ואע\"פ שירידה וצמצום גדול הי' זה אבל כתי' קול דודי<sup data-n=\"45\">45</sup> כו' מדלג על ההרים כו', ונק' חת\"ן כמ\"ש ביום חתונתו זו מ\"ת<sup data-n=\"46\">46</sup> כו', ויותר ממה שהעגל כו' דהיינו יותר מתשוקת נש\"י שנק' כלה לקבל כשאמרו נעשה<sup data-n=\"47\">47</sup> הי' חשק ורצון העליון דמשפיע להשפיע להם כו' (וכמשי\"ת).\n<b>והנה</b> כמ\"כ מלמטה למעלה מן המקבל אל המשפיע שזהו בחי' התשוקה דכלה לגבי חתן העליון זהו בחי' ההעלא' וביטול דאור האלקי המצומצם באותיו' הדיבור העליון שנק' כלה שנק' שכינ' לעלו' ולקבל האור ממקורו הראשון שהוא בחי' סובב כ\"ע הנ\"ל וכמו ואל אישך כו', וכמ\"ש בזוהר ע\"פ אלקי' אל דמי לך כו' דאלקים עצמו הוא שעולה בעלי' למעלה בתשוקה לקבל מן המשפיע שהוא בחי' שם הוי' דסובב כ\"ע כנ\"ל, והוא שא' בזוהר דנהורא תתאה<sup data-n=\"48\">48</sup> קארי תדיר לנה\"ע ולא שכיך לעלמין דהיינו בחי' שם אלקי' בחי' ממלא בחי' המל' שמלובש בבחי' צמצום להיו' ראש ומקור לנבראי' כו' וכמ\"ש ואתה מחי' את כולם א\"ת דכ\"ב אותיו'<sup data-n=\"49\">49</sup> הדיבור (וכמ\"ש בס\"י וקבען בפה<sup data-n=\"50\">50</sup>) נק' בחי' נה\"ת שהוא בחי' כלה המקבל מבחי' סובב כ\"ע המשפיע וכמו ואל אישך תשוקתך כנ\"ל שקארי תדיר לנה\"ע להוי' דאצי' לקבל הארת אור ושפע ולא שכיך כו', כמ\"ש למען יזמרך כבו\"ד ולא ידום, פי' כבוד זהו שנק' כבוד נבר\"א שהוא ל\"ב נ\"ח גי' כבוד שנק' מלך הכבו\"ד כו' וכמ\"ש על כל כבו\"ד חופה כבוד עליון שנק' כבוד נאצל חכמה עילאה וכבוד תחתון ח\"ת שלא ידו\"ם כבוד זה בבחי' העלא' דאו\"ח למעלה כנ\"ל (ונק' עול\"ת תמיד שעולה תמיד בהעלא' ותשוקה לגבי נה\"ע דאצי' שהן ה\"ג דנוק' שמעלה מ\"ן תמיד, והוא מ\"ש אש כו' על המזבח<sup data-n=\"51\">51</sup> כו' ולכך נק' אש\"ה אש ה\"א<sup data-n=\"52\">52</sup> תתא' כמ\"ש בזוהר ואיש אש יו\"ד דחסד דח\"ע כו').\n<b>ולפי</b> הכלל הנ\"ל דיותר ממה שהעגל כו', כך הוא למעלה שתאובתא דדכורא יותר להשפיע כו' מתשוקת המקבל לקבל (וכמ\"ש במ\"א שכל אשר לאיש יתן בעד נפש\"ו שהוא בחי' המקבל, וראי' ממה שבמ\"ת שהוא תשב\"כ",[["45","45","<b>פנים בפנים. . קול דודי</b>: ואתחנן ה, ד. שה\"ש ב, ח."],["46","46","<b>ביום חתונתו זו מ\"ת</b>: שה\"ש ג, יא. תענית כו, ב."],["47","47","<b>כשאמרו נעשה</b>: יתרו יט, ח. משפטים כד, ז."],["48","48","<b>בזוהר ע\"פ אלקי' אל דמי לך. . בזוהר דנהורא תתאה</b>: תהלים פג, ב. ראה זח\"ב קמ, א. זח\"א עז, ב. פו, ב. קעח, ב."],["49","49","<b>ואתה מחי'. . א\"ת דכ\"ב אותיו'</b>: נחמי' ט, ו. וראה גם ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תקמא. וש\"נ."],["50","50","<b>בס\"י וקבען בפה</b>: ראה ס' יצירה פ\"ב, מ\"ג."],["51","51","<b>אש כו' על המזבח</b>: צו ו, ו."],["52","52","<b>אש\"ה אש ה' תתאה כמ\"ש בזוהר</b>: ראה זח\"א מח, ב."]]],[1900420020,"בחי' משפיע לא נשאר כ\"א גויתו שהן רק האותיו' בלא נקודו' כי הכל נתן לבחי' הנוק' שהוא תשבע\"פ בחי' מקבל, וכן ביונתן ודוד בחי' יסוד ומל' א' ויתפש\"ט יונת\"ן כו' כי אהבת נפש\"ו<sup data-n=\"53\">53</sup> כו') (ועכ\"ז בבחי' העדר השפע תשוקת המקבל יותר כמא' יותר משהאיש כו' האשה רוצה להנשא, וכמו טב למיתב כו'<sup data-n=\"54\">54</sup>, וגם באשה לבעלה בהעדר היחוד תגדל התשוקה שלה יותר וע\"כ א' אשה מזרע' תחלה<sup data-n=\"55\">55</sup> כו', וז\"ש נפש\"י (בחי' מל' שנק' נפש דוד כידוע) אויתי\"ך בלילה דוקא שהוא בזמן הגלו' בהעדר יחוד העליון דקודב\"ה בגלותא אסתלק<sup data-n=\"56\">56</sup> לעילא כו' אז אויתי\"ך ביותר וכן רשפי' רשפי אש בגלות' דוקא, וע\"ז א' הסיבי עיניך מנגדי כו' דמוקדי' לי'<sup data-n=\"57\">57</sup> בשלהובי דרחימותא כו').\n[ו] <b>והנה</b> כמו שמבואר למעלה בענין בחי' יחוד דהוי' ואלקי' בחי' סובב וממלא משפיע ומקבל שנק' חו\"כ למעלה שזהו שנק' בחי' ריעים האהובי' למעלה בתמידו' האהבה והתשוקה זא\"ז בלי פירוד לעולם כנ\"ל, כך יובן ג\"כ בענין חו\"כ למטה כמו בנש\"י בגופי' למטה שנק' כל\"ה מל' כלת\"ה נפשי שנק' כנ\"י דלתתא ונק' אשה ירא' ה' בבחי' נוק' בחי' מקבל משם הוי' שלמעלה, בחי' סובב כ\"ע הנ\"ל, וגם בהן א' ואל אישך תשוקתך שזהו להקדב\"ה שנק' חתן ונק' איש כידוע שע\"ז יסוד הענין ביחודא עילא' דהוי' ואלקי' והיינו מה שמזכיר חו\"כ בשה\"ש כמו לבבתני אחותי כלה<sup data-n=\"58\">58</sup> כו' כידוע. וביאור הענין הזה הנה אנו רואי' כמו בחוש הטבעי' בכלל נש\"י הגם שמלובשי' בגופים גשמיי' ובפרט בכל א' מישראל מצד נשמתו האלקי' הרי הן מתעוררי' תמיד באה\"ר ותשוקה נפלאה ליכלל ולידבק בה' אחד שנק' הקדב\"ה בחי' סובב כ\"ע הכללי הנ\"ל, וכמו שאנו רואי' בכאו\"א מישראל שאו' שמע ישראל שהוא הניצוץ האלקי שנק' ישרא\"ל ש\"ר א\"ל<sup data-n=\"59\">59</sup> שמוסר נפשו באחד בכל בקר וערב, ובכללו' נש\"י הן המייחדי' שמו ית' פעמי' בקר וערב ונק' ג\"כ מקדשי שמך כו', והיינו בבחי' אהבה ותשוקה גדולה באמרם ואהבת את ה' כו' בכל לבבך בכל נפשך כו', ופי' ואהב\"ת ל' ממילא מצד טבע המקבל שיש לו תשוקה למשפיע כנ\"ל (והוא מצד רוחא דשביק בגווה בזמן מ\"ת (כמשי\"ת), וידוע דבאתדל\"ת מכנ\"י מלמטה למעלה מעורר אתדל\"ע כמים הפנים כו' מלמעלה למטה מן המשפיע למקבל בחי' אה\"ר העליונה של הקדב\"ה לכנ\"י כמ\"ש",[["53","53","<b>ויתפשט יונתן כו' כי אהבת נפשו</b>: שמו\"א יח, ד. כ, יז."],["54","54","<b>יותר משהאיש. . טב למיתב כו'</b>: כתובות פו, א. קידושין ז, א."],["55","55","<b>אשה מזרע' תחלה</b>: נדה לא, א."],["56","56","<b>נפשי אויתיך. . דקודב\"ה בגלותא אסתלק</b>: ישעי' כו, ט. ראה זח\"א רי, א. זח\"ג כ, ב."],["57","57","<b>רשפי'. . הסיבי עיניך. . דמוקדי' לי'</b>: שה\"ש ח, ו. ו, ה. זח\"ג פד, א."],["58","58","<b>לבבתני אחותי כלה</b>: שה\"ש ד, ט."],["59","59","<b>ישראל ש\"ר א\"ל</b>: ראה גם לקו\"ת ראה לב, א. ס' מאמרי אדהאמ\"צ שמות ח\"ב ע' תמב וע' תסב. דברים ח\"א ע' של. ח\"ב ע' תקנז. ח\"ג ע' א'פ [ובהמ\"מ שם]. ח\"ד ע' א'קעד."]]],[1900420021,"אהבתי אתכם<sup data-n=\"60\">60</sup> אמר ה' כו' וכתי' אה\"ע אהבתיך כו', שזהו בחי' המשכה דאה\"ר דבחי' סובב כ\"ע שהוא שם הוי' בבחי' החסד דימין מקרבת כמ\"ש וימינ\"ו<sup data-n=\"61\">61</sup> תחבקיני כו', ואה\"ר זו דמשפיע למקבל גדולה יותר כנ\"ל בענין יותר ממה שהעגל כו', וא\"כ בחי' אה\"ר העליונה לישראל כמו שאנו אומרי' הבוחר בעמ\"י באהבה גדולה יותר מאהב' דכנ\"י להקדב\"ה (והוא מטעם שא' האדם זאת הפעם עצם מעצמ\"י ממש כו' כי מאיש לוקחה זאת וע\"כ אמרו דאשתו כגופ\"ו דמיא<sup data-n=\"62\">62</sup> ולכך א' ע\"כ יעזוב כו' כנ\"ל), והטעם הוא לפי שבחי' האהבה שנמשך מן המשפיע אל המקבל באה בתחלה וקודם להתעוררו' האהבה מן המקבל למשפיע, והוא מה שנמשך האהב' דמשפיע למקבל בבחי' מקיף דוקא שהוא להקיף ולסובב את המקבל בבחי' חיבוק דימין מקרבת (לפי ששרש הנוק' שנק' בת זוגו הרי היא מאיש לוקח' זאת כנ\"ל), כמו שמחבק אב לבנו ילד שעשועי' שמחמת גודל האה\"ר שבבחי' מקיף שלא יוכל להכיל בגילוי כמו בדיבור באה בבחי' מקיף מלמעלה ע\"ג המקבל, ומחיבוק זה הוא שמקרבו ומצמידו ומחברו אליו (כמו שהי' בשרשו כלול בו כמו שא' עצם מעצמי כו') לבלתי יוכל המקבל ליפרד ממנו לעולם, כי זהו יתרון מעלה שיש בכח או\"מ זה דאה\"ר בבחי' חיבוק בימין מקרבת ברוב עוז וחיבה יתירה שפועל חיזוק כח האהבה היתירה בהעלם בלב המקבל אל המשפיע שיומשך אליו תמיד ולא יוכל להפרד לעולם (וזה שנמשך המקבל אחר המשפיע ע\"י חיבוק זה הוא ג\"כ בבחי' מקיף דמקבל (בבחי' צלם דחי' יחידה שבה (כמו ביצ\"מ שא' זכרתי לך חסד נעוריך<sup data-n=\"63\">63</sup> לכת\"ך אחר\"י כו' שהי' זה מצד התקרבו' דמקיף העליון שנגלה עליהם כו' (כמו ענין האירוסי' בטבעת קידושי' וכמ\"ש וארשתיך לי באמונ\"ה<sup data-n=\"64\">64</sup> כו'), וכך יש בכל אדם בכל יום דכתי' אך בצלם יתהלך<sup data-n=\"65\">65</sup> איש שיתהלך מכח המקיף העליון שחופף עליו לבלתי יוכל לבא לחטא גמור כו'), וכמ\"כ הי' במ\"ת קודם שנגלה עליהם בקולו' וברקים ובגילוי קול ודיבור ארז\"ל שכפה עליהם ההר<sup data-n=\"66\">66</sup> כגיגית כו' כלומר שכפה עליהם ההר שהוא בבחי' אה\"ר דרב חסד העליון בבחי' מקיף להקיפם מכל צד כו' (כידוע דהר הוא בבחי' צומח שבדומם שעולה למעלה (והוא מצד יסוד הרוח שבעפר שעולה למעלה כמ\"ש במ\"א<sup data-n=\"67\">67</sup>), וכאברהם שקראו הר ה' ואבות הן המרכבה נק' הרי\"ם<sup data-n=\"68\">68</sup> שהן המדו' אהבה ויראה כידוע,",[["60","60","<b>אהבתי אתכם. . אהבת עולם אהבתיך</b>: מלאכי א, ב. ירמי' לא, ב."],["61","61","<b>וימינו תחבקני</b>: שה\"ש ב, ו. ח, ג."],["62","62","<b>דאשתו כגופו דמיא</b>: בכורות לה, ב."],["63","63","<b>זכרתי לך חסד נעוריך</b>: ירמי' ב, ב."],["64","64","<b>וארשתיך לי באמונה</b>: הושע ב, כב."],["65","65","<b>אך בצלם יתהלך</b>: תהלים לט, ז."],["66","66","<b>שכפה עליהם ההר</b>: שבת פח, א."],["67","67","<b>דהר הוא בחי' צומח. . כמ\"ש במ\"א</b>: ראה לעיל ח\"א ע' רי וע' דש [ובהמ\"מ שם בע' רי נסמן לכ\"מ בדא\"ח]."],["68","68","<b>וכאברהם שקראו הר ה' ואבות הן המרכבה נק' הרים</b>: פסחים פח, א. ב\"ר פמ\"ו, ו. ר\"ה יא, א."]]],[1900420022,"וכך התפעלו' האהב' בלב היא בבחי' צומח שעולה למעלה, כמו רוח החיים שבלב שעולה בצמאון ותשוקה גדולה כו', וכך יש מלמעלה למטה בבחי' ירידה והמשכה בבחי' או\"מ דוקא שזהו כפה עליהם הה\"ר דאה\"ר עליונה בבחי' עיגול כדורי כגיגית שמקיף ומכסה על האדם לבלתי יוכל לצאת משם כו', והיינו שהקיפם באה\"ר העליונה לכללו' נש\"י שעמדו בה\"ס וחיברם בימין העליון והצמידם אליו במקיף הזה לבלתי יוכלו לצאת בבחי' פירוד מאלקות לעולם אף בענפי' שנסתעפו מס\"ר שרשי' הללו לדורות הבאי' (וזהו כמו החופה שמקפת על החו\"כ יחד שזהו כח ועוז גדול לכל יחוד שיהי' אח\"כ בגילוי ההתקשרו' באהב' רבה פב\"פ כו', וכידוע במ\"ש כי על כל כבו\"ד חופ\"ה, ובמ\"ת הי' בחי' נישואי' בחופה וכמ\"ש והוא כחתן<sup data-n=\"69\">69</sup> יוצא מחופת\"ו כו'), ושרש הענין הוא לפי שיש כח גדול הזה במשפיע דוקא להקיף באה\"ר בימין מקרבת למקבל כ\"כ עד שלא יוכל להפרד ונמשך אחריו תמיד, לפי שאהבת המשפיע אל המקבל גדולה הרבה יותר מאהבת המקבל למשפיע כמו יותר ממה שהעגל כו' כנ\"ל (והוא מפני שהמקבל נכלל בגוף המשפיע בשרשה כמ\"ש כי מאיש לוקחה זאת כנ\"ל), ע\"כ יש בכח אה\"ר זו לבא בבחי' מקיף בכח ועוז כ\"כ לפעול גם במקבל חיזוק התפעלו' אהבה רבה ויתירה בלבו אל המשפיע כנ\"ל לבלתי יוכל להפרד ממנו לעולם (וכמ\"כ יש כח ועוז גדול הנמשך מן המשפיע למקבל בבחי' או\"פ בגוף היחוד שנק' רוחא דשביק בגוה בביא' ראשונה שמזה יש בה תשוקה תמידי' לבעלה עד שאינה כורתת ברית<sup data-n=\"70\">70</sup> אלא לבן זוגה כו' שעשא' כלי כו' ולא תוכל להפרד ממנו לאיש זר כו' משום דאהבת המשפיע נקשר בה ברוחא זה דשביק בגוה לפי שעשאה כלי בזה בביא' ראשונה כו', וגם רוח זה בא מבחי' המקיף דמשפיע אך הוא נמשך בגילוי אור הנקלט ונקשר ביסוד דנוק' שיהי' מזה ג\"כ גילוי אור התשוקה התמידי' כמו ואל אישך כו', משא\"כ מבחי' מקיף דימין מקרבת מבחוץ כחיבוק אינו פועל רק בהעלם בבחי' מקיף במקבל כמו לכתך אחרי כנ\"ל וד\"ל.\n[ז] <b>והנה</b> כתיב שמאל\"ו תחת לראשי<sup data-n=\"71\">71</sup> וימינו תחבקיני, דקאי זה במ\"ת שהי' שם ב' דברים, בחי' שמאל דוחה בגבו' דקו השמאל, כמו בקולו' וברקי' לאיים עליהם שיחרדו וינועו כו' ועי\"ז יהיו כלי קיבול לקבל אור ושפע פנימי' כזו מעצמו' ופנימי' רצונו וחכמתו באור פניו ממש כו' (וכן מ\"ש קול ה' יחול\"ל אילו' שעשא' כלי קיבול<sup data-n=\"72\">72</sup> כחלל ריקן ע\"י קול ה' שראו את הקולו'",[["69","69","<b>וכידוע במ\"ש כי על כל כבוד חופה. . והוא כחתן</b>: ישעי' ד, ה. תהלים יט, ו. וראה לעיל ח\"א ע' א ואילך וע' כג וע' נז. ועוד. וראה להלן ד\"ה שמח תשמח (השלישי), פיסקא: וזהו שאמר, ובהנסמן לשם."],["70","70","<b>רוחא דשביק בגוה. . שאינה כורתת ברית</b>: ראה זח\"ב צט, ב [וראה בהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"א ע' כד]. סנהדרין כב, ב."],["71","71","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו."],["72","72","<b>קול ה' יחולל. . שעשא' כלי קיבול</b>: תהלים כט, ט. וראה ס' מאמרי אדה\"ז הקצרים ע' רז ואילך."]]],[1900420023,"ולפידי' כו' (ועכשיו הוא מה שקודם הדיבור בד\"ת יקבל עליו עול מלכות שמים באימה יתירה כמו שהי' במ\"ת כמו שא' מה להלן<sup data-n=\"73\">73</sup> באימה כו'), והב' הי' בחי' ימין מקרבת שזהו מ\"ש וימינו תחבקיני כנ\"ל שכפה עליהם ההר כו' שזהו בחי' המשכת אה\"ר ונפלאה וחזקה הרבה יותר מאהבת נש\"י להקדב\"ה עד שפועל ישועו' בחי' התעוררו' אה\"ר בתעלומו' הלב בקרב ולב איש בעומק אה\"ר עד שלא יוכל להפרד לעולם כנ\"ל (וזהו הנק' אהב' רבה המסותר\"ת כידוע שמתעוררת מנקוד' הלב שבהעלם לגילוי לפרקים כמו למס\"נ על קדה\"ש ולעמוד בנסיון בפועל ממש כו' וכה\"ג), שזהו ענין החיבוק כמ\"ש וימינ\"ו תחבקיני כו', כמו שאנו רואי' בחוש בכל חיבוק של המשפיע שפועל במקבל הנחבק שיוצמד אליו באהבה ולא תשכח ממנו האהב' לעולם ויהי' אחוז וקשור תמיד עמו בברית האהבה בל תמוט לנצח, וכאשר אנו רואים בגוף ענין החיבוק הגשמי שמורה ע\"ז והיינו במה שמחבק את אהובו כנפשו ביד ימינו ע\"ג גופו מאחוריו בעוז אה\"ר ונפלאה עד שמושכו ומחזירו אליו פב\"פ ואינו מניחו להפרד ממנו להיו' מהו' בפ\"ע אלא יהי' דבוק וקשור בו כאילו המה גוף ומהות א' ממש בל יפרדו לעולם וע\"כ צומדו ומחברו אליו בחיבוק זה שמחבקו בידו הסובב ע\"ג גופו מאחורי\"ו דוקא לבלתי יתן לו עורף כו', וכך הוא למעלה מורה ציור ענין החיבוק העליון דימינ\"ו תחבקיני שיד ימין העליון חובק לנש\"י גם בהיותם בגופי' טרודי' בצרכיהם שמקיף וסובב על בחי' אחוריי' שלהם ומצמידם ומחברם אליו ית' בחיבוק זה העליון שנק' או\"מ כנ\"ל עד שמחזירם כלפי פניו ממש לידבק בו ית' בבחי' פב\"פ בלי יוכלו להיו' במהו' יש נפרד בפ\"ע כאילו דבוקי' בו ית' והיו לאחדי' ממש לפי שבחיבוק זה אינו מניחם לזוז ממנו להפרד כי סובבם מכל צד לבלתי יוכלו לנטות מאחריו כו' (כמו השיבנו ה' אליך<sup data-n=\"74\">74</sup> כו'), והיינו לפי שבחיבוק זה מלובש מכח ועוז דאה\"ר העליונה בבחי' מקיף ע\"ג כנ\"י בתוקף גדול כ\"כ עד שפועל בנש\"י הנחזקי' שיהיו צמודי' וקשורי' באה\"ר בהתקשרו' תמידי' (כמו שאו' חבוקה ודבוקה בך כו', וכך א' בזוהר ע\"פ שימני כחותם על לבך דאע\"ג דאזיל<sup data-n=\"75\">75</sup> הכא והכא דיוקני אשתאר בך כו') עד שלא ינטה ויסוג אחור לב כל א' מישראל ולא ינתק לעולם לא מצד השכחה ולא מצד המונעי' ומבלבלים ביותר כמו טרדו' הפרנסה וכה\"ג וזהו רק מצד בחי' חיבוק דימין העליון (ולהיפוך כאשר בחי' ימין העליון אינו נמשך למטה בבחי' חיבוק או שלא יועיל כ\"כ לפעול התעוררו' אה\"ר בלב כנ\"י אז א' כי פנו אלי עורף<sup data-n=\"76\">76</sup> ולא פנים שנסוג אחור לבבם ונפרדי' להיו' בבחי' עורף",[["73","73","<b>מה להלן</b>: ברכות כב, א."],["74","74","<b>השיבנו ה' אליך</b>: איכה ה, כא."],["75","75","<b>חבוקה ודבוקה בך. . בזוהר ע\"פ שימני כחותם. . דאע\"ג דאזיל</b>: פיוט הושענות (אום אני חומה). שה\"ש ח, ו. זח\"ב קיד, א."],["76","76","<b>כי פנו אלי עורף</b>: ירמי' כ, כז."]]],[1900420024,"ואחוריי' וכו'), וכמ\"ש עת לחבק ועת לרח\"ק מחב\"ק כמו בזמן הגלו' שמתרחק מחבק וכמו למה תשיב ידך<sup data-n=\"77\">77</sup> וימינ\"ך מקרב חיק\"ך כל\"ה כו' כמ\"ש במ\"א שזהו ההפרש בין יחוד פב\"פ<sup data-n=\"78\">78</sup> שאזי יש בחי' חיבוק כמו יחבק לה בעלה וכן ימינא ושמאלא<sup data-n=\"79\">79</sup> ובינייהו כלה כו', אבל כשהמל' מלבשת עד החז' לבד א' עת לרחק מחבק כו'). וזהו שאו' ברכת אה\"ע עד הבוחר בעמ\"י באהבה לפני ק\"ש דוקא לפי שבק\"ש הוא שעת היחוד עליון דקודב\"ה ושכינתי' ביח\"ע ויח\"ת דשמע ישראל ובשכמל\"ו<sup data-n=\"80\">80</sup> למהוי אחד באחד ממש כידוע והיינו במס\"נ דנש\"י באחד בכאו\"א באה\"ר דכל נפשך כו', וזהו כמו גוף ענין היחוד והזווג דמשפיע ומקבל, ואמנם צריך להיות תחלה בחי' המשכה דמקיף דאה\"ר ואה\"ע מן המשפיע למקבל כנ\"ל כדי לעורר את האהבה בכנ\"י שזהו כענין בחי' החיבוק הנ\"ל שהוא בימין דמשפיע כמ\"ש וימינ\"ו תחבקיני כנ\"ל, וכמו ענין החיבוק דאיש לאשתו שהוא קודם גוף היחוד בשביל היחוד כו' וד\"ל. וכך הי' במ\"ת שכפה עליהם ההר כו' שזהו בבחי' חיבוק דימין העליון בבחי' מקיף דאה\"ר העליונה לנש\"י לעוררם באהבה וחשק להיו' חפיצי' להתדב\"ק בו ית' ע\"י תו\"מ ואז הי' כח בכנ\"י לקבל גוף האור ושפע די' הדברו' עד שעל כל דיבור פרחה נשמתן מרוב התענוג והתשוקה כו', וזהו כמו ענין החיבוק שקודם גוף היחוד כנ\"ל בברכת אה\"ר עד הבוחר כו' לפני ק\"ש דוקא מטעם הנ\"ל וד\"ל.\n<b>(ואמנם</b> הנה בחי' קול ודיבור זה די' הדברו' עד שעל כל דיבור כו' זהו מ\"ש קול ה' יחול\"ל כו' שעשה בחי' חלל בית קיבול בנש\"י שיוכלו לקבל בכלים שלהם כללו' התורה ומצות, וכענין הנ\"ל בבחי' רוחא דשביק בגוה בביא' ראשונה שעשא' כלי כו', וכך א' כי בועליך עושיך כו' שזהו מה שיש כח להעלו' מ\"ן בתשוקה תמידי' בלי יפרדו לעולם יותר מכח החיבוק דאו\"מ הנ\"ל שהוא רק בהעלם שנק' אהבה מסותרת כנ\"ל וכל מה שהי' אור המקיף בתחלה אינו רק בשביל זה היחוד, וכך גם עכשיו ביחוד פנימי' דקול ודיבור בד\"ת שמקשר דו\"מ ושכלו בדו\"מ ושכל דתו' שנק' אתדבקו' רוחא ברוחא חב\"ד בחב\"ד, ולבד מה שקול ודיבור זה הוא שעושה בנפשו כח המעלה מ\"ן תמיד כו' שעי\"ז לא יפרדו לעולם וכמ\"ש ואשים דבר\"י בפי\"ך<sup data-n=\"81\">81</sup> ובצ\"ל יד\"י כסיתי\"ך לנטוע שמים כו' בבחי' מקיף א' לשניהם כו').\n<b>(ועכ\"פ</b> הרי מובן מב' העניני' הנ\"ל בין בבחי' או\"מ דימין מקרבת דמשפיע בחיבוק כנ\"ל בין בבחי' או\"פ ברוחא דשביק בגוה ביחוד הראשון שכל",[["77","77","<b>עת לחבק. . למה תשיב ידך</b>: קהלת ג, ה. תהלים עד, יא."],["78","78","<b>במ\"א שזהו ההפרש בין יחוד פב\"פ</b>: ראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' תקסא ואילך."],["79","79","<b>יחבק. . ימינא ושמאלא</b>: פיוט ”אזמר בשבחין\"."],["80","80","<b>ביח\"ע ויח\"ת דשמע ישראל ובשכמל\"ו</b>: זח\"א יח, ב. ובכ\"מ."],["81","81","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."]]],[1900420025,"זה בא מכח המשפיע למקבל שידובק בו בלי פירוד לעולם, והוא לפי שבכלל גדולה אהבת המשפיע למקבל יותר מהמקבל למשפיע כנ\"ל וע\"כ יש בכח אהבתו לעורר ולעשו' התקשרו' אהבה במקבל (וכמו ב\"ק מכריז שובו בנים<sup data-n=\"82\">82</sup> שפועל התעוררו' תשוב' בנש\"י אף באותן שכבר נפלו ונדחו למטה ביותר וכן באה\"ר דימין מקרבת הנ\"ל פועל התעוררו' אהב' אף בניצוצו' שנתרחקו מאד כמו וימינך פשוט' כו' וכענין אה\"ר דכה\"ג שמעלה את הנרות שהן נש\"י שזהו כח המושך לבם כו'), והרי אנו רואים שאין כח זה הגדול במקבל אל המשפיע שאין המקבל יכול לפעול פעולה כזו במשפיע לעורר בו את האהבה רבה כזו לבלתי יפרד מן המקבל לא בבחי' או\"פ ולא בבחי' או\"מ, כי הגם שבאתדל\"ת מלמטה למעלה נמשך אתדל\"ע במשפיע כמו באה\"ר ואה\"ע, זהו רק כפי ערך ההתעוררו' מלמטה ויכול ליפסק מיד כי אינו אלא כמים הפנים כו' באותה שעה לבד כידוע לפי שאין בכח אהב' דמקבל לעשו' חיזוק התעוררו' האהב' במשפיע (להיותה רק חלק א' ממנו ונכללת בו כנ\"ל), ואע\"פ שא' לא מאסתים<sup data-n=\"83\">83</sup> כו' להפר בריתי אתם, זהו מצד התקשרו' המשפיע במקבל ולא מצד התקשרו' המקבל במשפיע כו' (ובאמת יש כח גדול גם במקבל לעשו' במשפיע התעוררו' אה\"ר (וכמו שא' לאה הפעם ילוה אישי כו' יזבלנ\"י אישי כו') וכמ\"ש לבבתנ\"י אחותי כלה<sup data-n=\"84\">84</sup> כו' דמשמע שעשתה אהבתו בלבו בנקוד' הלב הפנימי' כו' וא' הסיבי עיניך כו' דמוקדי' לי'<sup data-n=\"85\">85</sup> כו' וכמ\"ש ביום ההוא יצאו מ\"ח מירושלי' אל הים כו' וכן עלי בא\"ר ענו לה כו' קומ\"י לך<sup data-n=\"86\">86</sup> רעייתי כו', שזהו עליי' המל' בחי' המקבל למעלה מן המשפיע כמו אשת חיל עטרת בעלה נקבה תסובב גבר<sup data-n=\"87\">87</sup>, וכן ואולך אתכם קוממיו' ב' קומות<sup data-n=\"88\">88</sup> דאו\"י ואו\"ח בכפלים דקומת המשפיע דאו\"י כו', וכמא' אין טפה יורדת מלמעלה<sup data-n=\"89\">89</sup> שאין טפיי' עולי' לנגדה שהן העלא' מ\"ן דנוק' שהן טפיי' כו', וכל זה אינו רק מצד בחי' התקשרו' דמקבל בהעלא' מ\"ן למשפיע שיגדל יותר מאהב' דחסדי' דמשפיע, כמו עד דוד הגדי\"ל שהגדי\"ל יותר מאהבת יונתן שהוא המשפיע ודוד בחי' מקבל שזהו אהבת נפש\"ו אהבו",[["82","82","<b>ב\"ק מכריז שובו בנים</b>: חגיגה טו, א."],["83","83","<b>לא מאסתים</b>: בחוקותי כו, מד."],["84","84","<b>הפעם ילוה. . יזבלנ\"י אישי. . לבבתני אחותי כלה</b>: ויצא כט, לד. ל, ב. שה\"ש ד, ט."],["85","85","<b>הסיבי עיניך כו' דמוקדי' לי'</b>: שה\"ש ו, ה. ראה זח\"ג פד, א."],["86","86","<b>ביום ההוא יצאו מ\"ח. . עלי בא\"ר. . קומ\"י לך</b>: זכרי' יד, ח. חוקת כא, יז. שה\"ש ב, י."],["87","87","<b>אשת חיל. . נקבה תסובב גבר</b>: משלי יב, ד. ירמי' לא, כא."],["88","88","<b>ואולך אתכם קוממיות ב' קומות</b>: בחוקותי כו, יג. ראה סנהדרין ק, א. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשפו ואילך."],["89","89","<b>אין טפה יורדת מלמעלה</b>: ראה זח\"ג רמז, ב. לקו\"ת שלח מב, ב [ובהמ\"מ שם]. ס' מאמרי אדהאמ\"צ בראשית ע' רל [ובהמ\"מ שם]."]]],[1900420026,"כידוע דיונת\"ן הוא יסוד ז\"א כמ\"ש במ\"א<sup data-n=\"90\">90</sup>, וכנ\"ל במ\"ש וכל אשר לאיש כו', וכן ביעקב ובנימין שא' ונפשו קשורה בנפש\"ו<sup data-n=\"91\">91</sup> שזהו בחי' צ\"ת דבנימין בבחי' או\"ח שעולה למעלה מכח המשפיע, כידוע דבע\"ס דאו\"ח בחי' המל' הוא בחי' הכתר דלכך כת\"ר מל' איהו כתר עליון<sup data-n=\"92\">92</sup> כו', וכן בענין השלום שהוא ב' שלימו' שלום העליון מן המשפיע למקבל כמו הנני נותן לו כו' ושלום הב' מלמטה למעלה מן המקבל למשפיע שנק' שלום בית עולה למעלה יותר, וז\"ש ה' יברך את עמו בשלו\"ם אותיו' מלבו\"ש<sup data-n=\"93\">93</sup> דחשמ\"ל העליון כו') (וכן מובן בשה\"ש בכמה מקומות כמו מה יפית כו' אהבה בתענוגי' אני לדודי ועלי תשוקתו כו' וכן עזה כמות אהבה כו' רשפיה רשפי אש כו' אם יתן איש<sup data-n=\"94\">94</sup> כל הון ביתו באהבה כו' (ואע\"פ שאינה רק צלע אחת מצלעותיו וא' זאת הפעם עצם מעצמי כו' לזאת יקרא אשה כי מאיש לוקח' כו' א\"כ למה יהי' כחה גדול מן האיש, זהו קודם הנסירה שהיו דו פרצופי' כמ\"ש אחור וקדם<sup data-n=\"95\">95</sup> צרתני כו' אבל לאחר בנין הנוק' יש בינה יתירה באשה יותר<sup data-n=\"96\">96</sup> כו' שעולה למעלה ממנו, וכמו שאו' והתקין לו ממנו בנין עדי עד שהוא כתר מל' דמשיח בן דוד שהוא בחי' המל' שיהי' נצחי ובהגדלה וריבוי ביותר כמ\"ש אז יאמרו<sup data-n=\"97\">97</sup> כו' הגדיל ה', וכמו ואולך אתכם קוממי\"ו' כנ\"ל (והיינו ענין תשבע\"פ מל' קרינן לה שנתגדל בה ונתעלה כל פרטי רצה\"ע בכפלי כפלי' ממה שכתוב בתשב\"כ ואע\"פ שמקבל מתשב\"כ, וכמו הכח שיש בנוק' לגדל הולד בט' חדשים ברמ\"ח אברי' מטפה א' דמשפיע (וכן באלישע שא' ויהי נא פי שנים ברוחך אלי כו', וכן ביהושע פני לבנה שמקבל מפני חמה דמשה ונק' נער לא ימיש<sup data-n=\"98\">98</sup> כו' ועל ידו דוקא נכנסו ישראל לא\"י ונעשה בנין המל' באורך ורוחב גדול באו\"כ במצות ונק' ארץ טובה ורחבה יותר מן המשפיע כו' וד\"ל).\n[ח] <b>והנה</b> כל ענין הנ\"ל בבחי' יחוד דשם הוי' ואלקי' שזהו בחי' סובב כל עלמין וממלא כל עלמין בכלל כנ\"ל שנק' יחוד קודב\"ה ושכינתי' (ואף למעלה בחי' יח\"ע די\"ה דאו\"א וגם בע\"י וא\"א וא\"ק הכל הוא רק בבחי' ממלא בכללות בקו\"ח לגבי בחי' מל' דא\"ס שלפני צמצום הראשון שנק' סובב הכללי שמקיף לכל ההשתלשלו' דקו\"ח כו', הרי אין כל זה שייך רק כאשר בא לכלל בחי' השתלשלו' דעו\"ע שנק' משפיע ומקבל בכלל ובפרט, דהיינו כאשר",[["90","90","<b>עד דוד הגדיל. . אהבת נפשו אהבו. . דיונתן הוא יסוד ז\"א כמ\"ש במ\"א</b>: שמו\"א כ, מא. יז. ראה לקו\"ת להאריז\"ל שמו\"א כ, כ. סה\"מ תקס\"ז ע, נח. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ס\"ע שנה. במדבר ח\"א ע' קסג. דברים ח\"ב ע' תכא. וש\"נ."],["91","91","<b>ונפשו קשורה בנפשו</b>: ויגש מד, ל."],["92","92","<b>כתר מל' איהו כתר עליון</b>: תקוני זהר בהקדמה ד\"ה פתח אליהו."],["93","93","<b>הנני נותן. . ה' יברך. . בשלו\"ם אותיו' מלבוש</b>: פינחס כה, יב. תהלים כט, יא. משנת חסידים מס' תפילת האצי' ספי\"א [ובהנסמן עוד במ\"מ בס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'לו]."],["94","94","<b>מה יפית. . אני לדודי. . עזה כמות. . רשפי'. . אם יתן איש</b>: שה\"ש ז. ז. ז, יא. ח, ו-ז."],["95","95","<b>דו פרצופי' כמ\"ש אחור וקדם</b>: ברכות סא, א וע\"ש בפירש\"י. תהלים קלט, ה."],["96","96","<b>בינה יתירה באשה יותר</b>: נדה מה, ב."],["97","97","<b>אז יאמרו</b>: תהלים קכו, ב."],["98","98","<b>ויהי נא פי שנים. . ביהושע פני לבנה. . נער לא ימיש</b>: מל\"ב ב, ט. ב\"ב עה, א. תשא לג, יא."]]],[1900420027,"מבחי' מוה\"ע<sup data-n=\"99\">99</sup>. דא\"ס ב\"ה נמשך בבחי' מקור להשתלשלו' זהו שנק' בבחי' השפעה והמשכה לחוץ מן העצמות, דאע\"פ שאור א\"ס עצמו מאיר למטה כמו למעלה בלי הפרש כלל כי קודם הצמצום הראשון הנק' מקום פנוי וחלל כו' הי' אור א\"ס ממלא כל המקום פנוי כו' כמ\"ש בע\"ח<sup data-n=\"100\">100</sup> וגם בדברי רז\"ל מרומז זה במה שא' דקודם שנברא העולם הי' הוא ושמו בלבד<sup data-n=\"101\">101</sup> (שהוא בחי' מל' דא\"ס), זהו קודם הצמצום הראשון הנ\"ל, אבל לאחר הצמצום הזה נמשך אח\"כ להיו' בבחי' אור ושפע בשביל השתלשלו' העולמו' כי חפץ חסד הוא מצד עצם הטוב כו' כמ\"ש בע\"ח<sup data-n=\"102\">102</sup>, ואז יש בזה ב' מדרגו' שהן בחי' משפיע ומקבל בכלל, והוא שנק' או\"מ ואו\"פ בכללות כנ\"ל), דהיינו בחי' סובב כ\"ע הכללי זהו מה שמקיף לכל העולמו' דאבי\"ע (גם בחי' ע\"י וא\"א וא\"ק כו'), מראשית הקו\"ח לסופו (כמו עד עק\"ב דא\"ק בסוף העשי' כידוע) נק' משפיע בכלל (והוא כענין כלל לפרט שנק' מח' הכללי' כנ\"ל), ובחי' גילוי האור הזה להיו' בבחי' ממלא כ\"ע בכלל (שהוא הקו\"ח) נק' בחי' מקבל כנ\"ל), ויש בהן יחוד והתכללו' זע\"ז כמו כי הוי' הוא האלקי' כנ\"ל, אבל בבחי' מוה\"ע דאא\"ס שהוא בבחי' אח\"פ ממש כמו שהוא ממש טרם שיבא לכלל בחי' משפיע עדיין הרי הוא נק' יחיד לבדו בבחי' אח\"פ בתכלית הפשיטו', וכמא' אנת הוא חד<sup data-n=\"103\">103</sup> ולא בחושבן די\"ס שנק' אחד אלא נק' יחיד לבדו כו' שלא יתכן לכנות לו שם דסובב ג\"כ, כי אין ענין סובב ומקיף שייך רק במה שבא לכלל בחי' השפעה והמשכה בהשתלשלו' דוקא שאז נק' סובב לעלמי\"ן עכ\"פ, אבל כמו שהוא יחיד לבדו למעלה מבחי' משפיע אינו שייך לומר בו גם ענין מקיף לתחתון כו' וד\"ל. וזהו כי עמך מקור חיים, דגם בחי' מקור החיים הכללי יותר כמו בחי' סובב הכללי שמקיף לראשית הקו\"ח וסופו כא' (ונק' טה\"ת), עמך טפל ובטל ונכלל במוה\"ע ית' ואין ערוך לו כלל אפי' כטפה בים כו', כי אין בחי' הארה זאת ששייך לבחי' השפעה והמשכה לעולמו' ערך כלל לגבי מוה\"ע ית' אפי' לגבי בחי' גילוי אור דעצמו' א\"ס שנק' מל' דא\"ס כמו שהוא קודם הצמצום הראשון הנ\"ל שהי' הוא ושמ\"ו בלבד כנ\"ל וד\"ל.\n<b>וזהו</b> פי' יחיד חי העולמי' מלך, כי בטרם שיצמצם אור עצמותו ממש כדי להיו' מקור למקור החיים כו' נק' יחי\"ד לבדו, כידוע ההפרש בין יחיד לראשון, דראשון יש לו התחלה ולתחלה יש סוף לפי שיש שני אליו ומשני לשלישי כו', אבל ליחיד אין שני לו כו', והוא ענין אור העצמו' דא\"ס ממש",[["99","99","<b>מוה\"ע</b>: מהות ועצמות. ראה לעיל ריש אות ב."],["100","100","<b>הי' אוא\"ס ממלא. . כמ\"ש בע\"ח</b>: ראה ע\"ח ש\"א ענף ב, ד. ש\"ג פ\"א."],["101","101","<b>דקודם שנברא. . ושמו בלבד</b>: פדר\"א פ\"ג."],["102","102","<b>כי חפץ חסד הוא מצד עצם הטוב כו' כמ\"ש בע\"ח</b>: מיכה ז, יח. ראה בהנסמן להלן סוסי\"ג [בהמ\"מ פיסקא: ”וכמ\"ש בע\"ח\"]. ולעיל אות ג' ריש פיסקא ”וזהו\". ובס' מאמרי אדהאמ\"צ ויקרא ח\"א ס\"ע לט."],["103","103","<b>אנת הוא חד</b>: תקוני זהר בהקדמה ד\"ה פתח אליהו."]]],[1900420028,"שאין לו תחלה ואין לו תכלה כו' (וכן נק' בשם קדמון לכל הקדומי' כו' כמ\"ש במ\"א בענין מגיד מראשית<sup data-n=\"104\">104</sup> כו' ומקד\"ם כו'), אבל מה שנק' בשם ח\"י העולמי' זהו שנמשך אחר הצמצום הראשון הנ\"ל מבחי' מל' דא\"ס שמתצמצם להיו' מקור לכל ההשתלשלו' דקו\"ח הנ\"ל, וכמ\"ש מלכותך מלכות כל עולמים<sup data-n=\"105\">105</sup> כו' והוא מה שעלה במח' הקדומה רצון פשוט להיו' מלך ובאמת נק' מלך מרומם לבדו או מלך יחיד כו' רק שנתצמצם להיו' מלכותו מל' כ\"ע בהתנשאו' שחוץ ממנו על העולמו' שאין לו ערך כלל לבחי' ההתנשאו' שמצד עצמו ממש שנק' מלך מרומם לבדו או מלך הקדוש כידוע. וזהו ההפרש בין מלך יחי\"ד ח\"י העולמי' שזהו מה שנמשך ממלך הקדוש מל' דא\"ס קודם הצמצום להיו' ח\"י העולמי' בין יחיד ח\"י העולמי' מל\"ך שמלך זה הוא מה שעלה במחה\"ק להיו' מלך על ההשתלשלו' שזהו שאו' המתנשא מימות עולם לבד כו' וד\"ל.\n[ט] <b>וזהו</b> פי' משובח ומפואר עדי עד כו', דהנה הגם שבחי' מל' דא\"ס כמו שמתצמצם להיו' חי העולמי' אינו רק בחי' הארה א' מצומצם הבא בדילוג הערך מעצמו' אא\"ס ממש כמו שהוא אחר צמצום הראשון הנק' מק\"פ כו' מ\"מ יש בו מבחי' עצמו' אא\"ס ממש, שזהו מה שאא\"ס מתפשט למטה עד אין תכלית דכשמו כן הוא דאין סוף משמעו שאין סוף לבחי' התפשטותו דוקא, ומאחר שבא למטה בבחי' התפשטו' יש בו ענין שבח ותהלה שיוכל לבא בגילוי אור לנשמו' באבי\"ע להיותו מקור למקור להשתלשלו' בקו\"ח ואף בעונג העצמו' דא\"ס ב\"ה שיומשך בעוה\"ב יתגלה לנשמות בהשגה ויהיו נהנין מזיו כו', וכן גם עכשיו בנשמו' שבג\"ע העליון דבריא' עולי' הן מדי חדש ושבת בעילוי אחר עילוי מבריא' לאצי' ומאצילו' למעלה יותר עד אין שיעור למעלה לפי שמאיר מעצמו\"ת דאור א\"ס בקו\"ח עד אבי\"ע שהוא בלתי גבול ומדה כלל לכך יכול הוא ית' להיות מתצמצם בהשגו' הנשמו' בעלייתן להיות משובח ומפואר בהן בכל מיני שבח ותהלה במדרגה אחר מדרגה לאין קץ ושיעור כלל, וכמו שאנו אומרים וקדושי' בכל יום יהללוך סלה שהן נשמו' קדושי' העליוני' כמו האבו' ומשה ואהרן וכה\"ג שהולכי' ועולי' בעילוי אחר עילוי אף עכשיו אחר עלותם למקור חוצבם בע\"ס דאצי' בעילוי אחר עילוי להלל ולשבח עד אין שיעור בלי הפסק כלל וכלל כמ\"ש ילכו מחיל אל חיל<sup data-n=\"106\">106</sup> כו' גם בשארי נשמו' ועולמו' שעולי' בכל חדש ושבת להשתחוו' לפני ה' כנ\"ל, וזהו יהללוך סלה וכל מקום שנא' סלה<sup data-n=\"107\">107</sup> הוא בלי הפסק לעולם כידוע. [אך* זהו בבחי' או\"י",[["104","104","<b>קדמון לכל הקדומים. . במ\"א בענין מגיד מראשית</b>: ע\"פ תקוני זהר תי\"ט (מב, א) ועוד. סה\"מ תקס\"ה ח\"א ע' רלא. ס' מאמרי אדה\"ז עה\"ת ח\"א ס\"ע רפג ואילך."],["105","105","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."],["106","106","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["107","107","<b>וכ\"מ שנאמר סלה</b>: ערובין נד, א."]]],[1900420029,"דחסדים בירידת אא\"ס בקו\"ח בהתפשטות למטה כנ\"ל, אבל בבחי' או\"ח בעליי' המ\"ל דא\"ס בעצמו ממש שלמעלה מהיות מקור להשתלשלות שם א' לך דומי' תהלה ונק' נורא תהלות כו'<sup data-n=\"108\">108</sup>].\n<b>וזהו</b> נפלאותיך ומחשבותיך אלינו<sup data-n=\"109\">109</sup> כו' עצמו מספר, דהיינו עילוי המדרגו' גם בנפלאו' דחכ' עילאה שבעצמו' א\"ס שנק' חכים ולא בחכ' ידיע' כלל פלא אחר פלא שזהו בהעלם אחר העלם ונק' סדכ\"ס כו', וכך הוא ענין מחשבותי\"ך ממש הסתומי\"ם ונעלמי' בהעלם דעצמות אא\"ס דהיינו בחי' מחשבה הסתומה שנק' מח' הקדומה כו' כל זה הוא למעלה למעלה מבחי' מקור לע\"ס הגלויו' באצי', וזהו עצמו מספ\"ר בדיבור וגם במחשבה כו', וכמו שא' דלית מחשבה תפיס' בך אפי' מח' דא\"ק<sup data-n=\"110\">110</sup> כו' שמקבל מראשית הקו\"ח כידוע, ושם א' לך דומי' תהל\"ה<sup data-n=\"111\">111</sup> ונק' נורא תהלות שאין תהלה ושבח מגיע שם כלל כי הוא למעלה מן הע\"ס, שאין השבח ותהלה שייך רק במה שבא לכלל השפעה לעולמו' להיות נקרא חכים ומבין ורחמן וחסדן כו' שזהו בע\"ס דאצי' באו\"כ דוקא, אבל למעלה מבחי' הקו\"ח שמובדל ומרומם לבדו ונק' סדכ\"ס דלמת\"ב אפי' מח' הכללי' דאנא אמלוך כו' (והוא בחי' ההתנשאו' שמצד עצמו ממש כנ\"ל), וזהו שא' דאפי' אור צח<sup data-n=\"112\">112</sup> ומצוחצח אוכם הוא לגבי עה\"ע כו' דהיינו אפי' אור קדמא' שהוא הקו\"ח אוכ\"ם לגבי מל' דא\"ס עצמו כנ\"ל, ואעפ\"כ במה שנמשך מבחי' נפלאותיך ומחשבותיך הנעלמי' בעצמו' אא\"ס אלינו ע\"י צמצום הראשון בקו\"ח כנ\"ל אע\"פ שלהגידם בדו\"מ עצמו מספר וכמ\"ש מי ימלל גבורו' ה'<sup data-n=\"113\">113</sup> כו' מ\"מ יוכלו הנשמו' לעלות במדרגו' זו למעלה מזו במה שמאיר משם אפס קצהו.\n<b>וזהו</b> משוב\"ח ומפוא\"ר בצמצומי' רבי' גם בנפלאו' הנ\"ל עדי עד בבחי' נצחיו' דא\"ס כענין הנ\"ל במ\"ש יהללוך סלה, אך השבח וההלל הוא בבחי' ביטול והתכללו' כמו לך ה' הגדולה והגבו'<sup data-n=\"114\">114</sup> כו', והוא מה שנכללי' הכל במל' דא\"ס עצמו שנק' שמ\"ו הגדו\"ל, כידוע שזהו שא' דקודם שנברא העולם הי' הוא ושמ\"ו בלבד שזהו בחי' גילוי אור העצמו' דא\"ס ב\"ה כמו שהוא יחיד לבדו כך",[["108","108","<b>אך זהו בבחי'. . נורא תהלות כו'</b>: פיסקא זו נמצאת רק בכתבי-יד מעתיקים של המאמר, ולא בגוכי\"ק אדהאמ\"צ. ועד\"ז עוד באיזה מקומות להלן בהמאמר שורות אחדות שניתוספו מכת\"י המעתיקים ואינם בגוכי\"ק [וגם לא נסמן בגוכי\"ק סימן להוספה במקומות אלו] — ראה להלן בהמ\"מ. ועד\"ז לעיל ע' שצב. [ואפשר הוא הוספת כ\"ק אדהאמ\"צ לאחר זמן ע\"ג דפים אחרים. ואי\"ז רגיל במאמרי אדהאמ\"צ]."],["109","109","<b>נפלאותיך ומחשבותיך אלינו</b>: תהלים מ, ו."],["110","110","<b>דלית מחשבה תפיסא בך אפי' מח' דא\"ק</b>: ע\"פ תקוני זהר בהקדמה ד\"ה פתח אליהו. ובס' הדרת מלך (קרוב לסופו בהפי' על פתח אליהו) מפרש: אפי' ח\"ס דא\"א אינה משגת כו'. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' שפב: כידוע המאמר דלית מחשבה תפיסא בי' כלל ואפי' מחשבה דא\"ק כו'. ועד\"ז מובא בכ\"מ."],["111","111","<b>לך דומי' תהלה</b>: תהלים סה, ב."],["112","112","<b>דאפי' אור צח כו'</b>: ראה תקו\"ז תיקון ע' (קלה, ב)."],["113","113","<b>מי ימלל גבורו' ה'</b>: תהלים קו, ב."],["114","114","<b>לך ה' הגדולה והגבו'</b>: דה\"א כט, יא."]]]]});
